eReplacement/missingNodeScan.ts","../../src/platform/missingModel/missingModelPipeline.ts","../../src/platform/missingMedia/missingMediaScan.ts","../../src/platform/missingMedia/missingMediaPipeline.ts","../../src/utils/migration/migrateReroute.ts","../../src/utils/vintageClipboard.ts","../../src/types/metadataTypes.ts","../../src/utils/fileUtil.ts","../../src/scripts/metadata/avif.ts","../../src/scripts/metadata/flac.ts","../../src/scripts/metadata/png.ts","../../src/scripts/pnginfo.ts","../../src/core/graph/subgraph/promotedWidgetControl.ts","../../src/platform/workflow/core/types/formats.ts","../../src/scripts/ui/dialog.ts","../../src/scripts/ui/settings.ts","../../src/scripts/ui/toggleSwitch.ts","../../src/scripts/ui.ts","../../src/scripts/ui/components/buttonGroup.ts","../../src/scripts/ui/components/button.ts","../../src/scripts/ui/components/popup.ts","../../src/scripts/ui/components/splitButton.ts","../../src/scripts/ui/components/asyncDialog.ts","../../src/scripts/ui/draggableList.ts","../../src/scripts/ui/menu/index.ts","../../src/renderer/core/layout/transform/graphRenderTransform.ts","../../src/renderer/extensions/vueNodes/layout/ensureCorrectLayoutScale.ts","../../src/scripts/metadata/ebml.ts","../../src/scripts/metadata/gltf.ts","../../src/scripts/metadata/isobmff.ts","../../src/scripts/metadata/json.ts","../../src/scripts/metadata/mp3.ts","../../src/scripts/metadata/ogg.ts","../../src/scripts/metadata/svg.ts","../../src/scripts/metadata/parser.ts","../../src/workbench/eventHelpers.ts","../../src/composables/useCopy.ts","../../src/composables/usePaste.ts","../../src/scripts/app.ts"],"sourcesContent":["import { useElementBounding } from '@vueuse/core'\n\nimport type { LGraphCanvas, Point } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nlet sharedConverter: ReturnType<typeof useCanvasPositionConversion> | null =\n  null\n\n/**\n * Convert between canvas and client positions\n * @param canvasElement - The canvas element\n * @param lgCanvas - The litegraph canvas\n * @returns The canvas position conversion functions\n */\nexport const useCanvasPositionConversion = (\n  canvasElement: Parameters<typeof useElementBounding>[0],\n  lgCanvas: LGraphCanvas\n) => {\n  const { left, top, update } = useElementBounding(canvasElement)\n\n  const clientPosToCanvasPos = (pos: Point): Point => {\n    const { offset, scale } = lgCanvas.ds\n    return [\n      (pos[0] - left.value) / scale - offset[0],\n      (pos[1] - top.value) / scale - offset[1]\n    ]\n  }\n\n  const canvasPosToClientPos = (pos: Point): Point => {\n    const { offset, scale } = lgCanvas.ds\n    return [\n      (pos[0] + offset[0]) * scale + left.value,\n      (pos[1] + offset[1]) * scale + top.value\n    ]\n  }\n\n  return {\n    clientPosToCanvasPos,\n    canvasPosToClientPos,\n    update\n  }\n}\n\nexport function useSharedCanvasPositionConversion() {\n  if (sharedConverter) return sharedConverter\n  const lgCanvas = useCanvasStore().getCanvas()\n  sharedConverter = useCanvasPositionConversion(lgCanvas.canvas, lgCanvas)\n  return sharedConverter\n}\n","import type { DragAndScaleState } from '@/lib/litegraph/src/DragAndScale'\nimport { clamp } from 'es-toolkit'\n\ninterface CameraScaleRange {\n  readonly minScale: number\n  readonly maxScale: number\n}\n\nconst defaultScaleRange: CameraScaleRange = { minScale: 0.1, maxScale: 10 }\n\nexport function normalizeCameraState(\n  value: unknown,\n  { minScale, maxScale }: CameraScaleRange = defaultScaleRange\n): DragAndScaleState | null {\n  if (\n    !value ||\n    typeof value !== 'object' ||\n    !('offset' in value) ||\n    !('scale' in value) ||\n    typeof value.offset !== 'object' ||\n    value.offset === null\n  ) {\n    return null\n  }\n\n  if (\n    '0' in value.offset &&\n    '1' in value.offset &&\n    typeof value.offset[0] === 'number' &&\n    Number.isFinite(value.offset[0]) &&\n    typeof value.offset[1] === 'number' &&\n    Number.isFinite(value.offset[1]) &&\n    typeof value.scale === 'number' &&\n    Number.isFinite(value.scale) &&\n    value.scale > 0\n  ) {\n    return {\n      offset: [value.offset[0], value.offset[1]],\n      scale: clamp(value.scale, minScale, maxScale)\n    }\n  }\n\n  return null\n}\n","/**\n * Thin performance instrumentation primitives.\n *\n * The browser Performance API records the marks and measures for local\n * inspection. Callers retain the returned measurements for structured reports.\n * Sentry breadcrumbs are a secondary consumer so a startup error carries the\n * phase timings that preceded it.\n */\nimport { addBreadcrumb } from '@sentry/vue'\n\nexport interface PerfSpan {\n  /** Wall-clock ms since navigationStart when mark() was called. */\n  startMs: number\n  /** Call stop() to end the span and record the measure. */\n  stop(): number\n}\n\nconst NOOP_PERF_SPAN: PerfSpan = {\n  startMs: 0,\n  stop: () => 0\n}\n\n/**\n * Begin a named performance span.\n *\n * Records a `performance.mark('<name>:start')`. Calling `stop()` records\n * `performance.mark('<name>:end')` + `performance.measure('<name>', ...)`,\n * adds a Sentry breadcrumb, and returns the elapsed milliseconds. Repeat\n * `stop()` calls return the first measured duration without re-recording.\n *\n * @example\n * const span = perfMark('bootstrap/object-info')\n * await this.getNodeDefs()\n * const ms = span.stop()\n */\nexport function perfMark(name: string): PerfSpan {\n  const startName = `${name}:start`\n  const endName = `${name}:end`\n\n  try {\n    performance.mark(startName)\n    const startMs = performance.now()\n    let durationMs: number | undefined\n\n    return {\n      startMs,\n      stop(): number {\n        if (durationMs !== undefined) return durationMs\n        try {\n          performance.mark(endName)\n          durationMs = _measure(name, startName, endName, startMs)\n          _emitToSentry(name, durationMs)\n          return durationMs\n        } catch {\n          durationMs = 0\n          return 0\n        }\n      }\n    }\n  } catch {\n    return NOOP_PERF_SPAN\n  }\n}\n\n/**\n * Mark a single point-in-time milestone (no duration).\n */\nexport function perfPoint(name: string): void {\n  try {\n    performance.mark(name)\n    _emitToSentry(name, 0)\n  } catch {\n    return\n  }\n}\n\nfunction _measure(\n  name: string,\n  startName: string,\n  endName: string,\n  fallbackStart: number\n): number {\n  try {\n    return performance.measure(name, startName, endName).duration\n  } catch {\n    return performance.now() - fallbackStart\n  }\n}\n\nfunction _emitToSentry(name: string, durationMs: number): void {\n  try {\n    // addBreadcrumb is a module-level function in @sentry/vue v10 — safe to\n    // call before Sentry.init() completes (it queues internally).\n    addBreadcrumb({\n      category: 'perf',\n      message: name,\n      level: 'info',\n      data: { duration_ms: durationMs }\n    })\n  } catch {\n    return\n  }\n}\n","/**\n * Structured performance tracing for the app startup/bootstrap sequence.\n *\n * Each phase maps to one of the known bottlenecks from profiling:\n *\n *   Phase                          | Typical range (cloud, Lighthouse)\n *   ───────────────────────────────┼──────────────────────────────────\n *   startup/remote-config          | ~0–0.5 s  (pre-Firebase, blocking)\n *   startup/telemetry-init         | ~0–0.3 s\n *   startup/firebase-init          | ~0–0.1 s\n *   startup/sentry-init            | ~0–0.1 s\n *   auth-gate/initialized          | variable  (Firebase session restore + timeout/retry)\n *   auth-gate/user-store           | ~0–2.5 s  (GET /api/user/*)\n *   auth-gate/needs-login          | ~0 s      (computed resolution)\n *   bootstrap/settings             | ~0.2 s    (parallel, non-blocking)\n *   bootstrap/workflows            | ~0.3 s    (parallel, non-blocking)\n *   bootstrap/extensions-load      | ~0.5 s    (fetch + import /extensions JS)\n *     ├ extensions-load-core       | subset    (core entry-point import)\n *     └ extensions-load-custom     | subset    (backend-provided extension imports)\n *   bootstrap/extensions-init      | ~0.3 s    (extension.init() hooks)\n *   bootstrap/object-info          | ~0.7 s    (GET /api/object_info)\n *   bootstrap/extensions           | ~0.5 s    (addCustomNodeDefs + registerCustomNodes)\n *   bootstrap/extensions-setup     | ~0.5 s    (extension.setup() hooks)\n *\n * The two `extensions-load-*` rows are nested inside `extensions-load` rather\n * than replacing it: the aggregate stays intact for the existing monitors, and\n * the residual (aggregate minus both children) is `api.getExtensions()` plus\n * bookkeeping. So read the children and the residual against the aggregate —\n * never sum rows across the flattened phase map, which would double-count\n * extension load time.\n *\n * These children add two to `phase_count` when both run, so thresholds based\n * on the old count must shift. Each duration is rounded independently, so the\n * residual can be off by a millisecond or two in either direction and can read\n * negative on a fast load. The phase map carries only the rounded values.\n *\n * Startup ends when the loading screen comes down, not when any one subsystem\n * finishes. `complete()` is therefore called from the single place that owns\n * that transition (`GraphCanvas`'s onMounted `finally`), so the trace covers\n * the extension and object-info phases that run inside `ComfyApp.setup()` and\n * so a startup that threw still reports. A startup that never gets there is\n * reported by `armWatchdog()`, armed from `main.ts` before blocking startup\n * work begins.\n *\n * Usage:\n *   import { bootstrapTracer } from '@/platform/telemetry/perf/bootstrapTracer'\n *\n *   await bootstrapTracer.settle('bootstrap/object-info', () => this.getNodeDefs())\n */\n// oxlint-disable-next-line no-restricted-imports -- startup telemetry must publish before the registry exists\nimport { datadogRum } from '@datadog/browser-rum'\n\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { TelemetryEvents } from '@/platform/telemetry/types'\nimport type { BootstrapCompleteMetadata } from '@/platform/telemetry/types'\n\nimport { perfMark, perfPoint } from './perfMark'\nimport type { PerfSpan } from './perfMark'\n\n/**\n * Startup past this is abnormal by any reading — the slowest healthy cloud\n * load profiled is ~5 s, and the reports that prompted this instrumentation\n * were minutes.\n */\nconst BOOTSTRAP_WATCHDOG_MS = 30_000\n\nfunction toRumTimingName(name: string): string {\n  return name.replace(/\\//g, '.')\n}\n\nconst BOOTSTRAP_PHASES = {\n  startup: ['remote-config', 'telemetry-init', 'firebase-init', 'sentry-init'],\n  'auth-gate': ['initialized', 'user-store', 'needs-login'],\n  bootstrap: [\n    'settings',\n    'workflows',\n    'extensions-load',\n    'extensions-load-core',\n    'extensions-load-custom',\n    'extensions-init',\n    'object-info',\n    'extensions',\n    'extensions-setup'\n  ]\n} as const satisfies Record<string, readonly string[]>\n\ntype BootstrapPhaseNamespace = keyof typeof BOOTSTRAP_PHASES\n\ntype BootstrapSubphase<Namespace extends BootstrapPhaseNamespace> =\n  (typeof BOOTSTRAP_PHASES)[Namespace][number]\n\nexport type BootstrapPhase = {\n  [Namespace in BootstrapPhaseNamespace]: `${Namespace}/${BootstrapSubphase<Namespace>}`\n}[BootstrapPhaseNamespace]\n\nexport interface BootstrapPhaseTiming {\n  name: BootstrapPhase\n  startMs: number\n  durationMs: number\n}\n\nexport class BootstrapTracer {\n  private _spans = new Map<BootstrapPhase, PerfSpan>()\n  private _timings: BootstrapPhaseTiming[] = []\n  private _completed = false\n  private _watchdog: ReturnType<typeof setTimeout> | undefined\n\n  /**\n   * Start timing a phase. Returns a handle; call `.stop()` when complete.\n   * Calling startPhase for the same phase twice is safe (second call is a no-op\n   * and returns the existing span's handle).\n   */\n  startPhase(phase: BootstrapPhase): { stop: () => number } {\n    if (this._spans.has(phase)) {\n      // Already running — return a no-op handle so callers don't have to guard\n      return { stop: () => 0 }\n    }\n    this._spans.set(phase, perfMark(phase))\n    return { stop: () => this._stopPhase(phase) }\n  }\n\n  private _stopPhase(phase: BootstrapPhase): number {\n    const span = this._spans.get(phase)\n    if (!span) return 0\n    this._spans.delete(phase)\n    const durationMs = span.stop()\n    this._publishRumTiming(phase)\n    this._timings.push({\n      name: phase,\n      startMs: Math.round(span.startMs),\n      durationMs: Math.round(durationMs)\n    })\n    return durationMs\n  }\n\n  /**\n   * Time `work` and record the phase whether it resolves or rejects, then\n   * re-settle exactly as `work` did.\n   *\n   * A phase stopped only on the success path goes unrecorded precisely when\n   * startup went wrong, so the surviving sessions are the fast ones and every\n   * percentile reads better than reality.\n   */\n  async settle<T>(phase: BootstrapPhase, work: () => Promise<T>): Promise<T> {\n    const span = this.startPhase(phase)\n    try {\n      return await work()\n    } finally {\n      span.stop()\n    }\n  }\n\n  /**\n   * Record a named milestone with no duration (e.g. \"app shell mounted\").\n   */\n  milestone(name: string): void {\n    const milestoneName = `bootstrap/milestone/${name}`\n    perfPoint(milestoneName)\n    this._publishRumTiming(milestoneName)\n  }\n\n  private _publishRumTiming(name: string): void {\n    if (isCloud) datadogRum.addTiming(toRumTimingName(name))\n  }\n\n  /**\n   * Completed phases, in the order they started.\n   *\n   * Built from what this tracer measured rather than re-scanned out of\n   * `performance.getEntriesByType('measure')`: that buffer is shared with\n   * every other measure in the app and can be cleared by anyone.\n   */\n  summary(): BootstrapPhaseTiming[] {\n    return [...this._timings].sort((a, b) => a.startMs - b.startMs)\n  }\n\n  /**\n   * Close out startup: stop any phase still open, emit one aggregate event\n   * carrying total wall-clock and the per-phase breakdown, and log the trace\n   * locally. Idempotent — only the first call reports.\n   */\n  complete(outcome: 'completed' | 'failed' = 'completed'): void {\n    if (this._completed) return\n    this._completed = true\n    clearTimeout(this._watchdog)\n    for (const phase of Array.from(this._spans.keys())) this._stopPhase(phase)\n    this._report(outcome)\n  }\n\n  /**\n   * Report startup as still running if it has not completed by `deadlineMs`.\n   *\n   * A session that hangs never reaches `complete()`, so without this the loads\n   * users actually report — the ones that spin for minutes — are the only ones\n   * that produce no data at all. The watchdog row does not end the trace: the\n   * terminal row still follows if startup eventually finishes.\n   */\n  armWatchdog(deadlineMs = BOOTSTRAP_WATCHDOG_MS): void {\n    clearTimeout(this._watchdog)\n    this._watchdog = setTimeout(() => {\n      if (this._completed) return\n      this._report('timed_out', [...this._spans.keys()])\n    }, deadlineMs)\n  }\n\n  private _report(\n    outcome: BootstrapCompleteMetadata['outcome'],\n    pending?: BootstrapPhase[]\n  ): void {\n    try {\n      const totalMs = Math.round(performance.now())\n      const rows = this.summary()\n      const metadata: BootstrapCompleteMetadata = {\n        total_ms: totalMs,\n        outcome,\n        phase_count: rows.length,\n        phases: Object.fromEntries(rows.map((r) => [r.name, r.durationMs])),\n        ...(pending?.length ? { pending } : {})\n      }\n      if (isCloud) {\n        datadogRum.addAction(TelemetryEvents.BOOTSTRAP_COMPLETE, metadata)\n      }\n      useTelemetry()?.trackBootstrapComplete(metadata)\n      if (isCloud && outcome === 'completed') datadogRum.setViewLoadingTime()\n      this._logSummary(rows, totalMs)\n    } catch {\n      return\n    }\n  }\n\n  /**\n   * Log the startup summary to the console in a compact table.\n   * Only emits in dev or when DEBUG_PERF is set.\n   */\n  private _logSummary(rows: BootstrapPhaseTiming[], totalMs: number): void {\n    if (!import.meta.env.DEV && localStorage.getItem('DEBUG_PERF') !== 'true')\n      return\n    if (rows.length === 0) return\n    console.warn(\n      '[Bootstrap] Startup trace\\n' +\n        rows\n          .map((r) => `  ${r.startMs}ms  ${r.name}: ${r.durationMs}ms`)\n          .join('\\n') +\n        `\\n  Total wall-clock: ${totalMs}ms`\n    )\n  }\n}\n\n/** Singleton tracer — import and use directly. */\nexport const bootstrapTracer = new BootstrapTracer()\n","import type { NodeAddSource } from '../types'\n\nlet currentSource: NodeAddSource = 'unknown'\n\nexport function getCurrentNodeAddSource(): NodeAddSource {\n  return currentSource\n}\n\n/**\n * Set the node-add source for the duration of `fn`. Synchronous only —\n * the source is read by the synchronous LGraph.onNodeAdded callback that\n * fires inside `graph.add()`. Nesting restores the previous value on exit.\n */\nexport function withNodeAddSource<T>(source: NodeAddSource, fn: () => T): T {\n  const previous = currentSource\n  currentSource = source\n  try {\n    return fn()\n  } finally {\n    currentSource = previous\n  }\n}\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { ChangeTracker } from '@/scripts/changeTracker'\n\nimport { useTelemetry } from '..'\nimport { getCurrentNodeAddSource } from './nodeAddSource'\n\n/**\n * Wire `app:node_added_to_workflow` telemetry into a graph. Bulk additions\n * during workflow load are skipped — `workflow_imported` already covers those.\n */\nexport function installNodeAddedTelemetry(graph: LGraph): void {\n  graph.events.addEventListener('node:added', ({ detail: { node } }) => {\n    if (ChangeTracker.isLoadingGraph) return\n    useTelemetry()?.trackNodeAdded({\n      node_type: node.type,\n      source: getCurrentNodeAddSource()\n    })\n  })\n}\n","import type { MissingNodeType } from '@/platform/nodeReplacement/types'\n\nimport type { MissingNodePack } from '../types'\n\nconst UNKNOWN_PACK_ID = 'unknown'\n\nexport function groupMissingNodesByPack(\n  missingNodes: readonly MissingNodeType[]\n): MissingNodePack[] {\n  const byPack = new Map<string, Set<string>>()\n\n  for (const node of missingNodes) {\n    const type = typeof node === 'string' ? node : node.type\n    const packId =\n      typeof node === 'string' ? UNKNOWN_PACK_ID : node.cnrId || UNKNOWN_PACK_ID\n\n    const existing = byPack.get(packId)\n    if (existing) {\n      existing.add(type)\n    } else {\n      byPack.set(packId, new Set([type]))\n    }\n  }\n\n  return Array.from(byPack, ([pack_id, types]) => ({\n    pack_id,\n    node_types: Array.from(types)\n  }))\n}\n","import type {\n  ExecutionContext,\n  WorkflowExecutionContext\n} from '@/platform/telemetry/types'\nimport type { AppMode } from '@/utils/appMode'\n\ninterface WorkflowExecutionContextOptions {\n  executableNodeCount: number\n  executionScope: WorkflowExecutionContext['execution_scope']\n  viewMode: AppMode\n}\n\nexport function toWorkflowExecutionContext(\n  executionContext: ExecutionContext,\n  {\n    executableNodeCount,\n    executionScope,\n    viewMode\n  }: WorkflowExecutionContextOptions\n): WorkflowExecutionContext {\n  return {\n    workflow_type: executionContext.is_template ? 'template' : 'custom',\n    view_mode: viewMode,\n    execution_scope: executionScope,\n    total_node_count: executionContext.total_node_count,\n    executable_node_count: executableNodeCount,\n    custom_node_count: executionContext.custom_node_count,\n    api_node_count: executionContext.api_node_count,\n    subgraph_count: executionContext.subgraph_count\n  }\n}\n","import type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { ComfyApiWorkflow } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { ComfyInputsSpec } from '@/schemas/nodeDefSchema'\nimport {\n  zDynamicComboInputSpec,\n  zDynamicGroupInputSpec\n} from '@/schemas/nodeDefSchema'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\nexport function restoreDynamicGroupInputs(\n  node: LGraphNode,\n  inputs: ComfyApiWorkflow[string]['inputs']\n) {\n  const definition = useNodeDefStore().fromLGraphNode(node)\n  const names = new Map<string, string>()\n  const restoredCombos = new Set<string>()\n  const groups: string[] = []\n\n  function restore(specs: ComfyInputsSpec, prefix = '') {\n    for (const [key, spec] of Object.entries({\n      ...specs.required,\n      ...specs.optional\n    })) {\n      const name = `${prefix}${key}`\n      const controller = node.widgets?.find((widget) => widget.name === name)\n      if (!controller) continue\n      const combo = zDynamicComboInputSpec.safeParse(spec).data\n      if (combo) {\n        const selected = combo[1].options.find(\n          (option) => option.key === inputs[name]\n        )\n        if (selected) {\n          controller.value = selected.key\n          controller.callback?.(selected.key)\n          restoredCombos.add(name)\n          restore(selected.inputs, `${name}.`)\n        }\n        continue\n      }\n      const group = zDynamicGroupInputSpec.safeParse(spec).data\n      if (!group) continue\n      groups.push(name)\n      const fields = {\n        ...group[1].template.required,\n        ...group[1].template.optional\n      }\n      restoreRows(name, fields, controller)\n    }\n  }\n\n  function restoreRows(\n    name: string,\n    fields: Record<string, unknown>,\n    controller: IBaseWidget\n  ) {\n    const rows = new Map<string, number>()\n    for (const input of Object.keys(inputs)) {\n      if (!input.startsWith(`${name}.`)) continue\n      const suffix = input.slice(name.length + 1)\n      const separator = suffix.indexOf('.')\n      if (separator === -1) continue\n      const index = suffix.slice(0, separator)\n      const field = suffix.slice(separator + 1)\n      if (!/^(0|[1-9][0-9]*)$/.test(index) || !Object.hasOwn(fields, field))\n        continue\n      if (!rows.has(index)) rows.set(index, rows.size)\n      names.set(input, `${name}.${rows.get(index)}.${field}`)\n    }\n    controller.value = rows.size\n  }\n\n  if (definition) restore(definition.input)\n  return Object.fromEntries(\n    Object.entries(inputs)\n      .filter(\n        ([name]) =>\n          !restoredCombos.has(name) &&\n          (names.has(name) ||\n            !groups.some(\n              (group) => name === group || name.startsWith(`${group}.`)\n            ))\n      )\n      .map(([name, value]) => [names.get(name) ?? name, value])\n  )\n}\n","/**\n * This code is adapted from rgthree-comfy's link_fixer.ts\n * @see https://github.com/rgthree/rgthree-comfy/blob/b84f39c7c224de765de0b54c55b967329011819d/src_web/common/link_fixer.ts\n *\n * MIT License\n *\n * Copyright (c) 2023 Regis Gaughan, III (rgthree)\n *\n * Permission is hereby granted, free of charge, to any person obtaining a copy\n * of this software and associated documentation files (the \"Software\"), to deal\n * in the Software without restriction, including without limitation the rights\n * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n * copies of the Software, and to permit persons to whom the Software is\n * furnished to do so, subject to the following conditions:\n *\n * The above copyright notice and this permission notice shall be included in all\n * copies or substantial portions of the Software.\n *\n * THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n * OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n * SOFTWARE.\n */\nimport type { INodeOutputSlot } from '@/lib/litegraph/src/types/slots'\nimport { NodeInputSlot } from '@/lib/litegraph/src/node/NodeInputSlot'\nimport { NodeOutputSlot } from '@/lib/litegraph/src/node/NodeOutputSlot'\nimport { outputLinkIds } from '@/lib/litegraph/src/node/slotLinks'\nimport { toLinkId } from '@/types/linkId'\nimport { parseNodeId } from '@/types/nodeId'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport type { SerialisedLLinkArray } from '@/lib/litegraph/src/LLink'\nimport type { LGraph, LGraphNode, LLink } from '@/lib/litegraph/src/litegraph'\nimport type {\n  ISerialisedGraph,\n  ISerialisedNode\n} from '@/lib/litegraph/src/types/serialisation'\n\ntype FixableSerialisedGraph = Omit<ISerialisedGraph, 'links'> & {\n  links: (SerialisedLLinkArray | null)[]\n}\n\ninterface BadLinksData<T = FixableSerialisedGraph | LGraph> {\n  hasBadLinks: boolean\n  fixed: boolean\n  graph: T\n  patched: number\n  deleted: number\n}\n\nenum IoDirection {\n  INPUT,\n  OUTPUT\n}\n\nfunction isLiveGraph(graph: FixableSerialisedGraph | LGraph): graph is LGraph {\n  return 'getNodeById' in graph\n}\n\nfunction getNodeById(\n  graph: FixableSerialisedGraph | LGraph,\n  id: SerializedNodeId\n) {\n  if (isLiveGraph(graph)) {\n    const parsedNodeId = parseNodeId(id)\n    return parsedNodeId ? graph.getNodeById(parsedNodeId) : null\n  }\n  return graph.nodes.find((node: ISerialisedNode) => node.id == id)!\n}\n\nfunction outputLinkIdsOf(\n  node: ISerialisedNode | LGraphNode,\n  slot: number\n): readonly number[] | undefined {\n  const slotData = node.outputs?.[slot]\n  if (!slotData) return undefined\n  if (!(slotData instanceof NodeOutputSlot)) return slotData.links ?? undefined\n\n  const { graph, id } = slotData.node\n  if (!graph) return undefined\n  const ids = outputLinkIds(graph, id, slot)\n  return ids.length ? ids : undefined\n}\n\nfunction extendLink(link: SerialisedLLinkArray) {\n  return {\n    link: link,\n    id: link[0],\n    origin_id: link[1],\n    origin_slot: link[2],\n    target_id: link[3],\n    target_slot: link[4],\n    type: link[5]\n  }\n}\n\n/**\n * Takes a ISerialisedGraph or live LGraph and inspects the links and nodes to ensure the linking\n * makes logical sense. Can apply fixes when passed the `fix` argument as true.\n *\n * Note that fixes are a best-effort attempt. Seems to get it correct in most cases, but there is a\n * chance it correct an anomaly that results in placing an incorrect link (say, if there were two\n * links in the data). Users should take care to not overwrite work until manually checking the\n * result.\n */\nexport function fixBadLinks(\n  graph: FixableSerialisedGraph | LGraph,\n  options: {\n    fix?: boolean\n    silent?: boolean\n    logger?: { log: (...args: unknown[]) => void }\n  } = {}\n): BadLinksData {\n  const { fix = false, silent = false, logger: _logger = console } = options\n  const logger = {\n    log: (...args: unknown[]) => {\n      if (!silent) {\n        _logger.log(...args)\n      }\n    }\n  }\n\n  const patchedNodeSlots: {\n    [nodeId: string]:\n      | {\n          inputs?: { [slot: number]: number | null | undefined }\n          outputs?: {\n            [slots: number]:\n              | {\n                  links: number[]\n                  changes: {\n                    [linkId: number]: 'ADD' | 'REMOVE' | undefined\n                  }\n                }\n              | undefined\n          }\n        }\n      | undefined\n  } = {}\n\n  const data: {\n    patchedNodes: Array<ISerialisedNode | LGraphNode>\n    deletedLinks: number[]\n  } = {\n    patchedNodes: [],\n    deletedLinks: []\n  }\n\n  /**\n   * Internal patch node. We keep track of changes in patchedNodeSlots in case we're in a dry run.\n   */\n  function patchNodeSlot(\n    node: ISerialisedNode | LGraphNode,\n    ioDir: IoDirection,\n    slot: number,\n    linkId: number,\n    op: 'ADD' | 'REMOVE'\n  ) {\n    const patchedNode = patchedNodeSlots[node.id] ?? {}\n    patchedNodeSlots[node.id] = patchedNode\n    if (ioDir == IoDirection.INPUT) {\n      patchedNode['inputs'] = patchedNode['inputs'] || {}\n      // We can set to null (delete), so undefined means we haven't set it at all.\n      if (patchedNode['inputs'][slot] !== undefined) {\n        logger.log(\n          ` > Already set ${node.id}.inputs[${slot}] to ${\n            patchedNode['inputs'][slot]!\n          } Skipping.`\n        )\n        return false\n      }\n      const linkIdToSet = op === 'REMOVE' ? null : linkId\n      const inputSlot = node.inputs?.[slot]\n      if (fix && !inputSlot) {\n        logger.log(\n          ` > Cannot patch ${node.id}.inputs[${slot}] because the input slot is missing.`\n        )\n        return false\n      }\n      patchedNode['inputs'][slot] = linkIdToSet\n      // Live NodeInputSlot mirrors are store-derived and need no repair;\n      // only serialized plain slots carry a writable link field.\n      if (fix && !(inputSlot instanceof NodeInputSlot)) {\n        const writable = inputSlot as { link?: number | null }\n        writable.link = linkIdToSet\n      }\n    } else {\n      patchedNode['outputs'] = patchedNode['outputs'] || {}\n      patchedNode['outputs'][slot] = patchedNode['outputs'][slot] || {\n        links: [...(outputLinkIdsOf(node, slot) ?? [])],\n        changes: {}\n      }\n      if (patchedNode['outputs'][slot]['changes'][linkId] !== undefined) {\n        logger.log(\n          ` > Already set ${node.id}.outputs[${slot}] to ${\n            patchedNode['inputs']![slot]\n          }! Skipping.`\n        )\n        return false\n      }\n      patchedNode['outputs'][slot]['changes'][linkId] = op\n      if (op === 'ADD') {\n        const linkIdIndex =\n          patchedNode['outputs'][slot]['links'].indexOf(linkId)\n        if (linkIdIndex !== -1) {\n          logger.log(\n            ` > Hmmm.. asked to add ${linkId} but it is already in list...`\n          )\n          return false\n        }\n        patchedNode['outputs'][slot]['links'].push(linkId)\n        // Live NodeOutputSlot mirrors are store-derived and need no repair;\n        // only serialized plain slots carry a writable links array.\n        if (fix && !(node.outputs?.[slot] instanceof NodeOutputSlot)) {\n          node.outputs = node.outputs || []\n          const slotData = (node.outputs[slot] ??=\n            {} satisfies Partial<INodeOutputSlot> as INodeOutputSlot)\n          const writable = slotData as { links?: number[] | null }\n          writable.links = writable.links || []\n          writable.links.push(linkId)\n        }\n      } else {\n        const linkIdIndex =\n          patchedNode['outputs'][slot]['links'].indexOf(linkId)\n        if (linkIdIndex === -1) {\n          logger.log(\n            ` > Hmmm.. asked to remove ${linkId} but it doesn't exist...`\n          )\n          return false\n        }\n        patchedNode['outputs'][slot]['links'].splice(linkIdIndex, 1)\n        if (fix && !(node.outputs?.[slot] instanceof NodeOutputSlot)) {\n          const writable = node.outputs?.[slot] as { links?: number[] | null }\n          writable.links?.splice(linkIdIndex, 1)\n        }\n      }\n    }\n    data.patchedNodes.push(node)\n    return true\n  }\n\n  /**\n   * Internal to check if a node (or patched data) has a linkId.\n   */\n  function nodeHasLinkId(\n    node: ISerialisedNode | LGraphNode,\n    ioDir: IoDirection,\n    slot: number,\n    linkId: number\n  ) {\n    // Patched data should be canonical. We can double check if fixing too.\n    let has: boolean\n    const patchedNode = patchedNodeSlots[node.id]\n    if (ioDir === IoDirection.INPUT) {\n      const nodeHasIt = node.inputs?.[slot]?.link === linkId\n      if (patchedNode?.inputs) {\n        const patchedHasIt = patchedNode.inputs[slot] === linkId\n        // If we're fixing, double check that node matches.\n        if (fix && nodeHasIt !== patchedHasIt) {\n          throw Error('Error. Expected node to match patched data.')\n        }\n        has = patchedHasIt\n      } else {\n        has = nodeHasIt\n      }\n    } else {\n      const nodeHasIt = outputLinkIdsOf(node, slot)?.includes(toLinkId(linkId))\n      const patchedOutput = patchedNode?.outputs?.[slot]\n      if (patchedOutput?.changes[linkId]) {\n        const patchedHasIt = patchedOutput.links.includes(linkId)\n        // If we're fixing, double check that node matches.\n        if (fix && nodeHasIt !== patchedHasIt) {\n          throw Error('Error. Expected node to match patched data.')\n        }\n        has = patchedHasIt\n      } else {\n        has = !!nodeHasIt\n      }\n    }\n    return has\n  }\n\n  /**\n   * Internal to check if a node (or patched data) has a linkId.\n   */\n  function nodeHasAnyLink(\n    node: ISerialisedNode | LGraphNode,\n    ioDir: IoDirection,\n    slot: number\n  ) {\n    // Patched data should be canonical. We can double check if fixing too.\n    let hasAny: boolean\n    const patchedNode = patchedNodeSlots[node.id]\n    if (ioDir === IoDirection.INPUT) {\n      const nodeHasAny = node.inputs?.[slot]?.link != null\n      if (patchedNode?.inputs) {\n        const patchedHasAny = patchedNode.inputs[slot] != null\n        // If we're fixing, double check that node matches.\n        if (fix && nodeHasAny !== patchedHasAny) {\n          throw Error('Error. Expected node to match patched data.')\n        }\n        hasAny = patchedHasAny\n      } else {\n        hasAny = nodeHasAny\n      }\n    } else {\n      const nodeHasAny = outputLinkIdsOf(node, slot)?.length\n      const patchedOutput = patchedNode?.outputs?.[slot]\n      if (patchedOutput?.changes) {\n        const patchedHasAny = patchedOutput.links.length\n        // If we're fixing, double check that node matches.\n        if (fix && nodeHasAny !== patchedHasAny) {\n          throw Error('Error. Expected node to match patched data.')\n        }\n        hasAny = !!patchedHasAny\n      } else {\n        hasAny = !!nodeHasAny\n      }\n    }\n    return hasAny\n  }\n\n  const links: Array<SerialisedLLinkArray | LLink | null> = isLiveGraph(graph)\n    ? Array.from(graph.links.values())\n    : graph.links\n\n  const linksReverse = [...links]\n  linksReverse.reverse()\n  for (const l of linksReverse) {\n    if (!l) continue\n    const link = !Array.isArray(l) ? l : extendLink(l)\n\n    const originNode = getNodeById(graph, link.origin_id)\n    const originHasLink = () =>\n      nodeHasLinkId(originNode!, IoDirection.OUTPUT, link.origin_slot, link.id)\n    const patchOrigin = (op: 'ADD' | 'REMOVE', id = link.id) =>\n      patchNodeSlot(originNode!, IoDirection.OUTPUT, link.origin_slot, id, op)\n\n    const targetNode = getNodeById(graph, link.target_id)\n    const targetHasLink = () =>\n      nodeHasLinkId(targetNode!, IoDirection.INPUT, link.target_slot, link.id)\n    const targetHasAnyLink = () =>\n      nodeHasAnyLink(targetNode!, IoDirection.INPUT, link.target_slot)\n    const patchTarget = (op: 'ADD' | 'REMOVE', id = link.id) =>\n      patchNodeSlot(targetNode!, IoDirection.INPUT, link.target_slot, id, op)\n\n    const originLog = `origin(${link.origin_id}).outputs[${link.origin_slot}].links`\n    const targetLog = `target(${link.target_id}).inputs[${link.target_slot}].link`\n\n    if (!originNode || !targetNode) {\n      if (!originNode && !targetNode) {\n        logger.log(\n          `Link ${link.id} is invalid, ` +\n            `both origin ${link.origin_id} and target ${link.target_id} do not exist`\n        )\n      } else if (!originNode) {\n        logger.log(\n          `Link ${link.id} is funky... ` +\n            `origin ${link.origin_id} does not exist, but target ${link.target_id} does.`\n        )\n        if (targetHasLink()) {\n          logger.log(\n            ` > [PATCH] ${targetLog} does have link, will remove the inputs' link first.`\n          )\n          patchTarget('REMOVE', -1)\n        }\n      } else if (!targetNode) {\n        logger.log(\n          `Link ${link.id} is funky... ` +\n            `target ${link.target_id} does not exist, but origin ${link.origin_id} does.`\n        )\n        if (originHasLink()) {\n          logger.log(\n            ` > [PATCH] Origin's links' has ${link.id}; will remove the link first.`\n          )\n          patchOrigin('REMOVE')\n        }\n      }\n      continue\n    }\n\n    if (targetHasLink() || originHasLink()) {\n      if (!originHasLink()) {\n        logger.log(\n          `${link.id} is funky... ${originLog} does NOT contain it, but ${targetLog} does.`\n        )\n\n        logger.log(\n          ` > [PATCH] Attempt a fix by adding this ${link.id} to ${originLog}.`\n        )\n        patchOrigin('ADD')\n      } else if (!targetHasLink()) {\n        logger.log(\n          `${link.id} is funky... ${targetLog} is NOT correct (is ${\n            targetNode.inputs?.[link.target_slot]?.link\n          }), but ${originLog} contains it`\n        )\n        if (!targetHasAnyLink()) {\n          logger.log(\n            ` > [PATCH] ${targetLog} is not defined, will set to ${link.id}.`\n          )\n          const patched = patchTarget('ADD')\n          if (!patched) {\n            logger.log(\n              ` > [PATCH] Nvm, ${targetLog} already patched. Removing ${link.id} from ${originLog}.`\n            )\n            patchOrigin('REMOVE')\n          }\n        } else {\n          logger.log(\n            ` > [PATCH] ${targetLog} is defined, removing ${link.id} from ${originLog}.`\n          )\n          patchOrigin('REMOVE')\n        }\n      }\n    }\n  }\n\n  // Now that we've cleaned up the inputs, outputs, run through it looking for dangling links.,\n  for (const l of linksReverse) {\n    if (!l) continue\n    const link = !Array.isArray(l) ? l : extendLink(l)\n    const originNode = getNodeById(graph, link.origin_id)\n    const targetNode = getNodeById(graph, link.target_id)\n    // Now that we've manipulated the linking, check again if they both exist.\n    if (\n      (!originNode ||\n        !nodeHasLinkId(\n          originNode,\n          IoDirection.OUTPUT,\n          link.origin_slot,\n          link.id\n        )) &&\n      (!targetNode ||\n        !nodeHasLinkId(\n          targetNode,\n          IoDirection.INPUT,\n          link.target_slot,\n          link.id\n        ))\n    ) {\n      logger.log(\n        `${link.id} is def invalid; BOTH origin node ${link.origin_id} ${\n          !originNode ? 'is removed' : `doesn't have ${link.id}`\n        } and ${link.origin_id} target node ${\n          !targetNode ? 'is removed' : `doesn't have ${link.id}`\n        }.`\n      )\n      data.deletedLinks.push(link.id)\n      continue\n    }\n  }\n\n  // If we're fixing, then we've been patching along the way. Now go through and actually delete\n  // the zombie links from `app.graph.links`\n  if (fix) {\n    for (let i = data.deletedLinks.length - 1; i >= 0; i--) {\n      logger.log(`Deleting link #${data.deletedLinks[i]}.`)\n      if (isLiveGraph(graph)) {\n        graph._removeLink(toLinkId(data.deletedLinks[i]))\n      } else {\n        const links = graph.links\n        // Sometimes we got objects for links if passed after ComfyUI's loadGraphData modifies the\n        // data. We make a copy now, but can handle the bastardized objects just in case.\n        const idx = links.findIndex(\n          (l) =>\n            l != null &&\n            (l[0] === data.deletedLinks[i] ||\n              ('id' in l && l.id === data.deletedLinks[i]))\n        )\n        if (idx === -1) {\n          logger.log(`INDEX NOT FOUND for #${data.deletedLinks[i]}`)\n        }\n        logger.log(`splicing ${idx} from links`)\n        links.splice(idx, 1)\n      }\n    }\n    // If we're a serialized graph, we can filter out the links because it's just an array.\n    if (!isLiveGraph(graph)) {\n      graph.links = graph.links.filter((link) => link !== null)\n    }\n  }\n  if (!data.patchedNodes.length && !data.deletedLinks.length) {\n    return {\n      hasBadLinks: false,\n      fixed: false,\n      graph,\n      patched: data.patchedNodes.length,\n      deleted: data.deletedLinks.length\n    }\n  }\n\n  logger.log(\n    `${fix ? 'Made' : 'Would make'} ${data.patchedNodes.length || 'no'} node link patches, and ${\n      data.deletedLinks.length || 'no'\n    } stale link removals.`\n  )\n\n  const hasChanges = !!(data.patchedNodes.length || data.deletedLinks.length)\n  let hasBadLinks: boolean = hasChanges\n  // If we're fixing, then let's run it again to see if there are no more bad links.\n  if (fix) {\n    const rerun = fixBadLinks(graph, { fix: false, silent: true })\n    hasBadLinks = rerun.hasBadLinks\n  }\n\n  return {\n    hasBadLinks,\n    fixed: fix && hasChanges && !hasBadLinks,\n    graph,\n    patched: data.patchedNodes.length,\n    deleted: data.deletedLinks.length\n  }\n}\n","import type { ISerialisedGraph } from '@/lib/litegraph/src/types/serialisation'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { t } from '@/i18n'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { validateComfyWorkflow } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { fixBadLinks } from '@/utils/linkFixer'\n\ninterface ValidationResult {\n  graphData: ComfyWorkflowJSON | null\n}\n\nexport function useWorkflowValidation() {\n  const toast = useToast()\n\n  function tryFixLinks(\n    graphData: ComfyWorkflowJSON,\n    options: { silent?: boolean } = {}\n  ) {\n    const { silent = false } = options\n\n    // Collect all logs in an array\n    const logs: string[] = []\n    // Then validate and fix links if schema validation passed\n    const linkValidation = fixBadLinks(graphData as ISerialisedGraph, {\n      fix: true,\n      silent,\n      logger: {\n        log: (...args: unknown[]) => {\n          logs.push(args.join(' '))\n        }\n      }\n    })\n\n    if (!silent && logs.length > 0) {\n      toast.warning(t('toastMessages.workflowValidationTitle'), {\n        description: logs.join('\\n')\n      })\n    }\n\n    // If links were fixed, notify the user\n    if (linkValidation.fixed) {\n      if (!silent) {\n        toast.success(t('toastMessages.workflowLinksFixedTitle'), {\n          description: t('toastMessages.workflowLinksFixed', {\n            patched: linkValidation.patched,\n            deleted: linkValidation.deleted\n          })\n        })\n      }\n    }\n\n    return linkValidation.graph\n  }\n\n  /**\n   * Validates a workflow, including link validation and schema validation\n   */\n  async function validateWorkflow(\n    graphData: ComfyWorkflowJSON,\n    options: {\n      silent?: boolean\n    } = {}\n  ): Promise<ValidationResult> {\n    const { silent = false } = options\n\n    let validatedData: ComfyWorkflowJSON | null = null\n\n    // First do schema validation\n    const validatedGraphData = await validateComfyWorkflow(\n      graphData,\n      /* onError=*/ (err) => {\n        if (!silent) {\n          toast.warning(err)\n        }\n      }\n    )\n\n    if (validatedGraphData) {\n      try {\n        validatedData = tryFixLinks(validatedGraphData, {\n          silent\n        }) as ComfyWorkflowJSON\n      } catch (err) {\n        // Link fixer itself is throwing an error\n        console.error(err)\n      }\n    }\n\n    return {\n      graphData: validatedData\n    }\n  }\n\n  return {\n    validateWorkflow\n  }\n}\n","import { useBillingContext } from '@/composables/billing/useBillingContext'\nimport type { AccountPrecondition } from '@/platform/errorCatalog/accountPreconditionRouting'\nimport type { PaymentIntentSource } from '@/platform/telemetry/types'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\n\ninterface AccountPreconditionContext {\n  /** Node type that triggered the precondition, used as modal context. */\n  nodeType?: string\n  source?: PaymentIntentSource\n}\n\n// Routes a resolved account precondition to its dedicated modal. This is the\n// single seam where FE-978 attaches role-aware (member vs owner) subscription\n// content: the `subscription` branch resolves to the subscription dialog, whose\n// inner content FE-978 specializes for cancelled/inactive team states.\nexport function useAccountPreconditionDialog() {\n  const { showApiNodesSignInDialog } = useAuthDialogs()\n  const { showSubscriptionRequiredDialog, showTopUpCreditsDialog } =\n    useBillingDialogs()\n\n  function open(\n    precondition: AccountPrecondition,\n    context: AccountPreconditionContext = {}\n  ): void {\n    switch (precondition) {\n      case 'sign_in':\n        void showApiNodesSignInDialog(\n          context.nodeType ? [context.nodeType] : []\n        )\n        return\n      case 'subscription':\n        void showSubscriptionRequiredDialog({\n          reason: context.source ?? 'subscription_required'\n        })\n        return\n      case 'credits': {\n        // The server just declared the balance exhausted; there is no push or\n        // polling for billing state, so refresh it here to converge\n        // hasFunds-keyed surfaces such as the credits-exhausted banner. The\n        // refresh is best-effort: allSettled keeps a flaky billing API from\n        // surfacing as unhandled rejections.\n        const { fetchStatus, fetchBalance } = useBillingContext()\n        void Promise.allSettled([fetchStatus(), fetchBalance()])\n        void showTopUpCreditsDialog({\n          isInsufficientCredits: true,\n          ...(context.source && { source: context.source })\n        })\n        return\n      }\n    }\n  }\n\n  return { open }\n}\n","import type {\n  ExportedSubgraph,\n  ExportedSubgraphInstance,\n  Subgraph\n} from '@/lib/litegraph/src/litegraph'\nimport { normalizeSubgraphDefinitionIds } from '@/lib/litegraph/src/subgraph/subgraphDeduplication'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { ComfyNodeDef as ComfyNodeDefV1 } from '@/schemas/nodeDefSchema'\nimport { useApp } from '@/scripts/appInstance'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\nimport { useLitegraphService } from './litegraphService'\n\nexport const useSubgraphService = () => {\n  const nodeDefStore = useNodeDefStore()\n\n  /** Loads a single subgraph definition and registers it with the node def store */\n  function registerLitegraphNode(\n    nodeDef: ComfyNodeDefV1,\n    subgraph: Subgraph,\n    exportedSubgraph: ExportedSubgraph\n  ) {\n    const instanceData: ExportedSubgraphInstance = {\n      id: -1,\n      type: exportedSubgraph.id,\n      pos: [0, 0],\n      size: [100, 100],\n      inputs: [],\n      outputs: [],\n      flags: {},\n      order: 0,\n      mode: 0\n    }\n\n    useLitegraphService().registerSubgraphNodeDef(\n      nodeDef,\n      subgraph,\n      instanceData\n    )\n  }\n\n  function createNodeDef(exportedSubgraph: ExportedSubgraph) {\n    const { id, name } = exportedSubgraph\n\n    const nodeDef: ComfyNodeDefV1 = {\n      input: { required: {} },\n      output: [],\n      output_is_list: [],\n      output_name: [],\n      output_tooltips: [],\n      name: id,\n      display_name: name,\n      description: exportedSubgraph.description || `Subgraph node for ${name}`,\n      category: 'subgraph',\n      output_node: false,\n      python_module: 'nodes'\n    }\n\n    nodeDefStore.addNodeDef(nodeDef)\n    return nodeDef\n  }\n\n  /** Loads all exported subgraph definitions from workflow */\n  function loadSubgraphs(graphData: ComfyWorkflowJSON) {\n    const subgraphs = graphData.definitions?.subgraphs\n    if (!subgraphs) return\n\n    const normalized = normalizeSubgraphDefinitionIds(\n      subgraphs,\n      graphData.nodes\n    )\n    graphData.definitions!.subgraphs = normalized.subgraphs\n    if (normalized.rootNodes) graphData.nodes = normalized.rootNodes\n    // Assertion: overriding Zod schema\n    const exportedSubgraphs = normalized.subgraphs as ExportedSubgraph[]\n    const missingSubgraphs = exportedSubgraphs.filter(\n      ({ id }) => !useApp().rootGraph.subgraphs.has(id)\n    )\n    const createdSubgraphs =\n      useApp().rootGraph.createSubgraphs(missingSubgraphs)\n    const loadedSubgraphs = new Map(useApp().rootGraph.subgraphs)\n    for (const [index, data] of missingSubgraphs.entries()) {\n      loadedSubgraphs.set(data.id, createdSubgraphs[index])\n    }\n\n    for (const subgraphData of exportedSubgraphs) {\n      const subgraph = loadedSubgraphs.get(subgraphData.id)\n      if (!subgraph) continue\n\n      registerNewSubgraph(subgraph, subgraphData)\n    }\n  }\n\n  /** Registers a new subgraph (e.g. user converted from nodes) */\n  function registerNewSubgraph(\n    subgraph: Subgraph,\n    exportedSubgraph: ExportedSubgraph\n  ) {\n    const nodeDef = createNodeDef(exportedSubgraph)\n    registerLitegraphNode(nodeDef, subgraph, exportedSubgraph)\n  }\n\n  return {\n    loadSubgraphs,\n    registerNewSubgraph\n  }\n}\n","import { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  desktopHostUser,\n  desktopHostWorkspaceToken\n} from '@/platform/auth/desktopHost/desktopHostSession'\nimport type { PartnerNodeTokenTarget } from '@/platform/auth/partnerNode/partnerNodeTokenSource'\nimport { partnerNodeTokens } from '@/platform/auth/partnerNode/partnerNodeTokens'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useAuthStore } from '@/stores/authStore'\n\n/**\n * Who mints for `workspaceId`: a signed-in host session with its OAuth access\n * token for that workspace, else the Firebase user with its ID token.\n */\nfunction mintTarget(workspaceId: string): PartnerNodeTokenTarget | undefined {\n  const hostUser = desktopHostUser.value\n  if (hostUser) {\n    return {\n      ownerUid: hostUser.id,\n      workspaceId,\n      credential: () => desktopHostWorkspaceToken(workspaceId)\n    }\n  }\n  const authStore = useAuthStore()\n  const ownerUid = authStore.currentUser?.uid\n  if (!ownerUid) return undefined\n  return { ownerUid, workspaceId, credential: () => authStore.getIdToken() }\n}\n\n/**\n * The credential a Local prompt carries in `auth_token_comfy_org`: a\n * partner-node token for the workspace when the flag is on and the mint\n * succeeds, otherwise the workspace token unchanged.\n */\nexport async function queueAuthToken(\n  workspaceToken: string | undefined,\n  workspaceId: string | null\n): Promise<string | undefined> {\n  if (!workspaceToken || !workspaceId || isCloud) return workspaceToken\n  if (!useFeatureFlags().flags.partnerNodeTokenEnabled) return workspaceToken\n\n  const target = mintTarget(workspaceId)\n  if (!target) return workspaceToken\n  return (await partnerNodeTokens.tokenFor(target)) ?? workspaceToken\n}\n","import type { CanvasInteractionModeReader } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nexport function createCanvasInteractionMode(): CanvasInteractionModeReader {\n  const canvasStore = useCanvasStore()\n  return { isSelectOnly: () => canvasStore.isPickingNodes }\n}\n","import type { NodeReplacementResponse } from './types'\n\nimport { api } from '@/scripts/api'\n\nexport async function fetchNodeReplacements(): Promise<NodeReplacementResponse> {\n  const response = await api.fetchApi('/node_replacements')\n  if (!response.ok) {\n    throw new Error(\n      `Failed to fetch node replacements: ${response.status} ${response.statusText}`\n    )\n  }\n  return response.json()\n}\n","import type { NodeReplacement, NodeReplacementResponse } from './types'\n\nimport { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { ServerFeatureFlag } from '@/platform/remoteConfig/serverFeatureFlag'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { api } from '@/scripts/api'\nimport { fetchNodeReplacements } from './nodeReplacementService'\n\nexport const useNodeReplacementStore = defineStore('nodeReplacement', () => {\n  const settingStore = useSettingStore()\n  const replacements = ref<NodeReplacementResponse>({})\n  const isLoaded = ref(false)\n  const isEnabled = computed(() =>\n    settingStore.get('Comfy.NodeReplacement.Enabled')\n  )\n\n  async function load() {\n    if (!isEnabled.value || isLoaded.value) return\n    if (!hasNodeReplacementFeature()) return\n\n    try {\n      replacements.value = await fetchNodeReplacements()\n      isLoaded.value = true\n    } catch (error) {\n      console.error('Failed to load node replacements:', error)\n    }\n  }\n\n  function hasNodeReplacementFeature(): boolean {\n    return api.getServerFeature(ServerFeatureFlag.NODE_REPLACEMENTS, false)\n  }\n\n  function getReplacementFor(nodeType: string): NodeReplacement | null {\n    if (!isEnabled.value) return null\n    return replacements.value[nodeType]?.[0] ?? null\n  }\n\n  function hasReplacement(nodeType: string): boolean {\n    if (!isEnabled.value) return false\n    return !!replacements.value[nodeType]?.length\n  }\n\n  return {\n    replacements,\n    isLoaded,\n    isEnabled,\n    load,\n    getReplacementFor,\n    hasReplacement\n  }\n})\n","import type {\n  ExecutableLGraphNode,\n  ExecutionId,\n  LGraph\n} from '@/lib/litegraph/src/litegraph'\nimport {\n  ExecutableNodeDTO,\n  LGraphEventMode\n} from '@/lib/litegraph/src/litegraph'\nimport type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\n\nimport { zNodePackMetadata } from '@/platform/workflow/validation/schemas/workflowSchema'\n\nimport { compressWidgetInputSlots } from './litegraphUtil'\n\ntype ExportedWidgetValueWrapper = {\n  __type__?: unknown\n  __value__: unknown\n}\n\nfunction isExportedWidgetValueWrapper(\n  value: unknown\n): value is ExportedWidgetValueWrapper {\n  return (\n    typeof value === 'object' &&\n    value !== null &&\n    !Array.isArray(value) &&\n    '__value__' in value\n  )\n}\n\n/**\n * Inverse of the wrapping applied during Export (API). Curve values carry a\n * type marker and may be objects; untyped wrappers are reserved for arrays so\n * ordinary objects containing a `__value__` property pass through unchanged.\n */\nexport function unwrapExportedWidgetValue(value: unknown): unknown {\n  if (\n    isExportedWidgetValueWrapper(value) &&\n    (value.__type__ === 'CURVE' || Array.isArray(value.__value__))\n  ) {\n    return value.__value__\n  }\n  return value\n}\n\n/**\n * Converts the current graph workflow for sending to the API.\n * @note Node widgets are updated before serialization to prepare queueing.\n *\n * @param graph The graph to convert.\n * @param options The options for the conversion.\n *  - `sortNodes`: Whether to sort the nodes by execution order.\n * @returns The workflow and node links\n */\nexport const graphToPrompt = async (\n  graph: LGraph,\n  options: { sortNodes?: boolean } = {}\n): Promise<{ workflow: ComfyWorkflowJSON; output: ComfyApiWorkflow }> => {\n  const { sortNodes = false } = options\n\n  for (const node of graph.computeExecutionOrder(false)) {\n    const innerNodes = node.getInnerNodes\n      ? node.getInnerNodes(new Map())\n      : [node]\n    for (const innerNode of innerNodes) {\n      if (innerNode.isVirtualNode) {\n        innerNode.applyToGraph?.()\n      }\n    }\n  }\n\n  const workflow = graph.serialize({ sortNodes })\n\n  // Remove localized_name from the workflow\n  for (const node of workflow.nodes) {\n    for (const slot of node.inputs ?? []) {\n      delete slot.localized_name\n    }\n    for (const slot of node.outputs ?? []) {\n      delete slot.localized_name\n    }\n  }\n\n  compressWidgetInputSlots(workflow)\n  workflow.extra ??= {}\n  workflow.extra.frontendVersion = __COMFYUI_FRONTEND_VERSION__\n\n  const nodeDtoMap = new Map<ExecutionId, ExecutableLGraphNode>()\n  for (const node of graph.computeExecutionOrder(false)) {\n    const dto: ExecutableLGraphNode = new ExecutableNodeDTO(\n      node,\n      [],\n      nodeDtoMap\n    )\n\n    nodeDtoMap.set(dto.id, dto)\n\n    if (\n      node.mode === LGraphEventMode.NEVER ||\n      node.mode === LGraphEventMode.BYPASS\n    ) {\n      continue\n    }\n\n    for (const innerNode of dto.getInnerNodes()) {\n      nodeDtoMap.set(innerNode.id, innerNode)\n    }\n  }\n\n  const output: ComfyApiWorkflow = {}\n  // Process nodes in order of execution\n  for (const node of nodeDtoMap.values()) {\n    // Don't serialize muted nodes\n    if (\n      node.isVirtualNode ||\n      node.mode === LGraphEventMode.NEVER ||\n      node.mode === LGraphEventMode.BYPASS\n    ) {\n      continue\n    }\n\n    const inputs: ComfyApiWorkflow[string]['inputs'] = {}\n    const { widgets } = node\n\n    // Store all widget values in the API prompt.\n    // Note: widget.options.serialize controls prompt inclusion (checked here).\n    // widget.serialize controls workflow persistence (checked by LGraphNode).\n    if (widgets) {\n      for (const [i, widget] of widgets.entries()) {\n        if (!widget.name || widget.options.serialize === false) continue\n\n        const widgetValue = widget.serializeValue\n          ? await widget.serializeValue(node, i)\n          : widget.value\n        // By default, Array values are reserved to represent node connections.\n        // We need to wrap the array as an object to avoid the misinterpretation\n        // of the array as a node connection.\n        // The backend automatically unwraps the object to an array during\n        // execution.\n        inputs[widget.name] =\n          widget.type === 'curve' && widgetValue != null\n            ? { __type__: 'CURVE', __value__: widgetValue }\n            : Array.isArray(widgetValue)\n              ? { __value__: widgetValue }\n              : widgetValue\n      }\n    }\n\n    // Store all node links\n    for (const [i, input] of node.inputs.entries()) {\n      const resolvedInput = node.resolveInput(i)\n      if (!resolvedInput) continue\n\n      // Resolved to an actual widget value rather than a node connection\n      if (resolvedInput.widgetInfo) {\n        const { value } = resolvedInput.widgetInfo\n        inputs[input.name] = Array.isArray(value) ? { __value__: value } : value\n        continue\n      }\n\n      inputs[input.name] = [resolvedInput.origin_id, resolvedInput.origin_slot]\n    }\n\n    const cnrId = zNodePackMetadata.shape.cnr_id.safeParse(\n      node.properties.cnr_id\n    ).data\n    const auxId = zNodePackMetadata.shape.aux_id.safeParse(\n      node.properties.aux_id\n    ).data\n    const packVersion = zNodePackMetadata.shape.ver.safeParse(\n      node.properties.ver\n    ).data\n    output[node.id] = {\n      inputs,\n      // TODO(huchenlei): Filter out all nodes that cannot be mapped to a\n      // comfyClass.\n      class_type: node.comfyClass!,\n      // Ignored by the backend. Pack identity rides along so a re-imported\n      // prompt can offer install/locate for missing types.\n      _meta: {\n        title: node.title,\n        ...(cnrId && { cnr_id: cnrId }),\n        ...(auxId && { aux_id: auxId }),\n        ...(packVersion && { ver: packVersion })\n      }\n    }\n  }\n\n  // Remove inputs connected to removed nodes\n  for (const { inputs } of Object.values(output)) {\n    for (const [i, input] of Object.entries(inputs)) {\n      if (\n        Array.isArray(input) &&\n        input.length === 2 &&\n        !Object.hasOwn(output, input[0])\n      ) {\n        delete inputs[i]\n      }\n    }\n  }\n\n  return { workflow: workflow as ComfyWorkflowJSON, output }\n}\n","/**\n * Parse JSON that may contain bare `NaN`/`Infinity`/`-Infinity` tokens\n * (which Python's `json.dumps` emits) by replacing them with `null` on\n * fallback. Coercion is lossy; a one-time warning is logged when it fires.\n */\nexport function parseJsonWithNonFinite<T = unknown>(\n  text: string & { readonly parsedType?: T }\n): T {\n  try {\n    return JSON.parse(text) as T\n  } catch {\n    return JSON.parse(replaceNonFiniteTokens(text)) as T\n  }\n}\n\n// Match a JSON string OR a non-finite token outside string.\n// - `\"(?:\\\\.|[^\"\\\\])*\"`  a quoted string - matched first so anything that\n//                        looks like a token inside a string is skipped\n// - `(?<![\\w.-])`        skip non bare tokens (e.g. 1NaN)\n// - `(-?Infinity|NaN)`   capture the non-finite token\n// - `(?![\\w.])`          skip non bare suffix tokens (e.g. NaN1)\nconst NON_FINITE_TOKEN =\n  /\"(?:\\\\.|[^\"\\\\])*\"|(?<![\\w.-])(-?Infinity|NaN)(?![\\w.])/g\n\nfunction replaceNonFiniteTokens(text: string): string {\n  let hasWarned = false\n  return text.replace(NON_FINITE_TOKEN, (match, token) => {\n    if (token) {\n      if (!hasWarned) {\n        console.warn(\n          'JSON contained non-finite numeric tokens (NaN/Infinity); they were replaced with null.'\n        )\n        hasWarned = true\n      }\n      return 'null'\n    }\n    return match\n  })\n}\n","import { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { LGraphEventMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { useNodeReplacementStore } from '@/platform/nodeReplacement/nodeReplacementStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport {\n  collectAllNodes,\n  getExecutionIdByNode\n} from '@/utils/graphTraversalUtil'\nimport { getCnrIdFromNode } from '@/platform/nodeReplacement/cnrIdUtil'\n\n/** Scan the live graph for unregistered node types and build a full MissingNodeType list. */\nfunction scanMissingNodes(rootGraph: LGraph): MissingNodeType[] {\n  const nodeReplacementStore = useNodeReplacementStore()\n  const missingNodeTypes: MissingNodeType[] = []\n\n  const allNodes = collectAllNodes(rootGraph)\n\n  for (const node of allNodes) {\n    if (\n      node.mode === LGraphEventMode.NEVER ||\n      node.mode === LGraphEventMode.BYPASS\n    )\n      continue\n\n    const originalType = node.last_serialization?.type ?? node.type\n\n    if (originalType in LiteGraph.registered_node_types) continue\n\n    const cnrId = getCnrIdFromNode(node)\n    const replacement = nodeReplacementStore.getReplacementFor(originalType)\n    const executionId = getExecutionIdByNode(rootGraph, node)\n\n    missingNodeTypes.push({\n      type: originalType,\n      nodeId: executionId ?? String(node.id),\n      cnrId,\n      isReplaceable: replacement !== null,\n      replacement: replacement ?? undefined\n    })\n  }\n\n  return missingNodeTypes\n}\n\n/** Re-scan the graph for missing nodes and update the error store. */\nexport function rescanAndSurfaceMissingNodes(rootGraph: LGraph): void {\n  const types = scanMissingNodes(rootGraph)\n  if (useMissingNodesErrorStore().surfaceMissingNodes(types)) {\n    useExecutionErrorStore().showErrorOverlay()\n  }\n}\n","import { st } from '@/i18n'\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport { isCloud } from '@/platform/distribution/types'\nimport {\n  enrichWithEmbeddedMetadata,\n  hasPendingVerification,\n  scanAllModelCandidates,\n  verifyAssetSupportedCandidates\n} from '@/platform/missingModel/missingModelScan'\nimport type { MissingModelWorkflowData } from '@/platform/missingModel/missingModelScan'\nimport type {\n  MissingModelCandidate,\n  MissingModelPipelineResult\n} from '@/platform/missingModel/types'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { updatePendingWarnings } from '@/platform/workflow/core/utils/pendingWarnings'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport type { ModelFile } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { api } from '@/scripts/api'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport {\n  getNodeByExecutionId,\n  isCandidateScopeActive,\n  isMissingCandidateActive\n} from '@/utils/graphTraversalUtil'\n\ninterface MissingModelPipelineStore {\n  missingModelCandidates: MissingModelCandidate[] | null\n  createVerificationAbortController: () => AbortController\n  setFolderPaths: (paths: Record<string, string[]>) => void\n  setFileSize: (url: string, size: number) => void\n  setGatedRepoUrl: (url: string, repoUrl: string) => void\n}\n\ninterface RunMissingModelPipelineOptions {\n  graph: LGraph\n  graphData: MissingModelWorkflowData\n  missingModelStore: MissingModelPipelineStore\n  missingNodeTypes?: MissingNodeType[]\n  onVerified?: (candidates: MissingModelCandidate[]) => void\n  silent?: boolean\n}\n\ninterface RefreshMissingModelPipelineOptions {\n  graph: LGraph\n  reloadNodeDefs?: () => Promise<void>\n  missingModelStore: MissingModelPipelineStore\n  silent?: boolean\n}\n\ntype MissingModelCandidateWithDownloadMetadata = MissingModelCandidate & {\n  url: string\n  directory: string\n}\n\nfunction cacheModelCandidates(\n  wf: Pick<ComfyWorkflow, 'pendingWarnings'> | null | undefined,\n  confirmed: MissingModelCandidate[]\n) {\n  if (!wf) return\n  updatePendingWarnings(wf, {\n    missingModelCandidates: confirmed\n  })\n}\n\nfunction clearMissingModels(\n  wf: Pick<ComfyWorkflow, 'pendingWarnings'> | null | undefined,\n  silent: boolean\n) {\n  useExecutionErrorStore().surfaceMissingModels([], { silent })\n  cacheModelCandidates(wf, [])\n}\n\nfunction hasDownloadMetadata(\n  candidate: MissingModelCandidate\n): candidate is MissingModelCandidateWithDownloadMetadata {\n  return !!candidate.url && !!candidate.directory\n}\n\nfunction toModelFile(candidate: MissingModelCandidateWithDownloadMetadata) {\n  return {\n    name: candidate.name,\n    url: candidate.url,\n    directory: candidate.directory,\n    hash: candidate.hash,\n    hash_type: candidate.hashType\n  }\n}\n\nfunction getCurrentMissingModelMetadata(\n  missingModelStore: MissingModelPipelineStore\n): ModelFile[] {\n  return (\n    missingModelStore.missingModelCandidates\n      ?.filter(hasDownloadMetadata)\n      .map(toModelFile) ?? []\n  )\n}\n\nexport async function runMissingModelPipeline({\n  graph,\n  graphData,\n  missingModelStore,\n  missingNodeTypes,\n  silent = false,\n  onVerified\n}: RunMissingModelPipelineOptions): Promise<MissingModelPipelineResult> {\n  const controller = missingModelStore.createVerificationAbortController()\n\n  const getDirectory = (nodeType: string) =>\n    useModelToNodeStore().getCategoryForNodeType(nodeType)\n  const isAssetBrowserWidget = assetService.shouldUseWidgetAssetPicker\n\n  const candidates = scanAllModelCandidates(\n    graph,\n    isAssetBrowserWidget,\n    getDirectory\n  )\n\n  const enrichedAll = enrichWithEmbeddedMetadata(candidates, graphData)\n\n  // Drop candidates whose active scope is muted/bypassed. Normal candidates\n  // use nodeId; promoted host candidates use sourceExecutionId so host-keyed\n  // errors still respect inactive interior subgraph containers.\n  // Asymmetric on purpose: a candidate dropped here is not resurrected if\n  // the user un-bypasses the container mid-verification. The realtime\n  // mode-change path (handleNodeModeChange → scanAndAddNodeErrors) is\n  // responsible for surfacing errors after an un-bypass.\n  const enrichedCandidates = enrichedAll.filter((c) =>\n    isCandidateScopeActive(graph, c)\n  )\n\n  const confirmedCandidates = enrichedCandidates.filter(\n    (c) => c.isMissing === true\n  )\n  const hasDeferredCandidates = enrichedCandidates.some(hasPendingVerification)\n  const downloadableCandidates = confirmedCandidates.filter(hasDownloadMetadata)\n\n  const missingModels: ModelFile[] = downloadableCandidates.map(toModelFile)\n\n  const activeWf = useWorkspaceStore().workflow.activeWorkflow\n  updatePendingWarnings(activeWf, {\n    ...(missingNodeTypes ? { missingNodeTypes } : {}),\n    missingModelCandidates: confirmedCandidates\n  })\n\n  if (!enrichedCandidates.length) {\n    clearMissingModels(activeWf, silent)\n    onVerified?.([])\n    return { missingModels, confirmedCandidates }\n  }\n\n  // Re-check at surface time: the user may have bypassed a container or\n  // changed the selection while verification or folder paths were in flight.\n  const isStillSelected = (candidate: MissingModelCandidate) => {\n    if (candidate.nodeId == null) return true\n    const node = getNodeByExecutionId(graph, String(candidate.nodeId))\n    const widget = node?.widgets?.find((w) => w.name === candidate.widgetName)\n    return widget?.value === candidate.name\n  }\n  const surfaceActiveCandidates = () => {\n    const confirmed = enrichedCandidates.filter(\n      (c) => isMissingCandidateActive(graph, c) && isStillSelected(c)\n    )\n    useExecutionErrorStore().surfaceMissingModels(confirmed, { silent })\n    cacheModelCandidates(activeWf, confirmed)\n    onVerified?.(\n      enrichedCandidates.filter(\n        (c) => isCandidateScopeActive(graph, c) && isStillSelected(c)\n      )\n    )\n  }\n  const reportVerificationFailure = (err: unknown) => {\n    if (controller.signal.aborted) return\n    console.warn(\n      '[Missing Model Pipeline] Missing model verification failed:',\n      err\n    )\n    reportError(err, {\n      surface: 'assets',\n      errorType: 'missing_model_verification_failed'\n    })\n    useToast().warning(\n      st(\n        'toastMessages.missingModelVerificationFailed',\n        'Failed to verify missing models. Some models may not be shown in the Issues tab.'\n      ),\n      { duration: 5000 }\n    )\n  }\n\n  if (isCloud) {\n    void verifyAssetSupportedCandidates(enrichedCandidates, controller.signal)\n      .then(() => {\n        if (controller.signal.aborted) return\n        surfaceActiveCandidates()\n      })\n      .catch(reportVerificationFailure)\n    return { missingModels, confirmedCandidates }\n  }\n\n  if (!confirmedCandidates.length && !hasDeferredCandidates) {\n    surfaceActiveCandidates()\n    return { missingModels, confirmedCandidates }\n  }\n\n  const verification = hasDeferredCandidates\n    ? verifyAssetSupportedCandidates(enrichedCandidates, controller.signal)\n    : Promise.resolve()\n  void verification\n    .then(async () => {\n      if (controller.signal.aborted) return\n      const hasActiveMissing = enrichedCandidates.some((c) =>\n        isMissingCandidateActive(graph, c)\n      )\n      if (!hasActiveMissing) {\n        surfaceActiveCandidates()\n        return\n      }\n      const verifiedDownloadableCandidates = enrichedCandidates\n        .filter((c) => c.isMissing === true)\n        .filter(hasDownloadMetadata)\n      const missingModelMetadata =\n        import('@/platform/missingModel/missingModelMetadata')\n      void Promise.allSettled(\n        verifiedDownloadableCandidates.map(async (c) => {\n          const { fetchAndStoreModelMetadata } = await missingModelMetadata\n          await fetchAndStoreModelMetadata(\n            c.url,\n            missingModelStore,\n            controller.signal\n          )\n        })\n      )\n      await api\n        .getFolderPaths()\n        .then((paths) => {\n          if (controller.signal.aborted) return\n          missingModelStore.setFolderPaths(paths)\n        })\n        .catch((err) => {\n          console.warn(\n            '[Missing Model Pipeline] Failed to fetch folder paths:',\n            err\n          )\n        })\n        .finally(() => {\n          if (controller.signal.aborted) return\n          surfaceActiveCandidates()\n        })\n    })\n    .catch(reportVerificationFailure)\n\n  return { missingModels, confirmedCandidates }\n}\n\nexport async function refreshMissingModelPipeline({\n  graph,\n  reloadNodeDefs,\n  missingModelStore,\n  silent = true\n}: RefreshMissingModelPipelineOptions): Promise<MissingModelPipelineResult> {\n  await reloadNodeDefs?.()\n  const graphData: MissingModelWorkflowData = graph.serialize()\n  const activeWorkflowState =\n    useWorkspaceStore().workflow.activeWorkflow?.activeState\n  const currentModelMetadata = getCurrentMissingModelMetadata(missingModelStore)\n  const models = activeWorkflowState?.models?.length\n    ? activeWorkflowState.models\n    : currentModelMetadata\n\n  return runMissingModelPipeline({\n    graph,\n    graphData: models.length ? { ...graphData, models } : graphData,\n    missingModelStore,\n    silent\n  })\n}\n","import { groupBy } from 'es-toolkit'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  buildPromotedWidgetExecutionSources,\n  hasActivePromotedWidgetConsumer,\n  resolveActivePromotedWidgetConsumers\n} from '@/core/graph/subgraph/resolveConcretePromotedWidget'\nimport { resolvePromotedWidgetSource } from '@/core/graph/subgraph/resolvePromotedWidgetSource'\nimport { resolveWidgetValueAsset } from '@/platform/assets/utils/resolveWidgetValueAsset'\nimport { isComboInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type {\n  MissingMediaCandidate,\n  MissingMediaViewModel,\n  MissingMediaGroup,\n  MediaType\n} from './types'\nimport type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type {\n  IBaseWidget,\n  IComboWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport {\n  collectAllNodes,\n  getExecutionIdByNode,\n  getNodeByExecutionId,\n  isExecutionPathActive\n} from '@/utils/graphTraversalUtil'\nimport { LGraphEventMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { resolveComboValues } from '@/utils/litegraphUtil'\nimport { parseAnnotatedPath } from '@/utils/createAnnotatedPath'\n\nfunction isComboWidget(widget: IBaseWidget): widget is IComboWidget {\n  return widget.type === 'combo'\n}\n\n/** The widget a user can actually edit. */\nfunction isEditableValueOwner(node: LGraphNode, widget: IBaseWidget): boolean {\n  const input = node.getSlotFromWidget(widget)\n  if (input?.link != null) return false\n  if (!node.isSubgraphNode()) return true\n  return !!input?.widgetId && hasActivePromotedWidgetConsumer(node, input.name)\n}\n\nfunction mediaTypeFromSpec(\n  spec: InputSpecV2 | undefined\n): MediaType | undefined {\n  if (!spec || !isComboInputSpec(spec)) return undefined\n  if (spec.video_upload) return 'video'\n  if (spec.image_upload || spec.animated_image_upload) return 'image'\n  if (spec.audio_upload) return 'audio'\n  return undefined\n}\n\n/**\n * Scan combo widgets on media nodes for file values that may be missing.\n *\n * With the asset API enabled, `isMissing` is left `undefined` so\n * `verifyMediaCandidates` resolves it against the asset listing on every\n * backend. Without it, `isMissing` is resolved immediately from widget\n * options unless an output annotation needs generated-history verification.\n */\nexport function scanAllMediaCandidates(\n  rootGraph: LGraph\n): MissingMediaCandidate[] {\n  const allNodes = collectAllNodes(rootGraph)\n  const candidates: MissingMediaCandidate[] = []\n\n  for (const node of allNodes) {\n    if (!node.widgets?.length) continue\n    if (\n      node.mode === LGraphEventMode.NEVER ||\n      node.mode === LGraphEventMode.BYPASS\n    )\n      continue\n\n    candidates.push(...scanNodeMediaCandidates(rootGraph, node))\n  }\n\n  return candidates\n}\n\nfunction resolveMediaMissingState(\n  widget: IComboWidget,\n  value: string\n): boolean | undefined {\n  if (useFeatureFlags().flags.assetsEnabled) return undefined\n  const options = resolveComboValues(widget)\n  const { filepath, rootFolder } = parseAnnotatedPath(value)\n  if (rootFolder !== 'input') return options.includes(value) ? false : undefined\n  return !options.includes(value) && !options.includes(filepath)\n}\n\n/** Scan a single node for missing media candidates. */\nexport function scanNodeMediaCandidates(\n  rootGraph: LGraph,\n  node: LGraphNode\n): MissingMediaCandidate[] {\n  if (!node.widgets?.length) return []\n\n  const executionId = getExecutionIdByNode(rootGraph, node)\n  if (!executionId) return []\n\n  if (node.isUploading) return []\n\n  const nodeDefStore = useNodeDefStore()\n  const candidates: MissingMediaCandidate[] = []\n  for (const widget of node.widgets) {\n    if (!isComboWidget(widget)) continue\n\n    const mediaType = mediaTypeFromSpec(\n      nodeDefStore.getInputSpecForWidget(node, widget.name)\n    )\n    if (!mediaType) continue\n    if (!isEditableValueOwner(node, widget)) continue\n\n    const value = widget.value\n    if (typeof value !== 'string' || !value.trim()) continue\n\n    const isMissing = resolveMediaMissingState(widget, value)\n\n    // Label only, and leaf-derived to match missingModelScan: the overlay\n    // formats nodeType directly and a SubgraphNode's own type is a UUID.\n    const promotedSource = resolvePromotedWidgetSource(rootGraph, node, widget)\n    const labelNode = promotedSource?.sourceNode ?? node\n\n    const candidate: MissingMediaCandidate = {\n      nodeId: executionId,\n      nodeType: labelNode.type,\n      widgetName: widget.name,\n      mediaType,\n      name: value,\n      isMissing\n    }\n    if (node.isSubgraphNode()) {\n      const consumers = resolveActivePromotedWidgetConsumers(node, widget.name)\n      candidate.promotedSources = buildPromotedWidgetExecutionSources(\n        executionId,\n        consumers\n      )\n    }\n    candidates.push(candidate)\n  }\n\n  return candidates\n}\n\nexport function isMissingMediaCandidateScopeActive(\n  rootGraph: LGraph | null | undefined,\n  candidate: MissingMediaCandidate\n): boolean {\n  if (!rootGraph) return false\n\n  const executionId = String(candidate.nodeId)\n  if (!isExecutionPathActive(rootGraph, executionId)) return false\n\n  const node = getNodeByExecutionId(rootGraph, executionId)\n  if (!node) return false\n  const widget = node.widgets?.find(\n    (candidateWidget) => candidateWidget.name === candidate.widgetName\n  )\n  if (!widget) return false\n\n  return widget.value === candidate.name && isEditableValueOwner(node, widget)\n}\n\nexport function isMissingMediaCandidateActive(\n  rootGraph: LGraph | null | undefined,\n  candidate: MissingMediaCandidate\n): boolean {\n  return (\n    candidate.isMissing === true &&\n    isMissingMediaCandidateScopeActive(rootGraph, candidate)\n  )\n}\n\n/** Resolve pending candidates against the asset store, then a remote hash lookup when assets are enabled. */\nexport async function verifyMediaCandidates(\n  candidates: MissingMediaCandidate[],\n  { signal }: { signal?: AbortSignal } = {}\n): Promise<void> {\n  if (signal?.aborted) return\n  const pending = candidates.filter((c) => c.isMissing === undefined)\n  const results = await Promise.allSettled(\n    Object.entries(groupBy(pending, (p) => p.name)).map(\n      async ([name, candidates]) => {\n        const asset = await resolveWidgetValueAsset(name, { signal })\n        const isMissing = asset === undefined ? undefined : asset === null\n        for (const candidate of candidates) candidate.isMissing = isMissing\n      }\n    )\n  )\n  const firstRejection = results.find((r) => r.status === 'rejected')\n  if (firstRejection && !signal?.aborted) throw firstRejection.reason\n}\n\n/** Group confirmed-missing candidates by file name into view models. */\nexport function groupCandidatesByName(\n  candidates: MissingMediaCandidate[]\n): MissingMediaViewModel[] {\n  const map = new Map<string, MissingMediaViewModel>()\n  for (const c of candidates) {\n    const existing = map.get(c.name)\n    if (existing) {\n      existing.referencingNodes.push({\n        nodeId: c.nodeId,\n        nodeType: c.nodeType,\n        widgetName: c.widgetName\n      })\n    } else {\n      map.set(c.name, {\n        name: c.name,\n        mediaType: c.mediaType,\n        representative: c,\n        referencingNodes: [\n          { nodeId: c.nodeId, nodeType: c.nodeType, widgetName: c.widgetName }\n        ]\n      })\n    }\n  }\n  return Array.from(map.values())\n}\n\n/** Group confirmed-missing candidates by media type. */\nexport function groupCandidatesByMediaType(\n  candidates: MissingMediaCandidate[]\n): MissingMediaGroup[] {\n  const grouped = groupBy(candidates, (c) => c.mediaType)\n  const order: MediaType[] = ['image', 'video', 'audio']\n  return order\n    .filter((t) => t in grouped)\n    .map((mediaType) => ({\n      mediaType,\n      items: groupCandidatesByName(grouped[mediaType])\n    }))\n}\n","import { st } from '@/i18n'\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport {\n  isMissingMediaCandidateActive,\n  isMissingMediaCandidateScopeActive,\n  scanAllMediaCandidates,\n  verifyMediaCandidates\n} from '@/platform/missingMedia/missingMediaScan'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { updatePendingWarnings } from '@/platform/workflow/core/utils/pendingWarnings'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\n\ninterface RunMissingMediaPipelineOptions {\n  rootGraph: LGraph\n  silent?: boolean\n  onVerified?: (candidates: MissingMediaCandidate[]) => void\n}\n\nfunction cacheMediaCandidates(\n  wf: Pick<ComfyWorkflow, 'pendingWarnings'> | null | undefined,\n  confirmed: MissingMediaCandidate[]\n) {\n  if (!wf) return\n  updatePendingWarnings(wf, {\n    missingMediaCandidates: confirmed\n  })\n}\n\nexport async function runMissingMediaPipeline({\n  rootGraph,\n  silent = false,\n  onVerified\n}: RunMissingMediaPipelineOptions): Promise<void> {\n  const missingMediaStore = useMissingMediaStore()\n  const activeWf = useWorkspaceStore().workflow.activeWorkflow\n  const allCandidates = scanAllMediaCandidates(rootGraph)\n  // Drop candidates whose enclosing subgraph is muted/bypassed.\n  const candidates = allCandidates.filter((candidate) =>\n    isMissingMediaCandidateScopeActive(rootGraph, candidate)\n  )\n\n  if (!candidates.length) {\n    cacheMediaCandidates(activeWf, [])\n    onVerified?.([])\n    return\n  }\n\n  const pending = candidates.some((c) => c.isMissing === undefined)\n  if (pending) {\n    const controller = missingMediaStore.createVerificationAbortController()\n    void verifyMediaCandidates(candidates, { signal: controller.signal })\n      .then(() => {\n        if (controller.signal.aborted) return\n        // Re-check ancestor after async verification (see model pipeline).\n        const confirmed = candidates.filter((candidate) =>\n          isMissingMediaCandidateActive(rootGraph, candidate)\n        )\n        if (confirmed.length) {\n          useExecutionErrorStore().surfaceMissingMedia(confirmed, { silent })\n        }\n        cacheMediaCandidates(activeWf, confirmed)\n        onVerified?.(\n          candidates.filter((candidate) =>\n            isMissingMediaCandidateScopeActive(rootGraph, candidate)\n          )\n        )\n      })\n      .catch((err) => {\n        console.warn('[Missing Media Pipeline] Asset verification failed:', err)\n        useToast().warning(\n          st(\n            'toastMessages.missingMediaVerificationFailed',\n            'Failed to verify missing media. Some inputs may not be shown in the Issues tab.'\n          ),\n          { duration: 5000 }\n        )\n      })\n  } else {\n    const confirmed = candidates.filter((c) => c.isMissing === true)\n    useExecutionErrorStore().surfaceMissingMedia(confirmed, { silent })\n    cacheMediaCandidates(activeWf, confirmed)\n    onVerified?.(candidates)\n  }\n}\n","import { cloneDeep, keyBy, omit } from 'es-toolkit/compat'\n\nimport type {\n  ComfyLinkObject,\n  ComfyNode,\n  Reroute,\n  WorkflowJSON04\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { SerializedNodeId } from '@/types/nodeId'\n\ntype RerouteNode = ComfyNode & {\n  type: 'Reroute'\n}\n\ntype LinkExtension = {\n  id: number\n  parentId: number\n}\n\n/**\n * Identifies all legacy Reroute nodes in a workflow\n */\nexport function findLegacyRerouteNodes(\n  workflow: WorkflowJSON04\n): RerouteNode[] {\n  return workflow.nodes.filter(\n    (node) => node.type === 'Reroute'\n  ) as RerouteNode[]\n}\n\n/**\n * Checks if the workflow has no native reroutes\n */\nexport function noNativeReroutes(workflow: WorkflowJSON04): boolean {\n  return (\n    !workflow.extra?.reroutes?.length && !workflow.extra?.linkExtensions?.length\n  )\n}\n\n/**\n * Gets the center position of a node\n */\nfunction getNodeCenter(node: ComfyNode): [number, number] {\n  return [node.pos[0] + node.size[0] / 2, node.pos[1] + node.size[1] / 2]\n}\n\nclass ConversionContext {\n  nodeById: Record<SerializedNodeId, ComfyNode>\n  linkById: Record<number, ComfyLinkObject>\n  rerouteById: Record<number, Reroute>\n  rerouteByNodeId: Record<SerializedNodeId, Reroute>\n  linkExtensions: LinkExtension[]\n\n  /** Reroutes that has at least a valid link pass through it */\n  validReroutes: Set<Reroute>\n\n  private _rerouteIdCounter = 0\n\n  constructor(public workflow: WorkflowJSON04) {\n    this.nodeById = keyBy(workflow.nodes.map(cloneDeep), 'id')\n    this.linkById = keyBy(\n      workflow.links.map((l) => ({\n        id: l[0],\n        origin_id: l[1],\n        origin_slot: l[2],\n        target_id: l[3],\n        target_slot: l[4],\n        type: l[5]\n      })),\n      'id'\n    )\n\n    const reroutes = findLegacyRerouteNodes(workflow).map((node, index) => ({\n      nodeId: node.id,\n      id: index + 1,\n      pos: getNodeCenter(node),\n      linkIds: []\n    }))\n    this._rerouteIdCounter = reroutes.length + 1\n\n    this.rerouteByNodeId = keyBy(reroutes, 'nodeId')\n    this.rerouteById = keyBy(reroutes, 'id')\n\n    this.linkExtensions = []\n    this.validReroutes = new Set()\n  }\n\n  /**\n   * Gets the chain of reroute nodes leading to the given node\n   */\n  private _getRerouteChain(node: RerouteNode): RerouteNode[] {\n    const nodes: RerouteNode[] = []\n    let currentNode: RerouteNode | undefined = node\n    while (currentNode?.type === 'Reroute') {\n      nodes.push(currentNode)\n      const linkId = currentNode.inputs?.[0]?.link ?? 0\n      const inputLink = Object.hasOwn(this.linkById, linkId)\n        ? this.linkById[linkId]\n        : undefined\n      if (!inputLink) break\n\n      currentNode = this.nodeById[inputLink.origin_id] as\n        | RerouteNode\n        | undefined\n    }\n\n    return nodes\n  }\n\n  private _connectRerouteChain(rerouteNodes: RerouteNode[]): Reroute[] {\n    const reroutes = rerouteNodes.map((node) => this.rerouteByNodeId[node.id])\n    for (const reroute of reroutes) {\n      this.validReroutes.add(reroute)\n    }\n\n    for (let i = 0; i < rerouteNodes.length - 1; i++) {\n      const to = reroutes[i]\n      const from = reroutes[i + 1]\n      to.parentId = from.id\n    }\n\n    return reroutes\n  }\n\n  private _createNewLink(\n    startingLink: ComfyLinkObject,\n    endingLink: ComfyLinkObject,\n    rerouteNodes: RerouteNode[]\n  ): ComfyLinkObject {\n    if (rerouteNodes.length === 0) {\n      throw new Error('No reroute nodes found')\n    }\n\n    const reroute = this.rerouteByNodeId[rerouteNodes[0].id]\n    this.linkExtensions.push({\n      id: endingLink.id,\n      parentId: reroute.id\n    })\n\n    const reroutes = this._connectRerouteChain(rerouteNodes)\n    for (const reroute of reroutes) {\n      reroute.linkIds ??= []\n      reroute.linkIds.push(endingLink.id)\n      delete reroute.floating\n    }\n\n    return {\n      id: endingLink.id,\n      origin_id: startingLink.origin_id,\n      origin_slot: startingLink.origin_slot,\n      target_id: endingLink.target_id,\n      target_slot: endingLink.target_slot,\n      type: endingLink.type\n    }\n  }\n\n  private _createNewInputFloatingLink(\n    endingLink: ComfyLinkObject,\n    rerouteNodes: RerouteNode[]\n  ): ComfyLinkObject {\n    const reroutes = this._connectRerouteChain(rerouteNodes)\n    for (const reroute of reroutes) {\n      if (!reroute.linkIds?.length) {\n        reroute.floating = {\n          slotType: 'input'\n        }\n      }\n    }\n    return {\n      id: this._rerouteIdCounter++,\n      origin_id: -1,\n      origin_slot: -1,\n      target_id: endingLink.target_id,\n      target_slot: endingLink.target_slot,\n      type: endingLink.type,\n      parentId: reroutes[0].id\n    }\n  }\n\n  private _createNewOutputFloatingLink(\n    startingLink: ComfyLinkObject,\n    rerouteNodes: RerouteNode[]\n  ): ComfyLinkObject {\n    const reroutes = this._connectRerouteChain(rerouteNodes)\n    for (const reroute of reroutes) {\n      if (!reroute.linkIds?.length) {\n        reroute.floating = {\n          slotType: 'output'\n        }\n      }\n    }\n\n    return {\n      id: this._rerouteIdCounter++,\n      origin_id: startingLink.origin_id,\n      origin_slot: startingLink.origin_slot,\n      target_id: -1,\n      target_slot: -1,\n      type: startingLink.type,\n      parentId: reroutes[0].id\n    }\n  }\n\n  private _reconnectLinks(nodes: ComfyNode[], links: ComfyLinkObject[]): void {\n    // Remove all existing links on sockets\n    for (const node of nodes) {\n      for (const input of node.inputs ?? []) {\n        input.link = null\n      }\n      for (const output of node.outputs ?? []) {\n        output.links = []\n      }\n    }\n\n    const nodesById = keyBy(nodes, 'id')\n\n    // Reconnect the links\n    for (const link of links) {\n      const sourceNode = nodesById[link.origin_id]\n      sourceNode.outputs![link.origin_slot].links!.push(link.id)\n\n      const targetNode = nodesById[link.target_id]\n      targetNode.inputs![link.target_slot].link = link.id\n    }\n  }\n\n  migrateReroutes(): WorkflowJSON04 {\n    const links: ComfyLinkObject[] = []\n    const floatingLinks: ComfyLinkObject[] = []\n\n    const endingLinks: ComfyLinkObject[] = []\n\n    for (const link of Object.values(this.linkById)) {\n      const sourceIsReroute = Boolean(this.rerouteByNodeId[link.origin_id])\n      const targetIsReroute = Boolean(this.rerouteByNodeId[link.target_id])\n\n      // Process links that are not connected to reroute nodes\n      if (!sourceIsReroute && !targetIsReroute) {\n        links.push(link)\n      } else if (sourceIsReroute && !targetIsReroute) {\n        endingLinks.push(link)\n      }\n    }\n\n    for (const endingLink of endingLinks) {\n      const endingRerouteNode = this.nodeById[\n        endingLink.origin_id\n      ] as RerouteNode\n      const rerouteNodes = this._getRerouteChain(endingRerouteNode)\n      const startingLinkId =\n        rerouteNodes[rerouteNodes.length - 1]?.inputs?.[0]?.link ?? -1\n      if (Object.hasOwn(this.linkById, startingLinkId)) {\n        const startingLink = this.linkById[startingLinkId]\n        // Valid link found, create a new link\n        links.push(this._createNewLink(startingLink, endingLink, rerouteNodes))\n      } else {\n        // Floating link found, create a new floating link\n        floatingLinks.push(\n          this._createNewInputFloatingLink(endingLink, rerouteNodes)\n        )\n      }\n    }\n\n    const floatingEndingRerouteNodes = Object.keys(this.rerouteByNodeId)\n      .map((nodeId) => this.nodeById[nodeId] as RerouteNode)\n      .filter((rerouteNode) => {\n        const output = rerouteNode.outputs?.[0]\n        if (!output) return false\n        return !output.links?.length\n      })\n\n    for (const rerouteNode of floatingEndingRerouteNodes) {\n      const rerouteNodes = this._getRerouteChain(rerouteNode)\n      const startingLinkId =\n        rerouteNodes[rerouteNodes.length - 1]?.inputs?.[0]?.link ?? -1\n      if (Object.hasOwn(this.linkById, startingLinkId)) {\n        const startingLink = this.linkById[startingLinkId]\n        floatingLinks.push(\n          this._createNewOutputFloatingLink(startingLink, rerouteNodes)\n        )\n      }\n    }\n\n    const nodes = Object.values(this.nodeById).filter(\n      (node) => node.type !== 'Reroute'\n    )\n    this._reconnectLinks(nodes, links)\n\n    return {\n      ...this.workflow,\n      nodes,\n      links: links.map((link) => [\n        link.id,\n        link.origin_id,\n        link.origin_slot,\n        link.target_id,\n        link.target_slot,\n        link.type\n      ]),\n      floatingLinks: floatingLinks.length > 0 ? floatingLinks : undefined,\n      extra: {\n        ...this.workflow.extra,\n        reroutes: Array.from(this.validReroutes).map(\n          (reroute) => omit(reroute, 'nodeId') as Reroute\n        ),\n        linkExtensions: this.linkExtensions\n      }\n    }\n  }\n}\n\n/**\n * Main function to migrate legacy reroute nodes to native reroute points\n */\nexport const migrateLegacyRerouteNodes = (\n  workflow: WorkflowJSON04\n): WorkflowJSON04 => {\n  // Find all legacy Reroute nodes\n  const legacyRerouteNodes = findLegacyRerouteNodes(workflow)\n\n  // If no reroute nodes, return the workflow unchanged\n  if (legacyRerouteNodes.length === 0) {\n    return workflow\n  }\n\n  // Create a deep copy of the workflow to avoid mutating the original\n  const newWorkflow = JSON.parse(JSON.stringify(workflow)) as WorkflowJSON04\n\n  // Initialize extra structure if needed\n  if (!newWorkflow.extra) {\n    newWorkflow.extra = {}\n  }\n\n  const context = new ConversionContext(newWorkflow)\n  return context.migrateReroutes()\n}\n","import type { LGraphCanvas, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\n\n/**\n * Deserialises nodes and links using a modified version of the old Litegraph (copy &) paste function\n * @param data The serialised nodes and links to create\n * @param canvas The canvas to create the serialised items in\n */\nexport function deserialiseAndCreate(data: string, canvas: LGraphCanvas): void {\n  if (!data) return\n\n  const { graph, graph_mouse } = canvas\n  if (!graph) return\n  canvas.emitBeforeChange()\n  try {\n    graph.beforeChange()\n\n    const deserialised = JSON.parse(data)\n\n    // Find the top left point of the boundary of all pasted nodes\n    const topLeft = [Infinity, Infinity]\n    for (const { pos } of deserialised.nodes) {\n      if (topLeft[0] > pos[0]) topLeft[0] = pos[0]\n      if (topLeft[1] > pos[1]) topLeft[1] = pos[1]\n    }\n\n    // Silent default instead of throw\n    if (!Number.isFinite(topLeft[0]) || !Number.isFinite(topLeft[1])) {\n      topLeft[0] = graph_mouse[0]\n      topLeft[1] = graph_mouse[1]\n    }\n\n    // Create nodes\n    const nodes: LGraphNode[] = []\n    for (const info of deserialised.nodes) {\n      const node = LiteGraph.createNode(info.type)\n      if (!node) continue\n\n      node.configure(info)\n\n      // Paste to the bottom right of pointer\n      node.pos = [\n        node.pos[0] + graph_mouse[0] - topLeft[0],\n        node.pos[1] + graph_mouse[1] - topLeft[1]\n      ]\n\n      withNodeAddSource('paste', () => graph.add(node, true))\n      nodes.push(node)\n    }\n\n    // Create links\n    for (const info of deserialised.links) {\n      const relativeId = info[0]\n      const outNode = relativeId != null ? nodes[relativeId] : undefined\n\n      const inNode = nodes[info[2]]\n      if (outNode) outNode.connect(info[1], inNode, info[3])\n      else console.warn('Warning, nodes missing on pasting')\n    }\n\n    canvas.selectNodes(nodes)\n\n    graph.afterChange()\n  } finally {\n    canvas.emitAfterChange()\n  }\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\n\n/**\n * Tag names used in ComfyUI metadata\n */\nexport enum ComfyMetadataTags {\n  PROMPT = 'PROMPT',\n  WORKFLOW = 'WORKFLOW'\n}\n\n/**\n * Metadata extracted from ComfyUI output files\n */\nexport interface ComfyMetadata {\n  workflow?: ComfyWorkflowJSON\n  prompt?: ComfyApiWorkflow\n  [key: string]: string | ComfyWorkflowJSON | ComfyApiWorkflow | undefined\n}\n\nexport type EbmlElementRange = {\n  /** Position in the buffer */\n  pos: number\n  /** Length of the element in bytes */\n  len: number\n}\n\nexport type EbmlTagPosition = {\n  name: EbmlElementRange\n  value: EbmlElementRange\n}\n\nexport type VInt = {\n  /** The value of the variable-length integer */\n  value: number\n  /** The length of the variable-length integer in bytes */\n  length: number\n}\n\nexport type TextRange = {\n  start: number\n  end: number\n}\n\nexport enum ASCII {\n  GLTF = 0x46546c67,\n  JSON = 0x4e4f534a,\n  OPEN_BRACE = 0x7b\n}\n\nexport enum GltfSizeBytes {\n  HEADER = 12,\n  CHUNK_HEADER = 8\n}\n\nexport type GltfHeader = {\n  magicNumber: number\n  gltfFormatVersion: number\n  totalLengthBytes: number\n}\n\nexport type GltfChunkHeader = {\n  chunkLengthBytes: number\n  chunkTypeIdentifier: number\n}\n\n/**\n * Represents the content range [start, end) of an ISOBMFF box, excluding its header.\n * Null if the box was not found.\n */\nexport type IsobmffBoxContentRange = { start: number; end: number } | null\n\nexport type AvifInfeBox = {\n  box_header: {\n    size: number\n    type: 'infe'\n  }\n  version: number\n  flags: number\n  item_ID: number\n  item_protection_index: number\n  item_type: string\n  item_name: string\n  content_type?: string\n  content_encoding?: string\n}\n\nexport type AvifIinfBox = {\n  box_header: {\n    size: number\n    type: 'iinf'\n  }\n  version: number\n  flags: number\n  entry_count: number\n  entries: AvifInfeBox[]\n}\n\ntype AvifIlocItemExtent = {\n  extent_offset: number\n  extent_length: number\n}\n\ntype AvifIlocItem = {\n  item_ID: number\n  data_reference_index: number\n  base_offset: number\n  extent_count: number\n  extents: AvifIlocItemExtent[]\n}\n\nexport type AvifIlocBox = {\n  box_header: {\n    size: number\n    type: 'iloc'\n  }\n  version: number\n  flags: number\n  offset_size: number\n  length_size: number\n  base_offset_size: number\n  index_size: number\n  item_count: number\n  items: AvifIlocItem[]\n}\n","/**\n * Reads a file (optionally capped to its first `maxBytes`) into an ArrayBuffer.\n * Resolves `null` when the read errors, aborts, or yields no result, so callers\n * can guard with a single truthiness check before parsing. The underlying\n * `FileReader` error reason is intentionally not surfaced; callers treat any\n * failure as \"no metadata\" rather than distinguishing causes.\n * @param file - The file to read.\n * @param maxBytes - Optional cap; when set, only the first `maxBytes` are read.\n */\nexport function readFileAsArrayBuffer(\n  file: File,\n  maxBytes?: number\n): Promise<ArrayBuffer | null> {\n  return new Promise<ArrayBuffer | null>((resolve) => {\n    const reader = new FileReader()\n    reader.onload = () => {\n      resolve(reader.result instanceof ArrayBuffer ? reader.result : null)\n    }\n    reader.onerror = () => resolve(null)\n    reader.onabort = () => resolve(null)\n    const blob = maxBytes === undefined ? file : file.slice(0, maxBytes)\n    reader.readAsArrayBuffer(blob)\n  })\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { ComfyMetadataTags } from '@/types/metadataTypes'\nimport type {\n  AvifIinfBox,\n  AvifIlocBox,\n  AvifInfeBox,\n  ComfyMetadata,\n  IsobmffBoxContentRange\n} from '@/types/metadataTypes'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nconst readNullTerminatedString = (\n  dataView: DataView,\n  start: number,\n  end: number\n): { str: string; length: number } => {\n  let length = 0\n  while (start + length < end && dataView.getUint8(start + length) !== 0) {\n    length++\n  }\n  const str = new TextDecoder('utf-8').decode(\n    new Uint8Array(dataView.buffer, dataView.byteOffset + start, length)\n  )\n  return { str, length: length + 1 } // Include null terminator\n}\n\nconst parseInfeBox = (dataView: DataView, start: number): AvifInfeBox => {\n  const version = dataView.getUint8(start)\n  const flags = dataView.getUint32(start) & 0xffffff\n  let offset = start + 4\n\n  let item_ID: number, item_protection_index: number, item_type: string\n\n  if (version >= 2) {\n    if (version === 2) {\n      item_ID = dataView.getUint16(offset)\n      offset += 2\n    } else {\n      item_ID = dataView.getUint32(offset)\n      offset += 4\n    }\n\n    item_protection_index = dataView.getUint16(offset)\n    offset += 2\n    item_type = String.fromCharCode(\n      ...new Uint8Array(dataView.buffer, dataView.byteOffset + offset, 4)\n    )\n    offset += 4\n\n    const { str: item_name, length: name_len } = readNullTerminatedString(\n      dataView,\n      offset,\n      dataView.byteLength\n    )\n    offset += name_len\n\n    const content_type = readNullTerminatedString(\n      dataView,\n      offset,\n      dataView.byteLength\n    ).str\n\n    return {\n      box_header: { size: 0, type: 'infe' }, // Size is dynamic\n      version,\n      flags,\n      item_ID,\n      item_protection_index,\n      item_type,\n      item_name,\n      content_type\n    }\n  }\n  throw new Error(`Unsupported infe box version: ${version}`)\n}\n\nconst parseIinfBox = (\n  dataView: DataView,\n  range: IsobmffBoxContentRange\n): AvifIinfBox => {\n  if (!range) throw new Error('iinf box not found')\n\n  const version = dataView.getUint8(range.start)\n  const flags = dataView.getUint32(range.start) & 0xffffff\n  let offset = range.start + 4\n\n  const entry_count =\n    version === 0 ? dataView.getUint16(offset) : dataView.getUint32(offset)\n  offset += version === 0 ? 2 : 4\n\n  const entries: AvifInfeBox[] = []\n  for (let i = 0; i < entry_count; i++) {\n    const boxSize = dataView.getUint32(offset)\n    const boxType = String.fromCharCode(\n      ...new Uint8Array(dataView.buffer, dataView.byteOffset + offset + 4, 4)\n    )\n\n    if (boxType === 'infe') {\n      const infe = parseInfeBox(dataView, offset + 8)\n      infe.box_header.size = boxSize\n      entries.push(infe)\n    }\n    offset += boxSize\n  }\n\n  return {\n    box_header: { size: range.end - range.start + 8, type: 'iinf' },\n    version,\n    flags,\n    entry_count,\n    entries\n  }\n}\n\nconst parseIlocBox = (\n  dataView: DataView,\n  range: IsobmffBoxContentRange\n): AvifIlocBox => {\n  if (!range) throw new Error('iloc box not found')\n\n  const version = dataView.getUint8(range.start)\n  const flags = dataView.getUint32(range.start) & 0xffffff\n  let offset = range.start + 4\n\n  const sizes = dataView.getUint8(offset++)\n  const offset_size = (sizes >> 4) & 0x0f\n  const length_size = sizes & 0x0f\n\n  const base_offset_size = (dataView.getUint8(offset) >> 4) & 0x0f\n  const index_size =\n    version === 1 || version === 2 ? dataView.getUint8(offset) & 0x0f : 0\n  offset++\n\n  const item_count =\n    version < 2 ? dataView.getUint16(offset) : dataView.getUint32(offset)\n  offset += version < 2 ? 2 : 4\n\n  const items = []\n  for (let i = 0; i < item_count; i++) {\n    const item_ID =\n      version < 2 ? dataView.getUint16(offset) : dataView.getUint32(offset)\n    offset += version < 2 ? 2 : 4\n\n    if (version === 1 || version === 2) {\n      offset += 2 // construction_method\n    }\n\n    const data_reference_index = dataView.getUint16(offset)\n    offset += 2\n\n    const base_offset = base_offset_size > 0 ? dataView.getUint32(offset) : 0 // Simplified\n    offset += base_offset_size\n\n    const extent_count = dataView.getUint16(offset)\n    offset += 2\n\n    const extents = []\n    for (let j = 0; j < extent_count; j++) {\n      if ((version === 1 || version === 2) && index_size > 0) {\n        offset += index_size\n      }\n      const extent_offset = dataView.getUint32(offset) // Simplified\n      offset += offset_size\n      const extent_length = dataView.getUint32(offset) // Simplified\n      offset += length_size\n      extents.push({ extent_offset, extent_length })\n    }\n    items.push({\n      item_ID,\n      data_reference_index,\n      base_offset,\n      extent_count,\n      extents\n    })\n  }\n\n  return {\n    box_header: { size: range.end - range.start + 8, type: 'iloc' },\n    version,\n    flags,\n    offset_size,\n    length_size,\n    base_offset_size,\n    index_size,\n    item_count,\n    items\n  }\n}\n\nfunction findBox(\n  dataView: DataView,\n  start: number,\n  end: number,\n  type: string\n): IsobmffBoxContentRange {\n  let offset = start\n  while (offset < end) {\n    if (offset + 8 > end) break\n    const boxLength = dataView.getUint32(offset)\n    const boxType = String.fromCharCode(\n      ...new Uint8Array(dataView.buffer, dataView.byteOffset + offset + 4, 4)\n    )\n\n    if (boxLength === 0) break\n\n    if (boxType === type) {\n      return { start: offset + 8, end: offset + boxLength }\n    }\n    if (offset + boxLength > end) break\n    offset += boxLength\n  }\n  return null\n}\n\nfunction parseAvifMetadata(buffer: ArrayBuffer): ComfyMetadata {\n  const metadata: ComfyMetadata = {}\n  const dataView = new DataView(buffer)\n\n  if (\n    dataView.getUint32(4) !== 0x66747970 ||\n    dataView.getUint32(8) !== 0x61766966\n  ) {\n    console.error('Not a valid AVIF file')\n    return {}\n  }\n\n  const metaBox = findBox(dataView, 0, dataView.byteLength, 'meta')\n  if (!metaBox) return {}\n\n  const metaBoxContentStart = metaBox.start + 4 // Skip version and flags\n\n  const iinfBoxRange = findBox(\n    dataView,\n    metaBoxContentStart,\n    metaBox.end,\n    'iinf'\n  )\n  const iinf = parseIinfBox(dataView, iinfBoxRange)\n\n  const exifInfe = iinf.entries.find((e) => e.item_type === 'Exif')\n  if (!exifInfe) return {}\n\n  const ilocBoxRange = findBox(\n    dataView,\n    metaBoxContentStart,\n    metaBox.end,\n    'iloc'\n  )\n  const iloc = parseIlocBox(dataView, ilocBoxRange)\n\n  const exifIloc = iloc.items.find((i) => i.item_ID === exifInfe.item_ID)\n  if (!exifIloc || exifIloc.extents.length === 0) return {}\n\n  const exifExtent = exifIloc.extents[0]\n  const itemData = new Uint8Array(\n    buffer,\n    exifExtent.extent_offset,\n    exifExtent.extent_length\n  )\n\n  let tiffHeaderOffset = -1\n  for (let i = 0; i < itemData.length - 4; i++) {\n    if (\n      (itemData[i] === 0x4d &&\n        itemData[i + 1] === 0x4d &&\n        itemData[i + 2] === 0x00 &&\n        itemData[i + 3] === 0x2a) || // MM*\n      (itemData[i] === 0x49 &&\n        itemData[i + 1] === 0x49 &&\n        itemData[i + 2] === 0x2a &&\n        itemData[i + 3] === 0x00) // II*\n    ) {\n      tiffHeaderOffset = i\n      break\n    }\n  }\n\n  if (tiffHeaderOffset !== -1) {\n    const exifData = itemData.subarray(tiffHeaderOffset)\n    const data: Record<string, unknown> = parseExifData(exifData)\n    for (const key in data) {\n      const value = data[key]\n      if (typeof value === 'string') {\n        if (key === 'usercomment') {\n          try {\n            const metadataJson = parseJsonWithNonFinite<{\n              prompt?: ComfyApiWorkflow\n              workflow?: ComfyWorkflowJSON\n            }>(value)\n            if (metadataJson.prompt) {\n              metadata[ComfyMetadataTags.PROMPT] = metadataJson.prompt\n            }\n            if (metadataJson.workflow) {\n              metadata[ComfyMetadataTags.WORKFLOW] = metadataJson.workflow\n            }\n          } catch (e) {\n            console.error('Failed to parse usercomment JSON', e)\n          }\n        } else {\n          const [metadataKey, ...metadataValueParts] = value.split(':')\n          const metadataValue = metadataValueParts.join(':').trim()\n          if (\n            metadataKey.toLowerCase() ===\n              ComfyMetadataTags.PROMPT.toLowerCase() ||\n            metadataKey.toLowerCase() ===\n              ComfyMetadataTags.WORKFLOW.toLowerCase()\n          ) {\n            try {\n              const jsonValue = parseJsonWithNonFinite<\n                ComfyApiWorkflow | ComfyWorkflowJSON\n              >(metadataValue)\n              metadata[metadataKey.toLowerCase() as keyof ComfyMetadata] =\n                jsonValue\n            } catch (e) {\n              console.error(`Failed to parse JSON for ${metadataKey}`, e)\n            }\n          }\n        }\n      }\n    }\n  } else {\n    console.warn('TIFF header not found in EXIF data.')\n  }\n\n  return metadata\n}\n\nfunction parseExifData(exifData: Uint8Array) {\n  // Check for the correct TIFF header (0x4949 for little-endian or 0x4D4D for big-endian)\n  const isLittleEndian = String.fromCharCode(...exifData.slice(0, 2)) === 'II'\n\n  // Function to read 16-bit and 32-bit integers from binary data\n  function readInt(\n    offset: number,\n    isLittleEndian: boolean,\n    length: 2 | 4\n  ): number {\n    const arr = exifData.slice(offset, offset + length)\n    if (length === 2) {\n      return new DataView(arr.buffer, arr.byteOffset, arr.byteLength).getUint16(\n        0,\n        isLittleEndian\n      )\n    }\n    return new DataView(arr.buffer, arr.byteOffset, arr.byteLength).getUint32(\n      0,\n      isLittleEndian\n    )\n  }\n\n  // Read the offset to the first IFD (Image File Directory)\n  const ifdOffset = readInt(4, isLittleEndian, 4)\n\n  function parseIFD(offset: number) {\n    const numEntries = readInt(offset, isLittleEndian, 2)\n    const result: Record<number, string | undefined> = {}\n\n    for (let i = 0; i < numEntries; i++) {\n      const entryOffset = offset + 2 + i * 12\n      const tag = readInt(entryOffset, isLittleEndian, 2)\n      const type = readInt(entryOffset + 2, isLittleEndian, 2)\n      const numValues = readInt(entryOffset + 4, isLittleEndian, 4)\n      const valueOffset = readInt(entryOffset + 8, isLittleEndian, 4)\n\n      // Read the value(s) based on the data type\n      let value\n      if (type === 2) {\n        // ASCII string\n        value = new TextDecoder('utf-8').decode(\n          exifData.subarray(valueOffset, valueOffset + numValues - 1)\n        )\n      }\n\n      result[tag] = value\n    }\n\n    return result\n  }\n\n  // Parse the first IFD\n  const ifdData = parseIFD(ifdOffset)\n  return ifdData\n}\n\nexport async function getFromAvifFile(\n  file: File\n): Promise<Record<string, string>> {\n  const buffer = await readFileAsArrayBuffer(file)\n  if (!buffer) return {}\n\n  try {\n    const comfyMetadata = parseAvifMetadata(buffer)\n    const result: Record<string, string> = {}\n    if (comfyMetadata.prompt) {\n      result.prompt = JSON.stringify(comfyMetadata.prompt)\n    }\n    if (comfyMetadata.workflow) {\n      result.workflow = JSON.stringify(comfyMetadata.workflow)\n    }\n    return result\n  } catch (e) {\n    console.error('Parser: Error parsing AVIF metadata:', e)\n    return {}\n  }\n}\n","import { readFileAsArrayBuffer } from '@/utils/fileUtil'\n\nexport function getFromFlacBuffer(buffer: ArrayBuffer): Record<string, string> {\n  const dataView = new DataView(buffer)\n\n  // Verify the FLAC signature\n  const signature = String.fromCharCode(...new Uint8Array(buffer, 0, 4))\n  if (signature !== 'fLaC') {\n    console.error('Not a valid FLAC file')\n    return {}\n  }\n\n  // Parse metadata blocks\n  let offset = 4\n  let vorbisComment = null\n  while (offset < dataView.byteLength) {\n    const isLastBlock = dataView.getUint8(offset) & 0x80\n    const blockType = dataView.getUint8(offset) & 0x7f\n    const blockSize = dataView.getUint32(offset, false) & 0xffffff\n    offset += 4\n\n    if (blockType === 4) {\n      // Vorbis Comment block type\n      vorbisComment = parseVorbisComment(\n        new DataView(buffer, offset, blockSize)\n      )\n    }\n\n    offset += blockSize\n    if (isLastBlock) break\n  }\n\n  return vorbisComment ?? {}\n}\n\nexport async function getFromFlacFile(\n  file: File\n): Promise<Record<string, string>> {\n  const buffer = await readFileAsArrayBuffer(file)\n  if (!buffer) return {}\n\n  try {\n    return getFromFlacBuffer(buffer)\n  } catch (e) {\n    console.error('Parser: Error parsing FLAC metadata:', e)\n    return {}\n  }\n}\n\n// Function to parse the Vorbis Comment block\nfunction parseVorbisComment(dataView: DataView): Record<string, string> {\n  let offset = 0\n  const vendorLength = dataView.getUint32(offset, true)\n  offset += 4 + vendorLength\n\n  const userCommentListLength = dataView.getUint32(offset, true)\n  offset += 4\n  const comments: Record<string, string> = {}\n  for (let i = 0; i < userCommentListLength; i++) {\n    const commentLength = dataView.getUint32(offset, true)\n    offset += 4\n    const comment = getString(dataView, offset, commentLength)\n    offset += commentLength\n\n    const ind = comment.indexOf('=')\n    const key = comment.substring(0, ind)\n\n    comments[key] = comment.substring(ind + 1)\n  }\n\n  return comments\n}\n\nfunction getString(dataView: DataView, offset: number, length: number): string {\n  let string = ''\n  for (let i = 0; i < length; i++) {\n    string += String.fromCharCode(dataView.getUint8(offset + i))\n  }\n  return string\n}\n","async function decompressZlib(\n  data: Uint8Array<ArrayBuffer>\n): Promise<Uint8Array<ArrayBuffer>> {\n  const stream = new DecompressionStream('deflate')\n  const writer = stream.writable.getWriter()\n  try {\n    await writer.write(data)\n    await writer.close()\n  } finally {\n    writer.releaseLock()\n  }\n\n  const reader = stream.readable.getReader()\n  const chunks: Uint8Array<ArrayBuffer>[] = []\n  let totalLength = 0\n\n  try {\n    for (;;) {\n      const { done, value } = await reader.read()\n      if (done) break\n      chunks.push(value)\n      totalLength += value.length\n    }\n  } finally {\n    reader.releaseLock()\n  }\n\n  const result = new Uint8Array(totalLength)\n  let offset = 0\n  for (const chunk of chunks) {\n    result.set(chunk, offset)\n    offset += chunk.length\n  }\n  return result\n}\n\nexport async function getFromPngBuffer(\n  buffer: ArrayBuffer\n): Promise<Record<string, string>> {\n  const pngData = new Uint8Array(buffer)\n  const dataView = new DataView(pngData.buffer)\n\n  if (dataView.getUint32(0) !== 0x89504e47) {\n    console.error('Not a valid PNG file')\n    return {}\n  }\n\n  let offset = 8\n  const txt_chunks: Record<string, string> = {}\n\n  while (offset < pngData.length) {\n    const length = dataView.getUint32(offset)\n    const type = String.fromCharCode(...pngData.slice(offset + 4, offset + 8))\n\n    if (type === 'tEXt' || type === 'comf' || type === 'iTXt') {\n      let keyword_end = offset + 8\n      while (pngData[keyword_end] !== 0) {\n        keyword_end++\n      }\n      const keyword = String.fromCharCode(\n        ...pngData.slice(offset + 8, keyword_end)\n      )\n\n      let textStart = keyword_end + 1\n      let isCompressed = false\n      let compressionMethod = 0\n\n      if (type === 'iTXt') {\n        const chunkEnd = offset + 8 + length\n        isCompressed = pngData[textStart] === 1\n        compressionMethod = pngData[textStart + 1]\n        textStart += 2\n\n        while (pngData[textStart] !== 0 && textStart < chunkEnd) {\n          textStart++\n        }\n        if (textStart < chunkEnd) textStart++\n\n        while (pngData[textStart] !== 0 && textStart < chunkEnd) {\n          textStart++\n        }\n        if (textStart < chunkEnd) textStart++\n      }\n\n      let contentArraySegment = pngData.slice(textStart, offset + 8 + length)\n\n      if (isCompressed) {\n        if (compressionMethod === 0) {\n          try {\n            contentArraySegment = await decompressZlib(contentArraySegment)\n          } catch (e) {\n            console.error(`Failed to decompress iTXt chunk \"${keyword}\":`, e)\n            offset += 12 + length\n            continue\n          }\n        } else {\n          console.warn(\n            `Unsupported compression method ${compressionMethod} for iTXt chunk \"${keyword}\"`\n          )\n          offset += 12 + length\n          continue\n        }\n      }\n\n      const contentJson = new TextDecoder('utf-8').decode(contentArraySegment)\n      txt_chunks[keyword] = contentJson\n    }\n\n    offset += 12 + length\n  }\n  return txt_chunks\n}\n\nexport async function getFromPngFile(\n  file: File\n): Promise<Record<string, string>> {\n  return new Promise<Record<string, string>>((resolve, reject) => {\n    const reader = new FileReader()\n    reader.onload = async (event) => {\n      const buffer = event.target?.result\n      if (!(buffer instanceof ArrayBuffer)) {\n        reject(new Error('Failed to read file as ArrayBuffer'))\n        return\n      }\n      const result = await getFromPngBuffer(buffer)\n      resolve(result)\n    }\n    reader.onerror = () => reject(reader.error)\n    reader.onabort = () => reject(new Error('FileReader aborted'))\n    reader.readAsArrayBuffer(file)\n  })\n}\n","import type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { withGraphIntentSource } from '@/lib/litegraph/src/graphIntents'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\n\nimport { api } from './api'\nimport { getFromAvifFile } from './metadata/avif'\nimport { getFromFlacFile } from './metadata/flac'\nimport { getFromPngFile } from './metadata/png'\n\n// Original functions left in for backwards compatibility\nexport function getPngMetadata(file: File): Promise<Record<string, string>> {\n  return getFromPngFile(file)\n}\n\nexport function getFlacMetadata(file: File): Promise<Record<string, string>> {\n  return getFromFlacFile(file)\n}\n\nexport function getAvifMetadata(file: File): Promise<Record<string, string>> {\n  return getFromAvifFile(file)\n}\n\nfunction parseExifData(exifData: Uint8Array) {\n  // Check for the correct TIFF header (0x4949 for little-endian or 0x4D4D for big-endian)\n  const isLittleEndian = String.fromCharCode(...exifData.slice(0, 2)) === 'II'\n\n  // Function to read 16-bit and 32-bit integers from binary data\n  function readInt(\n    offset: number,\n    isLittleEndian: boolean,\n    length: 2 | 4\n  ): number {\n    const arr = exifData.slice(offset, offset + length)\n    const view = new DataView(arr.buffer, arr.byteOffset, arr.byteLength)\n    return length === 2\n      ? view.getUint16(0, isLittleEndian)\n      : view.getUint32(0, isLittleEndian)\n  }\n\n  // Read the offset to the first IFD (Image File Directory)\n  const ifdOffset = readInt(4, isLittleEndian, 4)\n\n  function parseIFD(offset: number): Record<number, string | undefined> {\n    const numEntries = readInt(offset, isLittleEndian, 2)\n    const result: Record<number, string | undefined> = {}\n\n    for (let i = 0; i < numEntries; i++) {\n      const entryOffset = offset + 2 + i * 12\n      const tag = readInt(entryOffset, isLittleEndian, 2)\n      const type = readInt(entryOffset + 2, isLittleEndian, 2)\n      const numValues = readInt(entryOffset + 4, isLittleEndian, 4)\n      const valueOffset = readInt(entryOffset + 8, isLittleEndian, 4)\n\n      // Read the value(s) based on the data type\n      let value\n      if (type === 2) {\n        // ASCII string\n        value = new TextDecoder('utf-8').decode(\n          exifData.subarray(valueOffset, valueOffset + numValues - 1)\n        )\n      }\n\n      result[tag] = value\n    }\n\n    return result\n  }\n\n  // Parse the first IFD\n  const ifdData = parseIFD(ifdOffset)\n  return ifdData\n}\n\nexport function getWebpMetadata(file: File) {\n  return new Promise<Record<string, string>>((r) => {\n    const reader = new FileReader()\n    reader.onload = (event) => {\n      const webp = new Uint8Array(event.target?.result as ArrayBuffer)\n      const dataView = new DataView(webp.buffer)\n\n      // Check that the WEBP signature is present\n      if (\n        dataView.getUint32(0) !== 0x52494646 ||\n        dataView.getUint32(8) !== 0x57454250\n      ) {\n        console.error('Not a valid WEBP file')\n        r({})\n        return\n      }\n\n      // Start searching for chunks after the WEBP signature\n      let offset = 12\n      const txt_chunks: Record<string, string> = {}\n      // Loop through the chunks in the WEBP file\n      while (offset < webp.length) {\n        const chunk_length = dataView.getUint32(offset + 4, true)\n        const chunk_type = String.fromCharCode(\n          ...webp.slice(offset, offset + 4)\n        )\n        if (chunk_type === 'EXIF') {\n          let exifOffset = offset + 8\n          let exifLength = chunk_length\n          if (\n            String.fromCharCode(...webp.slice(exifOffset, exifOffset + 6)) ==\n            'Exif\\0\\0'\n          ) {\n            exifOffset += 6\n            exifLength -= 6\n          }\n          const data = parseExifData(\n            webp.slice(exifOffset, exifOffset + exifLength)\n          )\n          for (const key in data) {\n            const value = data[Number(key)]\n            if (typeof value === 'string') {\n              const index = value.indexOf(':')\n              txt_chunks[value.slice(0, index)] = value.slice(index + 1)\n            }\n          }\n          break\n        }\n\n        // RIFF spec requires odd-sized chunks to be padded with a single byte\n        // https://developers.google.com/speed/webp/docs/riff_container#riff_file_format\n        offset += 8 + chunk_length + (chunk_length % 2)\n      }\n\n      r(txt_chunks)\n    }\n    reader.onerror = () => r({})\n    reader.onabort = () => r({})\n    reader.readAsArrayBuffer(file)\n  })\n}\n\nexport function getLatentMetadata(\n  file: File\n): Promise<Record<string, string> | undefined> {\n  return new Promise((r) => {\n    const reader = new FileReader()\n    reader.onload = (event) => {\n      try {\n        const safetensorsData = new Uint8Array(\n          event.target?.result as ArrayBuffer\n        )\n        const dataView = new DataView(safetensorsData.buffer)\n        const headerSize = dataView.getUint32(0, true)\n        const offset = 8\n        const header = JSON.parse(\n          new TextDecoder().decode(\n            safetensorsData.slice(offset, offset + headerSize)\n          )\n        )\n        r(header.__metadata__)\n      } catch {\n        r(undefined)\n      }\n    }\n    reader.onerror = () => r(undefined)\n    reader.onabort = () => r(undefined)\n    const slice = file.slice(0, 1024 * 1024 * 4)\n    reader.readAsArrayBuffer(slice)\n  })\n}\n\ninterface NodeConnection {\n  node: LGraphNode\n  index: number\n}\n\ninterface LoraEntry {\n  name: string\n  weight: number\n}\n\nconst A1111_NEGATIVE_PROMPT_PREFIX = '\\nNegative prompt:'\n\nfunction normalizeA1111Parameters(parameters: string): string {\n  const stepsIndex = parameters.lastIndexOf('\\nSteps:')\n  if (\n    stepsIndex === -1 ||\n    parameters.lastIndexOf(A1111_NEGATIVE_PROMPT_PREFIX, stepsIndex) > -1\n  ) {\n    return parameters\n  }\n\n  return `${parameters.slice(0, stepsIndex)}${A1111_NEGATIVE_PROMPT_PREFIX}${parameters.slice(stepsIndex)}`\n}\n\nexport type A1111ImportOutcome =\n  | 'imported'\n  | 'imported-without-embeddings'\n  | 'not-a1111'\n  | 'core-nodes-unavailable'\n\nexport async function importA1111(\n  graph: LGraph,\n  parameters: string,\n  beforeGraphClear?: () => void | Promise<void>\n): Promise<A1111ImportOutcome> {\n  const normalizedParameters = normalizeA1111Parameters(parameters)\n  const p = normalizedParameters.lastIndexOf('\\nSteps:')\n  if (p > -1) {\n    const matchResult = normalizedParameters\n      .substr(p)\n      .split('\\n')[1]\n      .match(\n        new RegExp('\\\\s*([^:]+:\\\\s*([^\"\\\\{].*?|\".*?\"|\\\\{.*?\\\\}))\\\\s*(,|$)', 'g')\n      )\n    if (!matchResult) return 'not-a1111'\n\n    const opts: Partial<Record<string, string>> = matchResult.reduce(\n      (acc: Record<string, string>, n: string) => {\n        const s = n.split(':')\n        if (s[1].endsWith(',')) {\n          s[1] = s[1].substr(0, s[1].length - 1)\n        }\n        acc[s[0].trim().toLowerCase()] = s[1].trim()\n        return acc\n      },\n      {}\n    )\n    const p2 = normalizedParameters.lastIndexOf(A1111_NEGATIVE_PROMPT_PREFIX, p)\n    if (p2 > -1) {\n      let positive = normalizedParameters.substr(0, p2).trim()\n      let negative = normalizedParameters\n        .substring(p2 + A1111_NEGATIVE_PROMPT_PREFIX.length, p)\n        .trim()\n\n      const ckptNode = LiteGraph.createNode('CheckpointLoaderSimple')\n      const clipSkipNode = LiteGraph.createNode('CLIPSetLastLayer')\n      const positiveNode = LiteGraph.createNode('CLIPTextEncode')\n      const negativeNode = LiteGraph.createNode('CLIPTextEncode')\n      const samplerNode = LiteGraph.createNode('KSampler')\n      const imageNode = LiteGraph.createNode('EmptyLatentImage')\n      const vaeNode = LiteGraph.createNode('VAEDecode')\n      const saveNode = LiteGraph.createNode('SaveImage')\n\n      if (\n        !ckptNode ||\n        !clipSkipNode ||\n        !positiveNode ||\n        !negativeNode ||\n        !samplerNode ||\n        !imageNode ||\n        !vaeNode ||\n        !saveNode\n      ) {\n        console.error('Failed to create required nodes for A1111 import')\n        return 'core-nodes-unavailable'\n      }\n\n      const hires: { samplerNode: LGraphNode | null; steps?: string } = {\n        samplerNode: null\n      }\n\n      const ceil64 = (v: number) => Math.ceil(v / 64) * 64\n\n      function getWidget(\n        node: LGraphNode | null,\n        name: string\n      ): IBaseWidget | undefined {\n        return node?.widgets?.find((w) => w.name === name)\n      }\n\n      function setWidgetValue(\n        node: LGraphNode | null,\n        name: string,\n        value: string | number,\n        isOptionPrefix?: boolean\n      ): void {\n        const w = getWidget(node, name)\n        if (!w) return\n\n        if (isOptionPrefix) {\n          const values = w.options.values as string[] | undefined\n          const o = values?.find((v) => v.startsWith(String(value)))\n          if (o) {\n            w.value = o\n          } else {\n            console.warn(`Unknown value '${value}' for widget '${name}'`, node)\n            w.value = value\n          }\n        } else {\n          w.value = value\n        }\n      }\n\n      function createLoraNodes(\n        clipNode: LGraphNode,\n        text: string,\n        prevClip: NodeConnection,\n        prevModel: NodeConnection,\n        targetSamplerNode: LGraphNode\n      ): { text: string; prevModel: NodeConnection; prevClip: NodeConnection } {\n        const loras: LoraEntry[] = []\n        text = text.replace(/<lora:([^:]+:[^>]+)>/g, (_m, c: string) => {\n          const s = c.split(':')\n          const weight = parseFloat(s[1])\n          if (isNaN(weight)) {\n            console.warn('Invalid LORA', _m)\n          } else {\n            loras.push({ name: s[0], weight })\n          }\n          return ''\n        })\n\n        for (const l of loras) {\n          const loraNode = LiteGraph.createNode('LoraLoader')\n          if (!loraNode) continue\n          graph.add(loraNode)\n          setWidgetValue(loraNode, 'lora_name', l.name, true)\n          setWidgetValue(loraNode, 'strength_model', l.weight)\n          setWidgetValue(loraNode, 'strength_clip', l.weight)\n          prevModel.node.connect(prevModel.index, loraNode, 0)\n          prevClip.node.connect(prevClip.index, loraNode, 1)\n          prevModel = { node: loraNode, index: 0 }\n          prevClip = { node: loraNode, index: 1 }\n        }\n\n        prevClip.node.connect(1, clipNode, 0)\n        prevModel.node.connect(0, targetSamplerNode, 0)\n        if (hires.samplerNode) {\n          prevModel.node.connect(0, hires.samplerNode, 0)\n        }\n\n        return { text, prevModel, prevClip }\n      }\n\n      function replaceEmbeddings(text: string): string {\n        if (!embeddings.length) return text\n        return text.replaceAll(\n          new RegExp(\n            '\\\\b(' +\n              embeddings\n                .map((e) => e.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'))\n                .join('\\\\b|\\\\b') +\n              ')\\\\b',\n            'ig'\n          ),\n          'embedding:$1'\n        )\n      }\n\n      function popOpt(name: string): string | undefined {\n        const v = opts[name]\n        delete opts[name]\n        return v\n      }\n\n      const { embeddings, embeddingsLoaded } = await api\n        .getEmbeddings()\n        .then((embeddings) => ({ embeddings, embeddingsLoaded: true }))\n        .catch((error: unknown) => {\n          console.error('Failed to load embeddings for A1111 import:', error)\n          return { embeddings: [], embeddingsLoaded: false }\n        })\n\n      await beforeGraphClear?.()\n      withGraphIntentSource('load', () => {\n        graph.clear()\n        graph.add(ckptNode)\n        graph.add(clipSkipNode)\n        graph.add(positiveNode)\n        graph.add(negativeNode)\n        graph.add(samplerNode)\n        graph.add(imageNode)\n        graph.add(vaeNode)\n        graph.add(saveNode)\n\n        ckptNode.connect(1, clipSkipNode, 0)\n        clipSkipNode.connect(0, positiveNode, 0)\n        clipSkipNode.connect(0, negativeNode, 0)\n        ckptNode.connect(0, samplerNode, 0)\n        positiveNode.connect(0, samplerNode, 1)\n        negativeNode.connect(0, samplerNode, 2)\n        imageNode.connect(0, samplerNode, 3)\n        vaeNode.connect(0, saveNode, 0)\n        samplerNode.connect(0, vaeNode, 0)\n        ckptNode.connect(2, vaeNode, 1)\n\n        const handlers: Partial<Record<string, (v: string) => void>> = {\n          model(v: string) {\n            setWidgetValue(ckptNode, 'ckpt_name', v, true)\n          },\n          vae() {},\n          'cfg scale'(v: string) {\n            setWidgetValue(samplerNode, 'cfg', +v)\n          },\n          'clip skip'(v: string) {\n            setWidgetValue(clipSkipNode, 'stop_at_clip_layer', -Number(v))\n          },\n          sampler(v: string) {\n            let name = v.toLowerCase().replace('++', 'pp').replaceAll(' ', '_')\n            if (name.includes('karras')) {\n              name = name.replace('karras', '').replace(/_+$/, '')\n              setWidgetValue(samplerNode, 'scheduler', 'karras')\n            } else {\n              setWidgetValue(samplerNode, 'scheduler', 'normal')\n            }\n            const w = getWidget(samplerNode, 'sampler_name')\n            const values = w?.options.values as string[] | undefined\n            const o = values?.find((v) => v === name || v === 'sample_' + name)\n            if (o) {\n              setWidgetValue(samplerNode, 'sampler_name', o)\n            }\n          },\n          // fallow-ignore-next-line complexity -- legacy A1111 size/hires importer; this PR only scopes its existing branches under load provenance.\n          size(v: string) {\n            const wxh = v.split('x')\n            const w = ceil64(+wxh[0])\n            const h = ceil64(+wxh[1])\n            const hrUp = popOpt('hires upscale')\n            const hrSz = popOpt('hires resize')\n            hires.steps = popOpt('hires steps')\n            let hrMethod = popOpt('hires upscaler')\n\n            setWidgetValue(imageNode, 'width', w)\n            setWidgetValue(imageNode, 'height', h)\n\n            if (hrUp || hrSz) {\n              let uw: number, uh: number\n              if (hrUp) {\n                uw = w * Number(hrUp)\n                uh = h * Number(hrUp)\n              } else if (hrSz) {\n                const s = hrSz.split('x')\n                uw = +s[0]\n                uh = +s[1]\n              } else {\n                return\n              }\n\n              let upscaleNode: LGraphNode | null\n              let latentNode: LGraphNode | null\n\n              if (hrMethod?.startsWith('Latent')) {\n                latentNode = upscaleNode = LiteGraph.createNode('LatentUpscale')\n                if (!upscaleNode) return\n                graph.add(upscaleNode)\n                samplerNode.connect(0, upscaleNode, 0)\n\n                switch (hrMethod) {\n                  case 'Latent (nearest-exact)':\n                    hrMethod = 'nearest-exact'\n                    break\n                }\n                setWidgetValue(upscaleNode, 'upscale_method', hrMethod, true)\n              } else {\n                const decode = LiteGraph.createNode('VAEDecodeTiled')\n                if (!decode) return\n                graph.add(decode)\n                samplerNode.connect(0, decode, 0)\n                ckptNode.connect(2, decode, 1)\n\n                const upscaleLoaderNode =\n                  LiteGraph.createNode('UpscaleModelLoader')\n                if (!upscaleLoaderNode) return\n                graph.add(upscaleLoaderNode)\n                setWidgetValue(\n                  upscaleLoaderNode,\n                  'model_name',\n                  hrMethod ?? '',\n                  true\n                )\n\n                const modelUpscaleNode = LiteGraph.createNode(\n                  'ImageUpscaleWithModel'\n                )\n                if (!modelUpscaleNode) return\n                graph.add(modelUpscaleNode)\n                decode.connect(0, modelUpscaleNode, 1)\n                upscaleLoaderNode.connect(0, modelUpscaleNode, 0)\n\n                upscaleNode = LiteGraph.createNode('ImageScale')\n                if (!upscaleNode) return\n                graph.add(upscaleNode)\n                modelUpscaleNode.connect(0, upscaleNode, 0)\n\n                const vaeEncodeNode = LiteGraph.createNode('VAEEncodeTiled')\n                if (!vaeEncodeNode) return\n                latentNode = vaeEncodeNode\n                graph.add(vaeEncodeNode)\n                upscaleNode.connect(0, vaeEncodeNode, 0)\n                ckptNode.connect(2, vaeEncodeNode, 1)\n              }\n\n              setWidgetValue(upscaleNode, 'width', ceil64(uw))\n              setWidgetValue(upscaleNode, 'height', ceil64(uh))\n\n              const hrSamplerNode = LiteGraph.createNode('KSampler')\n              if (!hrSamplerNode || !latentNode) return\n              hires.samplerNode = hrSamplerNode\n              graph.add(hrSamplerNode)\n              ckptNode.connect(0, hrSamplerNode, 0)\n              positiveNode.connect(0, hrSamplerNode, 1)\n              negativeNode.connect(0, hrSamplerNode, 2)\n              latentNode.connect(0, hrSamplerNode, 3)\n              hrSamplerNode.connect(0, vaeNode, 0)\n            }\n          },\n          steps(v: string) {\n            setWidgetValue(samplerNode, 'steps', +v)\n          },\n          seed(v: string) {\n            setWidgetValue(samplerNode, 'seed', +v)\n          }\n        }\n\n        for (const opt in opts) {\n          const handler = handlers[opt]\n          if (handler) {\n            const value = popOpt(opt)\n            if (value !== undefined) handler(value)\n          }\n        }\n\n        const { samplerNode: hrSamplerNode, steps: hrSteps } = hires\n        if (hrSamplerNode) {\n          setWidgetValue(\n            hrSamplerNode,\n            'steps',\n            hrSteps\n              ? +hrSteps\n              : (getWidget(samplerNode, 'steps')?.value as number)\n          )\n          setWidgetValue(\n            hrSamplerNode,\n            'cfg',\n            getWidget(samplerNode, 'cfg')?.value as number\n          )\n          setWidgetValue(\n            hrSamplerNode,\n            'scheduler',\n            getWidget(samplerNode, 'scheduler')?.value as string\n          )\n          setWidgetValue(\n            hrSamplerNode,\n            'sampler_name',\n            getWidget(samplerNode, 'sampler_name')?.value as string\n          )\n          setWidgetValue(\n            hrSamplerNode,\n            'denoise',\n            +(popOpt('denoising strength') ?? '1')\n          )\n        }\n\n        let n = createLoraNodes(\n          positiveNode,\n          positive,\n          { node: clipSkipNode, index: 0 },\n          { node: ckptNode, index: 0 },\n          samplerNode\n        )\n        positive = n.text\n        n = createLoraNodes(\n          negativeNode,\n          negative,\n          n.prevClip,\n          n.prevModel,\n          samplerNode\n        )\n        negative = n.text\n\n        setWidgetValue(positiveNode, 'text', replaceEmbeddings(positive))\n        setWidgetValue(negativeNode, 'text', replaceEmbeddings(negative))\n\n        graph.arrange()\n      })\n\n      for (const opt of [\n        'model hash',\n        'ensd',\n        'version',\n        'vae hash',\n        'ti hashes',\n        'lora hashes',\n        'hashes'\n      ]) {\n        delete opts[opt]\n      }\n\n      if (Object.keys(opts).length) {\n        console.warn('Unhandled parameters:', opts)\n      }\n      return embeddingsLoaded ? 'imported' : 'imported-without-embeddings'\n    }\n  }\n  return 'not-a1111'\n}\n","import { promotedInputSource } from '@/core/graph/subgraph/promotedInputWidget'\nimport { resolveConcretePromotedWidget } from '@/core/graph/subgraph/resolveConcretePromotedWidget'\nimport {\n  isValueControlWidget,\n  nextValueForLinkedTarget\n} from '@/core/graph/widgets/valueControl'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\n/**\n * A promoted subgraph host widget whose interior source widget is driven by a\n * `control_after_generate` widget. The host owns the value (store-backed), while\n * the interior linked widgets supply the control mode and filter (ADR-SUBGRAPH-PROMOTION-0009).\n */\ninterface PromotedControlTarget {\n  hostWidget: IBaseWidget\n  linkedWidgets: IBaseWidget[]\n}\n\nfunction collectPromotedControlTargets(\n  node: LGraphNode\n): PromotedControlTarget[] {\n  if (!node.isSubgraphNode()) return []\n\n  const targets: PromotedControlTarget[] = []\n  for (const [index, input] of node.inputs.entries()) {\n    // Promoted inputs are store-backed and addressed by widgetId.\n    if (!input.widgetId) continue\n\n    // An incoming link means the value is fed externally (or by an outer\n    // subgraph boundary in the nested case), so the host store is not the\n    // authoritative source and control must not run here.\n    if (node.isInputConnected(index)) continue\n\n    const source = promotedInputSource(node, input)\n    if (!source) continue\n\n    const resolution = resolveConcretePromotedWidget(\n      node,\n      source.nodeId,\n      source.widgetName\n    )\n    if (resolution.status !== 'resolved') continue\n\n    const { linkedWidgets } = resolution.resolved.widget\n    if (!linkedWidgets?.some(isValueControlWidget)) continue\n\n    const hostWidget = node.getWidgetFromSlot(input)\n    if (!hostWidget) continue\n\n    targets.push({ hostWidget, linkedWidgets })\n  }\n  return targets\n}\n\nfunction applyTarget(target: PromotedControlTarget, nodeId: unknown): void {\n  const next = nextValueForLinkedTarget({\n    target: target.hostWidget,\n    linkedWidgets: target.linkedWidgets,\n    nodeId\n  })\n  if (next === undefined) return\n\n  target.hostWidget.value = next\n  target.hostWidget.callback?.(next)\n}\n\nfunction controlValueRunBefore(): boolean {\n  return useSettingStore().get('Comfy.WidgetControlMode') === 'before'\n}\n\n/**\n * Host widgets that have run control at least once, so `before` mode can skip\n * the first execution (mirroring the interior control widget's HAS_EXECUTED).\n *\n * Keyed by the widget instance so entries are released when the graph is\n * cleared and its widgets are recreated, avoiding stale state across reloads.\n */\nconst executedWidgets = new WeakSet<IBaseWidget>()\n\n/**\n * Applies `control_after_generate` to a subgraph host node's promoted widgets.\n *\n * The interior control widget short-circuits for promoted inputs because the\n * interior widget is link-fed by the subgraph boundary, so its value is dead.\n * The authoritative value lives on the host node (store-backed), and this\n * applies the next controlled value there.\n */\nexport function applyPromotedWidgetControl(\n  node: LGraphNode,\n  phase: 'beforeQueued' | 'afterQueued'\n): void {\n  const runBefore = controlValueRunBefore()\n  if (phase === 'beforeQueued' && !runBefore) return\n  if (phase === 'afterQueued' && runBefore) return\n\n  for (const target of collectPromotedControlTargets(node)) {\n    if (phase === 'afterQueued') {\n      applyTarget(target, node.id)\n      continue\n    }\n\n    if (executedWidgets.has(target.hostWidget)) {\n      applyTarget(target, node.id)\n    }\n    executedWidgets.add(target.hostWidget)\n  }\n}\n","/**\n * Supported workflow file formats organized by type category\n */\n\n/**\n * All supported image formats that can contain workflow data\n */\nconst IMAGE_WORKFLOW_FORMATS = {\n  extensions: ['.png', '.webp', '.svg', '.avif'],\n  mimeTypes: ['image/png', 'image/webp', 'image/svg+xml', 'image/avif']\n}\n\n/**\n * All supported audio formats that can contain workflow data\n */\nconst AUDIO_WORKFLOW_FORMATS = {\n  extensions: ['.mp3', '.ogg', '.flac'],\n  mimeTypes: ['audio/mpeg', 'audio/ogg', 'audio/flac', 'audio/x-flac']\n}\n\n/**\n * All supported video formats that can contain workflow data\n */\nconst VIDEO_WORKFLOW_FORMATS = {\n  extensions: ['.mp4', '.mov', '.m4v', '.webm'],\n  mimeTypes: ['video/mp4', 'video/quicktime', 'video/x-m4v', 'video/webm']\n}\n\n/**\n * All supported 3D model formats that can contain workflow data\n */\nconst MODEL_WORKFLOW_FORMATS = {\n  extensions: ['.glb'],\n  mimeTypes: ['model/gltf-binary']\n}\n\n/**\n * All supported data formats that directly contain workflow data\n */\nconst DATA_WORKFLOW_FORMATS = {\n  extensions: ['.json', '.latent', '.safetensors'],\n  mimeTypes: ['application/json']\n}\n\n/**\n * Combines all supported formats into a single object\n */\nconst ALL_WORKFLOW_FORMATS = {\n  extensions: [\n    ...IMAGE_WORKFLOW_FORMATS.extensions,\n    ...AUDIO_WORKFLOW_FORMATS.extensions,\n    ...VIDEO_WORKFLOW_FORMATS.extensions,\n    ...MODEL_WORKFLOW_FORMATS.extensions,\n    ...DATA_WORKFLOW_FORMATS.extensions\n  ],\n  mimeTypes: [\n    ...IMAGE_WORKFLOW_FORMATS.mimeTypes,\n    ...AUDIO_WORKFLOW_FORMATS.mimeTypes,\n    ...VIDEO_WORKFLOW_FORMATS.mimeTypes,\n    ...MODEL_WORKFLOW_FORMATS.mimeTypes,\n    ...DATA_WORKFLOW_FORMATS.mimeTypes\n  ]\n}\n\n/**\n * Generate a comma-separated accept string for file inputs\n * Combines all extensions and mime types\n */\nexport const WORKFLOW_ACCEPT_STRING = [\n  ...ALL_WORKFLOW_FORMATS.extensions,\n  ...ALL_WORKFLOW_FORMATS.mimeTypes\n].join(',')\n","import { $el } from './utils'\n\nexport class ComfyDialog<\n  T extends HTMLElement = HTMLElement\n> extends EventTarget {\n  element: T\n  textElement!: HTMLElement\n  private _buttons: HTMLButtonElement[] | null\n\n  constructor(type = 'div', buttons: HTMLButtonElement[] | null = null) {\n    super()\n    this._buttons = buttons\n    this.element = $el(type + '.comfy-modal', { parent: document.body }, [\n      $el('div.comfy-modal-content', [\n        $el('p', { $: (p) => (this.textElement = p) }),\n        ...this.createButtons()\n      ])\n    ]) as T\n  }\n\n  createButtons() {\n    return (\n      this._buttons ?? [\n        $el('button', {\n          type: 'button',\n          textContent: 'Close',\n          onclick: () => this.close()\n        })\n      ]\n    )\n  }\n\n  close() {\n    this.element.style.display = 'none'\n  }\n\n  show(html: string | HTMLElement | HTMLElement[]): void {\n    if (typeof html === 'string') {\n      this.textElement.innerHTML = html\n    } else {\n      this.textElement.replaceChildren(\n        ...(html instanceof Array ? html : [html])\n      )\n    }\n    this.element.style.display = 'flex'\n  }\n}\n","import { t } from '@/i18n'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { SettingParams, Settings } from '@/platform/settings/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { ComfyApp } from '@/types/comfy'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nimport { ComfyDialog } from './dialog'\n\nfunction saveSetting<K extends keyof Settings>(id: K, value: Settings[K]) {\n  useSettingStore()\n    .set(id, value)\n    .catch((err) => {\n      useToast().warning(\n        t('toastMessages.errorSaveSetting', {\n          err: getErrorMessage(err) ?? t('g.unknownError'),\n          id\n        })\n      )\n    })\n}\n\nexport class ComfySettingsDialog extends ComfyDialog<HTMLDialogElement> {\n  app: ComfyApp\n\n  constructor(app: ComfyApp) {\n    super()\n    this.app = app\n  }\n\n  dispatchChange<T>(id: string, value: T, oldValue?: T) {\n    this.dispatchEvent(\n      new CustomEvent(id + '.change', {\n        detail: {\n          value,\n          oldValue\n        }\n      })\n    )\n  }\n\n  /**\n   * @deprecated Use `settingStore.settingValues` instead.\n   */\n  get settingsValues() {\n    return useSettingStore().settingValues\n  }\n\n  /**\n   * @deprecated Use `settingStore.settingsById` instead.\n   */\n  get settingsLookup() {\n    return useSettingStore().settingsById\n  }\n\n  /**\n   * @deprecated Use `settingStore.settingsById` instead.\n   */\n  get settingsParamLookup() {\n    return useSettingStore().settingsById\n  }\n\n  /**\n   * @deprecated Use `settingStore.get` instead.\n   */\n  getSettingValue<K extends keyof Settings>(\n    id: K,\n    defaultValue?: Settings[K]\n  ): Settings[K] {\n    if (defaultValue !== undefined) {\n      console.warn(\n        `Parameter defaultValue is deprecated. The default value in settings definition will be used instead.`\n      )\n    }\n    return useSettingStore().get(id)\n  }\n\n  /**\n   * @deprecated Use `settingStore.getDefaultValue` instead.\n   */\n  getSettingDefaultValue<K extends keyof Settings>(\n    id: K\n  ): Settings[K] | undefined {\n    return useSettingStore().getDefaultValue(id)\n  }\n\n  /**\n   * @deprecated Use `settingStore.set` instead.\n   */\n  async setSettingValueAsync<K extends keyof Settings>(\n    id: K,\n    value: Settings[K]\n  ) {\n    await useSettingStore().set(id, value)\n  }\n\n  /**\n   * @deprecated Use `settingStore.set` instead.\n   */\n  setSettingValue<K extends keyof Settings>(id: K, value: Settings[K]) {\n    saveSetting(id, value)\n  }\n\n  /**\n   * @deprecated Deprecated for external callers/extensions. Use\n   * `ComfyExtension.settings` field instead.\n   *\n   * Example:\n   * ```ts\n   * app.registerExtension({\n   *   name: 'My Extension',\n   *   settings: [\n   *     {\n   *       id: 'My.Setting',\n   *       name: 'My Setting',\n   *       type: 'text',\n   *       defaultValue: 'Hello, world!'\n   *     }\n   *   ]\n   * })\n   * ```\n   */\n  addSetting<K extends keyof Settings>(\n    params: SettingParams<Settings[K]> & { id: K }\n  ) {\n    const settingStore = useSettingStore()\n    settingStore.addSetting(params)\n\n    return {\n      get value() {\n        return settingStore.get(params.id)\n      },\n      set value(v) {\n        saveSetting(params.id, v)\n      }\n    }\n  }\n}\n","import { $el } from './utils'\n\ninterface ToggleSwitchItem {\n  text: string\n  value?: string\n  tooltip?: string\n  selected?: boolean\n}\n\ntype ResolvedToggleSwitchItem = ToggleSwitchItem & { value: string }\n\ninterface ToggleSwitchOptions {\n  onChange?: (e: {\n    item: ResolvedToggleSwitchItem\n    prev?: ResolvedToggleSwitchItem\n  }) => void\n}\n\n/**\n * Creates a toggle switch element\n */\nexport function toggleSwitch(\n  name: string,\n  items: (string | ToggleSwitchItem)[],\n  e?: ToggleSwitchOptions\n) {\n  const onChange = e?.onChange\n  const switchItems: ResolvedToggleSwitchItem[] = items.map((item) =>\n    typeof item === 'string'\n      ? { text: item, value: item }\n      : { ...item, value: item.value ?? item.text }\n  )\n  const initialIndex = Math.max(\n    switchItems.findLastIndex((item) => item.selected),\n    0\n  )\n\n  let selectedIndex: number | undefined\n\n  function updateSelected(index: number) {\n    if (selectedIndex != null) {\n      elements[selectedIndex].classList.remove('comfy-toggle-selected')\n    }\n    onChange?.({\n      item: switchItems[index],\n      prev: selectedIndex == null ? undefined : switchItems[selectedIndex]\n    })\n    selectedIndex = index\n    elements[selectedIndex].classList.add('comfy-toggle-selected')\n  }\n\n  const elements = switchItems.map((item, i) =>\n    $el(\n      'label',\n      {\n        textContent: item.text,\n        title: item.tooltip ?? ''\n      },\n      $el('input', {\n        name,\n        type: 'radio',\n        value: item.value,\n        checked: i === initialIndex,\n        onchange: () => {\n          updateSelected(i)\n        }\n      })\n    )\n  )\n\n  const container = $el('div.comfy-toggle-switch', elements)\n  updateSelected(initialIndex)\n\n  return container\n}\n","import { extractWorkflow } from '@/platform/remote/comfyui/jobs/fetchJobs'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { WORKFLOW_ACCEPT_STRING } from '@/platform/workflow/core/types/formats'\nimport type {\n  ExecutedWsMessage,\n  StatusWsMessageStatus\n} from '@/platform/remote/comfyui/execution/types'\nimport type { WorkflowQueueIntent } from '@/platform/telemetry/types'\nimport { useCommandStore } from '@/stores/commandStore'\n\nimport { api } from './api'\nimport type { ComfyApp } from '@/types/comfy'\nimport { ComfyDialog as _ComfyDialog } from './ui/dialog'\nimport { $el as _$el } from './ui/utils'\nimport { ComfySettingsDialog } from './ui/settings'\nimport { toggleSwitch } from './ui/toggleSwitch'\n\nexport const ComfyDialog = _ComfyDialog\nexport const $el = _$el\n\ntype Position2D = {\n  x: number\n  y: number\n}\n\nfunction dragElement(dragEl: HTMLElement): () => void {\n  let posDiffX = 0,\n    posDiffY = 0,\n    posStartX = 0,\n    posStartY = 0,\n    newPosX = 0,\n    newPosY = 0\n  const dragHandle = dragEl.querySelector<HTMLElement>('.drag-handle')\n  if (dragHandle) {\n    // if present, the handle is where you move the DIV from:\n    dragHandle.onmousedown = dragMouseDown\n  } else {\n    // otherwise, move the DIV from anywhere inside the DIV:\n    dragEl.onmousedown = dragMouseDown\n  }\n\n  // When the element resizes (e.g. view queue) ensure it is still in the windows bounds\n  new ResizeObserver(() => {\n    ensureInBounds()\n  }).observe(dragEl)\n\n  function ensureInBounds() {\n    try {\n      newPosX = Math.min(\n        document.body.clientWidth - dragEl.clientWidth,\n        Math.max(0, dragEl.offsetLeft)\n      )\n      newPosY = Math.min(\n        document.body.clientHeight - dragEl.clientHeight,\n        Math.max(0, dragEl.offsetTop)\n      )\n\n      positionElement()\n    } catch {\n      // robust\n    }\n  }\n\n  function positionElement() {\n    if (dragEl.style.display === 'none') return\n\n    const halfWidth = document.body.clientWidth / 2\n    const anchorRight = newPosX + dragEl.clientWidth / 2 > halfWidth\n\n    // set the element's new position:\n    if (anchorRight) {\n      dragEl.style.left = 'unset'\n      dragEl.style.right =\n        document.body.clientWidth - newPosX - dragEl.clientWidth + 'px'\n    } else {\n      dragEl.style.left = newPosX + 'px'\n      dragEl.style.right = 'unset'\n    }\n\n    dragEl.style.top = newPosY + 'px'\n    dragEl.style.bottom = 'unset'\n\n    if (savePos) {\n      try {\n        localStorage.setItem(\n          'Comfy.MenuPosition',\n          JSON.stringify({\n            x: dragEl.offsetLeft,\n            y: dragEl.offsetTop\n          })\n        )\n      } catch {\n        // Persisting the menu position is cosmetic; storage can be unavailable\n        // (private browsing, quota exceeded). Never let it break dragging.\n      }\n    }\n  }\n\n  function restorePos() {\n    // `dragElement` is reached from ComfyUI's constructor, which runs at module\n    // scope via `export const app = new ComfyApp()` in app.ts. A throw here\n    // therefore breaks *importing* that module, not just the menu. Restoring a\n    // remembered position is cosmetic, so degrade quietly instead: localStorage\n    // may be absent or degraded outside a real browser (e.g. Node >= 25 without\n    // `--no-experimental-webstorage`), and the stored value may be corrupt.\n    let pos: Position2D\n    try {\n      const posString = localStorage.getItem('Comfy.MenuPosition')\n      if (!posString) return\n      pos = JSON.parse(posString) as Position2D\n    } catch {\n      return\n    }\n\n    newPosX = pos.x\n    newPosY = pos.y\n    positionElement()\n    ensureInBounds()\n  }\n\n  let savePos = false\n  restorePos()\n  savePos = true\n\n  function dragMouseDown(e: MouseEvent) {\n    e.preventDefault()\n    // get the mouse cursor position at startup:\n    posStartX = e.clientX\n    posStartY = e.clientY\n    document.onmouseup = closeDragElement\n    // call a function whenever the cursor moves:\n    document.onmousemove = elementDrag\n  }\n\n  function elementDrag(e: MouseEvent) {\n    e.preventDefault()\n\n    dragEl.classList.add('comfy-menu-manual-pos')\n\n    // calculate the new cursor position:\n    posDiffX = e.clientX - posStartX\n    posDiffY = e.clientY - posStartY\n    posStartX = e.clientX\n    posStartY = e.clientY\n\n    newPosX = Math.min(\n      document.body.clientWidth - dragEl.clientWidth,\n      Math.max(0, dragEl.offsetLeft + posDiffX)\n    )\n    newPosY = Math.min(\n      document.body.clientHeight - dragEl.clientHeight,\n      Math.max(0, dragEl.offsetTop + posDiffY)\n    )\n\n    positionElement()\n  }\n\n  window.addEventListener('resize', () => {\n    ensureInBounds()\n  })\n\n  function closeDragElement() {\n    // stop moving when mouse button is released:\n    document.onmouseup = null\n    document.onmousemove = null\n  }\n\n  return restorePos\n}\n\nexport interface LegacyMenuHost {\n  resetView(): void\n  restoreOutputs(\n    outputs: Partial<Record<string, ExecutedWsMessage['output']>>\n  ): void\n  trackRunButton(intent: WorkflowQueueIntent): void\n  enterFocusMode(): void\n}\n\nclass ComfyList {\n  private _type: string\n  private _text: string\n  private _reverse: boolean\n  element: HTMLDivElement\n  button?: HTMLButtonElement\n\n  constructor(\n    private readonly app: ComfyApp,\n    private readonly host: LegacyMenuHost,\n    text: string,\n    type?: string,\n    reverse?: boolean\n  ) {\n    this._text = text\n    this._type = type || text.toLowerCase()\n    this._reverse = reverse || false\n    this.element = $el('div.comfy-list') as HTMLDivElement\n    this.element.style.display = 'none'\n\n    console.warn(\n      '[ComfyUI] The legacy queue/history menu is deprecated. ' +\n        'Core functionality in this menu may break at any time. ' +\n        'Issues and feature requests related to the legacy menu will not be addressed. ' +\n        'To switch to the new menu: Settings → search \"Use new menu\" → change from \"Disabled\" to \"Top\".'\n    )\n  }\n\n  get visible() {\n    return this.element.style.display !== 'none'\n  }\n\n  async load() {\n    const items =\n      this._type === 'history'\n        ? { history: await api.getHistory() }\n        : await api.getQueue()\n    this.element.replaceChildren(\n      ...Object.entries(items).flatMap(([section, sectionItems]) => [\n        $el('h4', {\n          textContent: section\n        }),\n        $el(\n          'div.comfy-list-items',\n          (this._reverse ? sectionItems.reverse() : sectionItems).map(\n            (item) => {\n              // Allow items to specify a custom remove action (e.g. for interrupt current prompt)\n              const removeAction =\n                section === 'Running'\n                  ? {\n                      name: 'Cancel',\n                      cb: () => api.interrupt(item.id)\n                    }\n                  : {\n                      name: 'Delete',\n                      cb: () => api.deleteItem(this._type, item.id)\n                    }\n              return $el('div', { textContent: item.priority + ': ' }, [\n                $el('button', {\n                  textContent: 'Load',\n                  onclick: async () => {\n                    const job = await api.getJobDetail(item.id)\n                    if (!job) return\n                    const workflow = await extractWorkflow(job)\n                    await this.app.loadGraphData(workflow, true, false)\n                    if ('outputs' in job && job.outputs) {\n                      this.host.restoreOutputs(job.outputs)\n                    }\n                  }\n                }),\n                $el('button', {\n                  textContent: removeAction.name,\n                  onclick: async () => {\n                    await removeAction.cb()\n                    await this.update()\n                  }\n                })\n              ])\n            }\n          )\n        )\n      ]),\n      $el('div.comfy-list-actions', [\n        $el('button', {\n          textContent: 'Clear ' + this._text,\n          onclick: async () => {\n            await api.clearItems(this._type)\n            await this.load()\n          }\n        }),\n        $el('button', { textContent: 'Refresh', onclick: () => this.load() })\n      ])\n    )\n  }\n\n  async update() {\n    if (this.visible) {\n      await this.load()\n    }\n  }\n\n  async show() {\n    this.element.style.display = 'block'\n    if (this.button) this.button.textContent = 'Close'\n\n    await this.load()\n  }\n\n  hide() {\n    this.element.style.display = 'none'\n    if (this.button) this.button.textContent = 'View ' + this._text\n  }\n\n  toggle() {\n    if (this.visible) {\n      this.hide()\n      return false\n    } else {\n      void this.show()\n      return true\n    }\n  }\n}\n\nexport class ComfyUI {\n  app: ComfyApp\n  private readonly host: LegacyMenuHost\n  dialog: _ComfyDialog\n  settings: ComfySettingsDialog\n  batchCount: number\n  lastQueueSize: number\n  queue: ComfyList\n  history: ComfyList\n  autoQueueMode = ''\n  graphHasChanged = false\n  autoQueueEnabled = false\n  menuContainer = document.createElement('div')\n  queueSize: Element = document.createElement('span')\n  restoreMenuPosition = () => {}\n  loadFile = () => {}\n\n  constructor(app: ComfyApp, host: LegacyMenuHost) {\n    this.app = app\n    this.host = host\n    this.dialog = new ComfyDialog()\n    this.settings = new ComfySettingsDialog(app)\n\n    this.batchCount = 1\n    this.lastQueueSize = 0\n    this.queue = new ComfyList(app, host, 'Queue')\n    this.history = new ComfyList(app, host, 'History', 'history', true)\n\n    api.addEventListener('status', () => {\n      void this.queue.update()\n      void this.history.update()\n    })\n\n    this.setup(document.body)\n  }\n\n  setup(containerElement: HTMLElement) {\n    const fileInput = $el('input', {\n      id: 'comfy-file-input',\n      type: 'file',\n      accept: WORKFLOW_ACCEPT_STRING,\n      style: { display: 'none' },\n      parent: document.body,\n      onchange: async () => {\n        const file = fileInput.files?.[0]\n        if (file) {\n          try {\n            await this.app.handleFile(file, 'file_button')\n          } catch (error) {\n            console.error('Failed to load file:', error)\n            this.app.showErrorOnFileLoad(file)\n          } finally {\n            fileInput.value = ''\n          }\n        }\n      }\n    })\n\n    this.loadFile = () => fileInput.click()\n\n    const autoQueueModeEl = toggleSwitch(\n      'autoQueueMode',\n      [\n        {\n          text: 'instant',\n          tooltip: 'A new prompt will be queued as soon as the queue reaches 0'\n        },\n        {\n          text: 'change',\n          tooltip:\n            'A new prompt will be queued when the queue is at 0 and the graph is/has changed'\n        }\n      ],\n      {\n        onChange: (value) => {\n          this.autoQueueMode = value.item.value\n        }\n      }\n    )\n    autoQueueModeEl.style.display = 'none'\n\n    api.addEventListener('autoQueueGraphChanged', () => {\n      if (this.autoQueueMode === 'change' && this.autoQueueEnabled) {\n        if (this.lastQueueSize === 0) {\n          this.graphHasChanged = false\n          void this.app.queuePrompt(0, this.batchCount, {\n            intent: { trigger_source: 'auto_queue' }\n          })\n        } else {\n          this.graphHasChanged = true\n        }\n      }\n    })\n\n    this.menuContainer = $el(\n      'div.comfy-menu.no-drag',\n      { parent: containerElement },\n      [\n        $el(\n          'div.drag-handle.comfy-menu-header',\n          {\n            style: {\n              overflow: 'hidden',\n              position: 'relative',\n              width: '100%',\n              cursor: 'default'\n            }\n          },\n          [\n            $el('span.drag-handle'),\n            $el('span.comfy-menu-queue-size', {\n              $: (q) => (this.queueSize = q)\n            }),\n            $el('div.comfy-menu-actions', [\n              $el('button.comfy-settings-btn', {\n                textContent: '⚙️',\n                onclick: () => {\n                  useSettingsDialog().show()\n                }\n              }),\n              $el('button.comfy-close-menu-btn', {\n                textContent: '\\u00d7',\n                onclick: () => {\n                  this.host.enterFocusMode()\n                }\n              })\n            ])\n          ]\n        ),\n        $el('button.comfy-queue-btn', {\n          id: 'queue-button',\n          textContent: 'Queue Prompt',\n          onclick: () => {\n            const workflowQueueIntent = {\n              trigger_source: 'legacy_ui'\n            } as const\n            this.host.trackRunButton(workflowQueueIntent)\n            useTelemetry()?.trackWorkflowExecution()\n            void this.app.queuePrompt(0, this.batchCount, {\n              intent: workflowQueueIntent\n            })\n          }\n        }),\n        $el('div', {}, [\n          $el('label', { innerHTML: 'Extra options' }, [\n            $el('input', {\n              type: 'checkbox',\n              onchange: (event: Event) => {\n                const input = event.currentTarget\n                const extraOptions = document.getElementById('extraOptions')\n                if (!(input instanceof HTMLInputElement) || !extraOptions)\n                  return\n                extraOptions.style.display = input.checked ? 'block' : 'none'\n                this.batchCount = input.checked\n                  ? Number.parseInt(\n                      (\n                        document.getElementById(\n                          'batchCountInputRange'\n                        ) as HTMLInputElement\n                      ).value\n                    )\n                  : 1\n                ;(\n                  document.getElementById(\n                    'autoQueueCheckbox'\n                  ) as HTMLInputElement\n                ).checked = false\n                this.autoQueueEnabled = false\n              }\n            })\n          ])\n        ]),\n        $el(\n          'div',\n          { id: 'extraOptions', style: { width: '100%', display: 'none' } },\n          [\n            $el('div', [\n              $el('label', { innerHTML: 'Batch count' }),\n              $el('input', {\n                id: 'batchCountInputNumber',\n                type: 'number',\n                value: this.batchCount,\n                min: '1',\n                style: { width: '35%', marginLeft: '0.4em' },\n                oninput: (event: Event) => {\n                  const input = event.currentTarget\n                  if (!(input instanceof HTMLInputElement)) return\n                  this.batchCount = Number(input.value)\n                  /* Even though an <input> element with a type of range logically represents a number (since\n              it's used for numeric input), the value it holds is still treated as a string in HTML and\n              JavaScript. This behavior is consistent across all <input> elements regardless of their type\n              (like text, number, or range), where the .value property is always a string. */\n                  ;(\n                    document.getElementById(\n                      'batchCountInputRange'\n                    ) as HTMLInputElement\n                  ).value = this.batchCount.toString()\n                }\n              }),\n              $el('input', {\n                id: 'batchCountInputRange',\n                type: 'range',\n                min: '1',\n                max: '100',\n                value: this.batchCount,\n                oninput: (event: Event) => {\n                  const input = event.currentTarget\n                  if (!(input instanceof HTMLInputElement)) return\n                  this.batchCount = Number(input.value)\n                  // Note\n                  ;(\n                    document.getElementById(\n                      'batchCountInputNumber'\n                    ) as HTMLInputElement\n                  ).value = input.value\n                }\n              })\n            ]),\n            $el('div', [\n              $el('label', {\n                for: 'autoQueueCheckbox',\n                innerHTML: 'Auto Queue'\n              }),\n              $el('input', {\n                id: 'autoQueueCheckbox',\n                type: 'checkbox',\n                checked: false,\n                title: 'Automatically queue prompt when the queue size hits 0',\n                onchange: (event: Event) => {\n                  const input = event.currentTarget\n                  if (!(input instanceof HTMLInputElement)) return\n                  this.autoQueueEnabled = input.checked\n                  autoQueueModeEl.style.display = this.autoQueueEnabled\n                    ? ''\n                    : 'none'\n                }\n              }),\n              autoQueueModeEl\n            ])\n          ]\n        ),\n        $el('div.comfy-menu-btns', [\n          $el('button', {\n            id: 'queue-front-button',\n            textContent: 'Queue Front',\n            onclick: () => {\n              const workflowQueueIntent = {\n                trigger_source: 'legacy_ui'\n              } as const\n              this.host.trackRunButton(workflowQueueIntent)\n              useTelemetry()?.trackWorkflowExecution()\n              void this.app.queuePrompt(-1, this.batchCount, {\n                intent: workflowQueueIntent\n              })\n            }\n          }),\n          $el('button', {\n            $: (b) => (this.queue.button = b as HTMLButtonElement),\n            id: 'comfy-view-queue-button',\n            textContent: 'View Queue',\n            onclick: () => {\n              this.history.hide()\n              this.queue.toggle()\n            }\n          }),\n          $el('button', {\n            $: (b) => (this.history.button = b as HTMLButtonElement),\n            id: 'comfy-view-history-button',\n            textContent: 'View History',\n            onclick: () => {\n              this.queue.hide()\n              this.history.toggle()\n            }\n          })\n        ]),\n        this.queue.element,\n        this.history.element,\n        $el('button', {\n          id: 'comfy-save-button',\n          textContent: 'Save',\n          onclick: () => {\n            void useCommandStore().execute('Comfy.ExportWorkflow')\n          }\n        }),\n        $el('button', {\n          id: 'comfy-dev-save-api-button',\n          textContent: 'Save (API Format)',\n          style: { width: '100%', display: 'none' },\n          onclick: () => {\n            void useCommandStore().execute('Comfy.ExportWorkflowAPI')\n          }\n        }),\n        $el('button', {\n          id: 'comfy-load-button',\n          textContent: 'Load',\n          onclick: () => fileInput.click()\n        }),\n        $el('button', {\n          id: 'comfy-refresh-button',\n          textContent: 'Refresh',\n          onclick: () => {\n            void this.app.refreshComboInNodes().catch(() => {})\n          }\n        }),\n        $el('button', {\n          id: 'comfy-clipspace-button',\n          textContent: 'Clipspace',\n          onclick: () => this.app.openClipspace()\n        }),\n        $el('button', {\n          id: 'comfy-clear-button',\n          textContent: 'Clear',\n          onclick: () => {\n            if (\n              !useSettingStore().get('Comfy.ConfirmClear') ||\n              confirm('Clear workflow?')\n            ) {\n              this.app.clean()\n              this.host.resetView()\n              api.dispatchCustomEvent('graphCleared')\n            }\n          }\n        }),\n        $el('button', {\n          id: 'comfy-load-default-button',\n          textContent: 'Load Default',\n          onclick: async () => {\n            if (\n              !useSettingStore().get('Comfy.ConfirmClear') ||\n              confirm('Load default workflow?')\n            ) {\n              this.host.resetView()\n              await this.app.loadGraphData()\n            }\n          }\n        }),\n        $el('button', {\n          id: 'comfy-reset-view-button',\n          textContent: 'Reset View',\n          onclick: async () => {\n            this.host.resetView()\n          }\n        })\n      ]\n    ) as HTMLDivElement\n    // Hide by default on construction so it does not interfere with other views.\n    this.menuContainer.style.display = 'none'\n\n    this.restoreMenuPosition = dragElement(this.menuContainer)\n\n    this.queueSize.textContent = 'Queue size: X'\n  }\n\n  setStatus(status: StatusWsMessageStatus | null) {\n    const queueRemaining = status?.exec_info?.queue_remaining\n    if (queueRemaining == null) return\n\n    this.queueSize.textContent = 'Queue size: ' + queueRemaining\n    if (\n      this.lastQueueSize != 0 &&\n      queueRemaining == 0 &&\n      this.autoQueueEnabled &&\n      (this.autoQueueMode === 'instant' || this.graphHasChanged) &&\n      !this.app.lastExecutionError\n    ) {\n      void this.app.queuePrompt(0, this.batchCount, {\n        intent: { trigger_source: 'auto_queue' }\n      })\n      this.graphHasChanged = false\n      this.lastQueueSize = queueRemaining + this.batchCount\n    } else {\n      this.lastQueueSize = queueRemaining\n    }\n  }\n}\n","import { $el } from '../utils'\nimport { prop } from '../../utils'\nimport type { ComfyButton } from './button'\n\nexport class ComfyButtonGroup {\n  element = $el('div.comfyui-button-group')\n  buttons: (HTMLElement | ComfyButton)[]\n\n  constructor(...buttons: (HTMLElement | ComfyButton)[]) {\n    this.buttons = prop(this, 'buttons', buttons, () => this.update())\n  }\n\n  insert(button: ComfyButton, index: number) {\n    this.buttons.splice(index, 0, button)\n    this.update()\n  }\n\n  append(button: ComfyButton) {\n    this.buttons.push(button)\n    this.update()\n  }\n\n  remove(indexOrButton: ComfyButton | number) {\n    if (typeof indexOrButton !== 'number') {\n      indexOrButton = this.buttons.indexOf(indexOrButton)\n    }\n    if (indexOrButton > -1) {\n      const r = this.buttons.splice(indexOrButton, 1)\n      this.update()\n      return r\n    }\n  }\n\n  update() {\n    this.element.replaceChildren(\n      ...this.buttons.map((button) =>\n        button instanceof HTMLElement ? button : button.element\n      )\n    )\n  }\n}\n","import type { Settings } from '@/platform/settings/types'\nimport type { ComfyApp } from '@/types/comfy'\n\nimport type { ComfyComponent } from '.'\nimport { prop } from '../../utils'\nimport { $el, applyClasses, toggleElement } from '../utils'\nimport type { ClassList } from '../utils'\nimport type { ComfyPopup } from './popup'\n\ntype ComfyButtonProps = {\n  icon?: string\n  overIcon?: string\n  iconSize?: number\n  content?: string | HTMLElement\n  tooltip?: string\n  enabled?: boolean\n  action?: (e: Event, btn: ComfyButton) => void\n  classList?: ClassList\n  visibilitySetting?: { id: keyof Settings; showValue: boolean }\n  app?: ComfyApp\n}\n\nexport class ComfyButton implements ComfyComponent {\n  private _over = 0\n  private _popupOpen = false\n  isOver = false\n  iconElement = $el('i.mdi')\n  contentElement = $el('span')\n  popup?: ComfyPopup\n  element: HTMLElement\n  overIcon?: string\n  iconSize?: number\n  content?: string | HTMLElement\n  icon?: string\n  tooltip?: string\n  classList: ClassList\n  hidden: boolean\n  enabled: boolean\n  action?: (e: Event, btn: ComfyButton) => void\n\n  constructor({\n    icon,\n    overIcon,\n    iconSize,\n    content,\n    tooltip,\n    action,\n    classList = 'comfyui-button',\n    visibilitySetting,\n    app,\n    enabled = true\n  }: ComfyButtonProps) {\n    this.element = $el(\n      'button',\n      {\n        onmouseenter: () => {\n          this.isOver = true\n          if (this.overIcon) {\n            this.updateIcon()\n          }\n        },\n        onmouseleave: () => {\n          this.isOver = false\n          if (this.overIcon) {\n            this.updateIcon()\n          }\n        }\n      },\n      [this.iconElement, this.contentElement]\n    )\n\n    this.icon = prop(\n      this,\n      'icon',\n      icon,\n      toggleElement(this.iconElement, { onShow: this.updateIcon })\n    )\n    this.overIcon = prop(this, 'overIcon', overIcon, () => {\n      if (this.isOver) {\n        this.updateIcon()\n      }\n    })\n    this.iconSize = prop(this, 'iconSize', iconSize, this.updateIcon)\n    this.content = prop(\n      this,\n      'content',\n      content,\n      toggleElement<ComfyButtonProps['content']>(this.contentElement, {\n        onShow: (el, v) => {\n          if (typeof v === 'string') {\n            el.textContent = v\n          } else {\n            el.replaceChildren(v)\n          }\n        }\n      })\n    )\n\n    this.tooltip = prop(this, 'tooltip', tooltip, (v) => {\n      if (v) {\n        this.element.title = v\n      } else {\n        this.element.removeAttribute('title')\n      }\n    })\n    if (tooltip !== undefined) {\n      this.element.setAttribute('aria-label', tooltip)\n    }\n    this.classList = prop(this, 'classList', classList, this.updateClasses)\n    this.hidden = prop(this, 'hidden', false, this.updateClasses)\n    this.enabled = prop(this, 'enabled', enabled, () => {\n      this.updateClasses()\n      ;(this.element as HTMLButtonElement).disabled = !this.enabled\n    })\n    this.action = prop(this, 'action', action)\n    this.element.addEventListener('click', (e) => {\n      if (this.popup) {\n        // we are either a touch device or triggered by click not hover\n        if (!this._over) {\n          this.popup.toggle()\n        }\n      }\n      this.action?.(e, this)\n    })\n\n    if (visibilitySetting?.id && app) {\n      const settingUpdated = () => {\n        this.hidden =\n          app.ui.settings.getSettingValue(visibilitySetting.id) !==\n          visibilitySetting.showValue\n      }\n      app.ui.settings.addEventListener(\n        visibilitySetting.id + '.change',\n        settingUpdated\n      )\n      settingUpdated()\n    }\n  }\n\n  updateIcon = () =>\n    (this.iconElement.className = `mdi mdi-${(this.isOver && this.overIcon) || this.icon}${this.iconSize ? ' mdi-' + this.iconSize + 'px' : ''}`)\n  updateClasses = () => {\n    const internalClasses = []\n    if (this.hidden) {\n      internalClasses.push('hidden')\n    }\n    if (!this.enabled) {\n      internalClasses.push('disabled')\n    }\n    if (this.popup) {\n      if (this._popupOpen) {\n        internalClasses.push('popup-open')\n      } else {\n        internalClasses.push('popup-closed')\n      }\n    }\n    applyClasses(this.element, this.classList, ...internalClasses)\n  }\n\n  withPopup(popup: ComfyPopup, mode: 'click' | 'hover' = 'click') {\n    this.popup = popup\n\n    if (mode === 'hover') {\n      for (const el of [this.element, popup.element]) {\n        el.addEventListener('mouseenter', () => {\n          popup.open = !!++this._over\n        })\n        el.addEventListener('mouseleave', () => {\n          popup.open = !!--this._over\n        })\n      }\n    }\n\n    popup.addEventListener('change', () => {\n      this._popupOpen = popup.open\n      this.updateClasses()\n    })\n\n    return this\n  }\n}\n","import { prop } from '../../utils'\nimport { $el, applyClasses } from '../utils'\nimport type { ClassList } from '../utils'\n\nexport class ComfyPopup extends EventTarget {\n  element = $el('div.comfyui-popup')\n  open: boolean\n  children: HTMLElement[]\n  target: HTMLElement\n  ignoreTarget: boolean\n  container: HTMLElement\n  position: string\n  closeOnEscape: boolean\n  horizontal: string\n  classList: ClassList\n\n  constructor(\n    {\n      target,\n      container = document.body,\n      classList = '',\n      ignoreTarget = true,\n      closeOnEscape = true,\n      position = 'absolute',\n      horizontal = 'left'\n    }: {\n      target: HTMLElement\n      container?: HTMLElement\n      classList?: ClassList\n      ignoreTarget?: boolean\n      closeOnEscape?: boolean\n      position?: 'absolute' | 'relative'\n      horizontal?: 'left' | 'right'\n    },\n    ...children: HTMLElement[]\n  ) {\n    super()\n    this.target = target\n    this.ignoreTarget = ignoreTarget\n    this.container = container\n    this.position = position\n    this.closeOnEscape = closeOnEscape\n    this.horizontal = horizontal\n\n    container.append(this.element)\n\n    this.children = prop(this, 'children', children, () => {\n      this.element.replaceChildren(...this.children)\n      this.update()\n    })\n    this.classList = prop(this, 'classList', classList, () =>\n      applyClasses(this.element, this.classList, 'comfyui-popup', horizontal)\n    )\n    this.open = prop(this, 'open', false, (v, o) => {\n      if (v === o) return\n      if (v) {\n        this._show()\n      } else {\n        this._hide()\n      }\n    })\n  }\n\n  toggle() {\n    this.open = !this.open\n  }\n\n  private _hide() {\n    this.element.classList.remove('open')\n    window.removeEventListener('resize', this.update)\n    window.removeEventListener('click', this._clickHandler, { capture: true })\n    window.removeEventListener('keydown', this._escHandler, { capture: true })\n\n    this.dispatchEvent(new CustomEvent('close'))\n    this.dispatchEvent(new CustomEvent('change'))\n  }\n\n  private _show() {\n    this.element.classList.add('open')\n    this.update()\n\n    window.addEventListener('resize', this.update)\n    window.addEventListener('click', this._clickHandler, { capture: true })\n    if (this.closeOnEscape) {\n      window.addEventListener('keydown', this._escHandler, { capture: true })\n    }\n\n    this.dispatchEvent(new CustomEvent('open'))\n    this.dispatchEvent(new CustomEvent('change'))\n  }\n\n  private _escHandler = (e: KeyboardEvent) => {\n    if (e.key === 'Escape') {\n      this.open = false\n      e.preventDefault()\n      e.stopImmediatePropagation()\n    }\n  }\n\n  private _clickHandler = (e: MouseEvent) => {\n    const target = e.target\n    if (\n      target instanceof Node &&\n      !this.element.contains(target) &&\n      this.ignoreTarget &&\n      !this.target.contains(target)\n    ) {\n      this.open = false\n    }\n  }\n\n  update = () => {\n    const rect = this.target.getBoundingClientRect()\n    this.element.style.setProperty('--bottom', 'unset')\n    if (this.position === 'absolute') {\n      if (this.horizontal === 'left') {\n        this.element.style.setProperty('--left', rect.left + 'px')\n      } else {\n        this.element.style.setProperty(\n          '--left',\n          rect.right - this.element.clientWidth + 'px'\n        )\n      }\n      this.element.style.setProperty('--top', rect.bottom + 'px')\n      this.element.style.setProperty('--limit', rect.bottom + 'px')\n    } else {\n      this.element.style.setProperty('--left', 0 + 'px')\n      this.element.style.setProperty('--top', rect.height + 'px')\n      this.element.style.setProperty('--limit', rect.height + 'px')\n    }\n\n    const thisRect = this.element.getBoundingClientRect()\n    if (thisRect.height < 30) {\n      // Move up instead\n      this.element.style.setProperty('--top', 'unset')\n      this.element.style.setProperty('--bottom', rect.height + 5 + 'px')\n      this.element.style.setProperty('--limit', rect.height + 5 + 'px')\n    }\n  }\n}\n","import { $el } from '../utils'\nimport { prop } from '../../utils'\nimport { ComfyButton } from './button'\nimport { ComfyPopup } from './popup'\n\nexport class ComfySplitButton {\n  arrow: ComfyButton\n  element: HTMLElement\n  popup: ComfyPopup\n  items: Array<HTMLElement | ComfyButton>\n\n  constructor(\n    {\n      primary,\n      mode,\n      horizontal = 'left',\n      position = 'relative'\n    }: {\n      primary: ComfyButton\n      mode?: 'hover' | 'click'\n      horizontal?: 'left' | 'right'\n      position?: 'relative' | 'absolute'\n    },\n    ...items: Array<HTMLElement | ComfyButton>\n  ) {\n    this.arrow = new ComfyButton({\n      icon: 'chevron-down'\n    })\n    this.element = $el(\n      'div.comfyui-split-button' + (mode === 'hover' ? '.hover' : ''),\n      [\n        $el(\n          'div.comfyui-split-primary',\n          {\n            ariaLabel: 'Queue current workflow'\n          },\n          primary.element\n        ),\n        $el(\n          'div.comfyui-split-arrow',\n          {\n            ariaLabel: 'Open extra opens',\n            ariaHasPopup: 'true'\n          },\n          this.arrow.element\n        )\n      ]\n    )\n    this.popup = new ComfyPopup({\n      target: this.element,\n      container: position === 'relative' ? this.element : document.body,\n      classList:\n        'comfyui-split-button-popup' + (mode === 'hover' ? ' hover' : ''),\n      closeOnEscape: mode === 'click',\n      position,\n      horizontal\n    })\n\n    this.arrow.withPopup(this.popup, mode)\n\n    this.items = prop(this, 'items', items, () => this.update())\n  }\n\n  update() {\n    this.popup.element.replaceChildren(\n      ...this.items.map((b) => ('element' in b ? b.element : b))\n    )\n  }\n}\n","import { $el } from '../utils'\nimport { ComfyDialog } from '../dialog'\n\ntype DialogAction<T> = string | { value?: T; text: string }\n\nexport class ComfyAsyncDialog<\n  T = string | null\n> extends ComfyDialog<HTMLDialogElement> {\n  private _resolve: (value: T | null) => void = () => {}\n\n  constructor(actions?: Array<DialogAction<T>>) {\n    super(\n      'dialog.comfy-dialog.comfyui-dialog',\n      actions?.map((opt) => {\n        const action = typeof opt === 'string' ? { text: opt } : opt\n        return $el('button.comfyui-button', {\n          type: 'button',\n          textContent: action.text,\n          onclick: () => this.close((action.value ?? action.text) as T)\n        }) as HTMLButtonElement\n      })\n    )\n  }\n\n  override show(html: string | HTMLElement | HTMLElement[]): Promise<T | null> {\n    this.element.addEventListener('close', () => {\n      this.close()\n    })\n\n    super.show(html)\n\n    return new Promise((resolve) => {\n      this._resolve = resolve\n    })\n  }\n\n  showModal(html: string | HTMLElement | HTMLElement[]): Promise<T | null> {\n    this.element.addEventListener('close', () => {\n      this.close()\n    })\n\n    super.show(html)\n    this.element.showModal()\n\n    return new Promise((resolve) => {\n      this._resolve = resolve\n    })\n  }\n\n  override close(result: T | null = null) {\n    this._resolve(result)\n    this.element.close()\n    super.close()\n  }\n\n  static async prompt<U = string>({\n    title,\n    message,\n    actions\n  }: {\n    title: string | null\n    message: string\n    actions: Array<DialogAction<U>>\n  }): Promise<U | null> {\n    const dialog = new ComfyAsyncDialog<U>(actions)\n    const content = [$el('span', message)]\n    if (title) {\n      content.unshift($el('h3', title))\n    }\n    const res = await dialog.showModal(content)\n    dialog.element.remove()\n    return res\n  }\n}\n","/*\n  Original implementation:\n    https://github.com/TahaSh/drag-to-reorder\n    MIT License\n\n    Copyright (c) 2023 Taha Shashtari\n\n    Permission is hereby granted, free of charge, to any person obtaining a copy\n    of this software and associated documentation files (the \"Software\"), to deal\n    in the Software without restriction, including without limitation the rights\n    to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n    copies of the Software, and to permit persons to whom the Software is\n    furnished to do so, subject to the following conditions:\n\n    The above copyright notice and this permission notice shall be included in all\n    copies or substantial portions of the Software.\n\n    THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n    IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n    FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n    AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n    LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n    OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n    SOFTWARE.\n*/\nconst styleElement = document.createElement('style')\nstyleElement.textContent = `\n        .draggable-item {\n            position: relative;\n            will-change: transform;\n            user-select: none;\n        }\n        .draggable-item.is-idle {\n            transition: 0.25s ease transform;\n        }\n        .draggable-item.is-draggable {\n            z-index: 10;\n        }\n    `\ndocument.head.append(styleElement)\n\nexport class DraggableList extends EventTarget {\n  listContainer: HTMLElement\n  draggableItem: HTMLElement | null = null\n  pointerStartX = 0\n  pointerStartY = 0\n  scrollYMax = 0\n  itemsGap = 0\n  items: HTMLElement[] = []\n  itemSelector: string\n  handleClass = 'drag-handle'\n  off: Array<() => void> = []\n  offDrag: Array<() => void> = []\n\n  constructor(element: HTMLElement, itemSelector: string) {\n    super()\n    this.listContainer = element\n    this.itemSelector = itemSelector\n\n    this.off.push(this.on(this.listContainer, 'mousedown', this.dragStart))\n    this.off.push(this.on(this.listContainer, 'touchstart', this.dragStart))\n    this.off.push(this.on(document, 'mouseup', this.dragEnd))\n    this.off.push(this.on(document, 'touchend', this.dragEnd))\n    this.off.push(this.on(document, 'pointercancel', this.dragEnd))\n  }\n\n  getAllItems() {\n    if (!this.items.length) {\n      this.items = Array.from(\n        this.listContainer.querySelectorAll(this.itemSelector)\n      )\n      this.items.forEach((element) => {\n        element.classList.add('is-idle')\n      })\n    }\n    return this.items\n  }\n\n  getIdleItems() {\n    return this.getAllItems().filter((item) =>\n      item.classList.contains('is-idle')\n    )\n  }\n\n  isItemAbove(item: HTMLElement) {\n    return item.hasAttribute('data-is-above')\n  }\n\n  isItemToggled(item: HTMLElement) {\n    return item.hasAttribute('data-is-toggled')\n  }\n\n  on(\n    source: EventTarget,\n    event: string,\n    listener: (event: Event) => void,\n    options?: AddEventListenerOptions | boolean\n  ) {\n    const boundListener = listener.bind(this)\n    source.addEventListener(event, boundListener, options)\n    return () => source.removeEventListener(event, boundListener)\n  }\n\n  dragStart(e: Event) {\n    if (e instanceof MouseEvent && e.button > 0) return\n\n    if (\n      e.target instanceof Element &&\n      e.target.classList.contains(this.handleClass)\n    ) {\n      const item = e.target.closest(this.itemSelector)\n      this.draggableItem = item instanceof HTMLElement ? item : null\n    }\n\n    if (!this.draggableItem) return\n\n    const pointer = this.getPointerPosition(e)\n    if (!pointer) return\n    this.pointerStartX = pointer.x\n    this.pointerStartY = pointer.y\n    this.scrollYMax =\n      this.listContainer.scrollHeight - this.listContainer.clientHeight\n\n    this.setItemsGap()\n    this.initDraggableItem()\n    this.initItemsState()\n\n    this.offDrag.push(this.on(document, 'mousemove', this.drag))\n    this.offDrag.push(\n      this.on(document, 'touchmove', this.drag, { passive: false })\n    )\n\n    this.dispatchEvent(\n      new CustomEvent('dragstart', {\n        detail: {\n          element: this.draggableItem,\n          position: this.getAllItems().indexOf(this.draggableItem)\n        }\n      })\n    )\n  }\n\n  setItemsGap() {\n    if (this.getIdleItems().length <= 1) {\n      this.itemsGap = 0\n      return\n    }\n\n    const item1 = this.getIdleItems()[0]\n    const item2 = this.getIdleItems()[1]\n\n    const item1Rect = item1.getBoundingClientRect()\n    const item2Rect = item2.getBoundingClientRect()\n\n    this.itemsGap = Math.abs(item1Rect.bottom - item2Rect.top)\n  }\n\n  initItemsState() {\n    const draggableItem = this.draggableItem\n    if (!draggableItem) return\n    this.getIdleItems().forEach((item, i) => {\n      if (this.getAllItems().indexOf(draggableItem) > i) {\n        item.dataset.isAbove = ''\n      }\n    })\n  }\n\n  initDraggableItem() {\n    const draggableItem = this.draggableItem\n    if (!draggableItem) return\n    draggableItem.classList.remove('is-idle')\n    draggableItem.classList.add('is-draggable')\n  }\n\n  drag(e: Event) {\n    if (!this.draggableItem) return\n\n    e.preventDefault()\n\n    const pointer = this.getPointerPosition(e)\n    if (!pointer) return\n    const clientX = pointer.x\n    const clientY = pointer.y\n\n    const listRect = this.listContainer.getBoundingClientRect()\n\n    if (clientY > listRect.bottom) {\n      if (this.listContainer.scrollTop < this.scrollYMax) {\n        this.listContainer.scrollBy(0, 10)\n        this.pointerStartY -= 10\n      }\n    } else if (clientY < listRect.top && this.listContainer.scrollTop > 0) {\n      this.pointerStartY += 10\n      this.listContainer.scrollBy(0, -10)\n    }\n\n    const pointerOffsetX = clientX - this.pointerStartX\n    const pointerOffsetY = clientY - this.pointerStartY\n\n    this.updateIdleItemsStateAndPosition()\n    this.draggableItem.style.transform = `translate(${pointerOffsetX}px, ${pointerOffsetY}px)`\n  }\n\n  updateIdleItemsStateAndPosition() {\n    const draggableItem = this.draggableItem\n    if (!draggableItem) return\n    const draggableItemRect = draggableItem.getBoundingClientRect()\n    const draggableItemY = draggableItemRect.top + draggableItemRect.height / 2\n\n    // Update state\n    this.getIdleItems().forEach((item) => {\n      const itemRect = item.getBoundingClientRect()\n      const itemY = itemRect.top + itemRect.height / 2\n      if (this.isItemAbove(item)) {\n        if (draggableItemY <= itemY) {\n          item.dataset.isToggled = ''\n        } else {\n          delete item.dataset.isToggled\n        }\n      } else {\n        if (draggableItemY >= itemY) {\n          item.dataset.isToggled = ''\n        } else {\n          delete item.dataset.isToggled\n        }\n      }\n    })\n\n    // Update position\n    this.getIdleItems().forEach((item) => {\n      if (this.isItemToggled(item)) {\n        const direction = this.isItemAbove(item) ? 1 : -1\n        item.style.transform = `translateY(${direction * (draggableItemRect.height + this.itemsGap)}px)`\n      } else {\n        item.style.transform = ''\n      }\n    })\n  }\n\n  dragEnd() {\n    if (!this.draggableItem) return\n\n    this.applyNewItemsOrder()\n    this.cleanup()\n  }\n\n  getReorderedItems(draggableItem: HTMLElement): {\n    items: HTMLElement[]\n    oldPosition: number\n  } {\n    const allItems = this.getAllItems()\n    const reorderedItems: Array<HTMLElement | undefined> = []\n\n    let oldPosition = -1\n    allItems.forEach((item, index) => {\n      if (item === draggableItem) {\n        oldPosition = index\n        return\n      }\n      if (!this.isItemToggled(item)) {\n        reorderedItems[index] = item\n        return\n      }\n      const newIndex = this.isItemAbove(item) ? index + 1 : index - 1\n      reorderedItems[newIndex] = item\n    })\n\n    const items = Array.from(\n      { length: allItems.length },\n      (_, index) => reorderedItems[index] ?? draggableItem\n    )\n    return { items, oldPosition }\n  }\n\n  applyNewItemsOrder() {\n    const draggableItem = this.draggableItem\n    if (!draggableItem) return\n    const { items, oldPosition } = this.getReorderedItems(draggableItem)\n\n    items.forEach((item) => this.listContainer.appendChild(item))\n    this.items = items\n\n    this.dispatchEvent(\n      new CustomEvent('dragend', {\n        detail: {\n          element: draggableItem,\n          oldPosition,\n          newPosition: items.indexOf(draggableItem)\n        }\n      })\n    )\n  }\n\n  cleanup() {\n    this.itemsGap = 0\n    this.items = []\n    this.unsetDraggableItem()\n    this.unsetItemState()\n\n    this.offDrag.forEach((f) => f())\n    this.offDrag = []\n  }\n\n  unsetDraggableItem() {\n    if (!this.draggableItem) return\n    this.draggableItem.removeAttribute('style')\n    this.draggableItem.classList.remove('is-draggable')\n    this.draggableItem = null\n  }\n\n  unsetItemState() {\n    this.getIdleItems().forEach((item: HTMLElement) => {\n      delete item.dataset.isAbove\n      delete item.dataset.isToggled\n      item.style.transform = ''\n\n      // Defer re-adding is-idle (which enables CSS transitions) until after\n      // the browser paints items in their final positions. Without this,\n      // the transition animates the stale drag transform.\n      item.classList.remove('is-idle')\n      requestAnimationFrame(() => {\n        item.classList.add('is-idle')\n      })\n    })\n  }\n\n  dispose() {\n    this.off.forEach((f) => f())\n  }\n\n  private getPointerPosition(event: Event) {\n    if (event instanceof MouseEvent) {\n      return { x: event.clientX, y: event.clientY }\n    }\n    if (event instanceof TouchEvent) {\n      const touch = event.touches[0]\n      return { x: touch.clientX, y: touch.clientY }\n    }\n  }\n}\n","import type { ComfyApp } from '@/types/comfy'\n\nimport { $el } from '../utils'\nimport { ComfyButtonGroup } from '../components/buttonGroup'\nimport './menu.css'\n\n// Export to make sure following components are shimmed and exported by vite\nexport { ComfyButton } from '../components/button'\nexport { ComfySplitButton } from '../components/splitButton'\nexport { ComfyPopup } from '../components/popup'\nexport { ComfyAsyncDialog } from '@/scripts/ui/components/asyncDialog'\nexport { DraggableList } from '@/scripts/ui/draggableList'\nexport { applyTextReplacements, addStylesheet } from '@/scripts/utils'\n\nexport class ComfyAppMenu {\n  app: ComfyApp\n  actionsGroup: ComfyButtonGroup\n  settingsGroup: ComfyButtonGroup\n  viewGroup: ComfyButtonGroup\n  element: HTMLElement\n\n  constructor(app: ComfyApp) {\n    this.app = app\n\n    // Keep the group as there are custom scripts attaching extra\n    // elements to it.\n    this.actionsGroup = new ComfyButtonGroup()\n    this.settingsGroup = new ComfyButtonGroup()\n    this.viewGroup = new ComfyButtonGroup()\n\n    this.element = $el('div.flex.gap-2.mx-2', [\n      this.actionsGroup.element,\n      this.settingsGroup.element,\n      this.viewGroup.element\n    ])\n  }\n}\n","import type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport { createBounds } from '@/lib/litegraph/src/measure'\nimport type { Bounds, Point } from '@/renderer/core/layout/types'\n\nexport const RENDER_SCALE_FACTOR = 1.2\n\nexport const MIN_NODE_WIDTH = 225\n\nconst anchorCache = new WeakMap<LGraph, Point>()\n\n/**\n * Returns a render anchor for a graph.\n *\n * @remarks\n * The anchor is computed once per graph instance and cached for that graph's\n * lifetime. This is intended for one-shot normalization passes.\n */\nexport function getGraphRenderAnchor(graph: LGraph): Point {\n  const cached = anchorCache.get(graph)\n  if (cached) return cached\n\n  const bounds = graph.nodes.length ? createBounds(graph.nodes) : undefined\n  const anchor = bounds ? { x: bounds[0], y: bounds[1] } : { x: 0, y: 0 }\n  anchorCache.set(graph, anchor)\n  return anchor\n}\n\nexport function unprojectPoint(\n  point: Point,\n  anchor: Point,\n  scale: number\n): Point {\n  if (scale === 1) return point\n  return {\n    x: anchor.x + (point.x - anchor.x) / scale,\n    y: anchor.y + (point.y - anchor.y) / scale\n  }\n}\n\nexport function unprojectBounds(\n  bounds: Bounds,\n  anchor: Point,\n  scale: number\n): Bounds {\n  const topLeft = unprojectPoint({ x: bounds.x, y: bounds.y }, anchor, scale)\n  return {\n    x: topLeft.x,\n    y: topLeft.y,\n    width: bounds.width / scale,\n    height: bounds.height / scale\n  }\n}\n","import type { LGraph, RendererType } from '@/lib/litegraph/src/LGraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { snapPoint } from '@/lib/litegraph/src/measure'\nimport type { Point as LGPoint } from '@/lib/litegraph/src/interfaces'\nimport {\n  RENDER_SCALE_FACTOR,\n  getGraphRenderAnchor,\n  unprojectBounds,\n  unprojectPoint\n} from '@/renderer/core/layout/transform/graphRenderTransform'\nimport type { SubgraphInputNode } from '@/lib/litegraph/src/subgraph/SubgraphInputNode'\nimport type { SubgraphOutputNode } from '@/lib/litegraph/src/subgraph/SubgraphOutputNode'\n\ninterface Positioned {\n  pos: LGPoint\n  size: LGPoint\n}\n\n/**\n * One-time legacy normalizer for workflows saved with Vue-scaled coordinates.\n *\n * Detects workflows saved in the old Vue coordinate space (where positions\n * were mutated by 1.2x at runtime) and normalizes them back to canonical\n * LiteGraph coordinates. Runs once per graph, then marks it as normalized.\n *\n * After normalization, rendering applies the 1.2x scale visually via CSS\n * transforms rather than mutating persisted geometry.\n *\n * @param rendererVersion - Override for the renderer version check. When\n *   graph metadata is missing, this value is used as a fallback.\n * @param targetGraph - The graph to normalize.\n */\nexport function ensureCorrectLayoutScale(\n  rendererVersion: RendererType | undefined,\n  graph: LGraph\n): boolean {\n  const currentRenderer = graph.extra.workflowRendererVersion\n  if (currentRenderer === 'Vue-corrected') return false\n\n  const renderer = currentRenderer ?? rendererVersion\n  if (renderer !== 'Vue') return false\n\n  const anchor = getGraphRenderAnchor(graph)\n\n  function applySnap(\n    pos: [number, number],\n    method: 'round' | 'ceil' | 'floor' = 'round'\n  ) {\n    if (LiteGraph.alwaysSnapToGrid) {\n      const snapTo = graph.getSnapToGridSize()\n      if (snapTo) {\n        snapPoint(pos, snapTo, method)\n      }\n    }\n  }\n\n  function normalizedBounds(\n    item: Positioned\n  ): [x: number, y: number, width: number, height: number] {\n    const c = unprojectBounds(\n      {\n        x: item.pos[0],\n        y: item.pos[1],\n        width: item.size[0],\n        height: item.size[1]\n      },\n      anchor,\n      RENDER_SCALE_FACTOR\n    )\n    const pos: [number, number] = [c.x, c.y]\n    const size: [number, number] = [c.width, c.height]\n    applySnap(pos)\n    applySnap(size, 'ceil')\n\n    return [pos[0], pos[1], size[0], size[1]]\n  }\n\n  function normalize(item: Positioned) {\n    const [x, y, width, height] = normalizedBounds(item)\n    item.pos = [x, y]\n    item.size = [width, height]\n  }\n\n  for (const node of graph.nodes) {\n    normalize(node)\n  }\n\n  for (const reroute of graph.reroutes.values()) {\n    const p = unprojectPoint(\n      { x: reroute.pos[0], y: reroute.pos[1] },\n      anchor,\n      RENDER_SCALE_FACTOR\n    )\n    const pos: [number, number] = [p.x, p.y]\n    applySnap(pos)\n    reroute.pos = pos\n  }\n\n  for (const group of graph.groups) {\n    group.boundingRect.set(normalizedBounds(group))\n  }\n\n  if ('inputNode' in graph && 'outputNode' in graph) {\n    for (const ioNode of [\n      graph.inputNode as SubgraphInputNode | null,\n      graph.outputNode as SubgraphOutputNode | null\n    ]) {\n      if (ioNode) normalize(ioNode)\n    }\n  }\n\n  graph.extra.workflowRendererVersion = 'Vue-corrected'\n  return true\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { ComfyMetadataTags } from '@/types/metadataTypes'\nimport type {\n  ComfyMetadata,\n  EbmlElementRange,\n  EbmlTagPosition,\n  TextRange,\n  VInt\n} from '@/types/metadataTypes'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nconst WEBM_SIGNATURE = [0x1a, 0x45, 0xdf, 0xa3]\nconst MAX_READ_BYTES = 2 * 1024 * 1024\nconst EBML_ID = {\n  SIMPLE_TAG: new Uint8Array([0x67, 0xc8]),\n  TAG_NAME: new Uint8Array([0x45, 0xa3]),\n  TAG_VALUE: new Uint8Array([0x44, 0x87])\n}\nconst ASCII = {\n  OPEN_BRACE: 0x7b,\n  NULL: 0,\n  PRINTABLE_MIN: 32,\n  PRINTABLE_MAX: 126\n}\nconst MASK = {\n  MSB: 0x80,\n  ALL_BITS_SET: -1\n}\n\nconst hasWebmSignature = (data: Uint8Array): boolean =>\n  WEBM_SIGNATURE.every((byte, index) => data[index] === byte)\n\nconst readVint = (data: Uint8Array, pos: number): VInt | null => {\n  if (pos >= data.length) return null\n\n  const byte = data[pos]\n\n  // Fast path for common case (1-byte vint)\n  if ((byte & MASK.MSB) === MASK.MSB) {\n    return { value: byte & ~MASK.MSB, length: 1 }\n  }\n\n  const length = findFirstSetBitPosition(byte)\n  if (length === 0 || pos + length > data.length) {\n    return null\n  }\n\n  return {\n    value: calculateVintValue(data, pos, length),\n    length\n  }\n}\n\nconst calculateVintValue = (\n  data: Uint8Array,\n  pos: number,\n  length: number\n): number => {\n  let value = data[pos] & (0xff >> length)\n\n  for (let i = 1; i < length; i++) {\n    value = (value << 8) | data[pos + i]\n  }\n\n  const allBitsSet = Math.pow(2, 7 * length) - 1\n  return value === allBitsSet ? MASK.ALL_BITS_SET : value\n}\n\nconst findFirstSetBitPosition = (byte: number): number => {\n  for (let mask = MASK.MSB, position = 1; mask !== 0; mask >>= 1, position++) {\n    if ((byte & mask) !== 0) return position\n  }\n  return 0\n}\n\nconst matchesId = (data: Uint8Array, pos: number, id: Uint8Array): boolean => {\n  if (pos + id.length > data.length) return false\n\n  for (let i = 0; i < id.length; i++) {\n    if (data[pos + i] !== id[i]) return false\n  }\n\n  return true\n}\n\nconst findNextTag = (\n  data: Uint8Array,\n  pos: number\n): { tagEnd: number; contents: EbmlTagPosition | null } | null => {\n  if (!matchesId(data, pos, EBML_ID.SIMPLE_TAG)) return null\n\n  const tagSize = readVint(data, pos + 2)\n  if (!tagSize || tagSize.value <= 0) return null\n\n  const tagEnd = pos + 2 + tagSize.length + tagSize.value\n  if (tagEnd > data.length) return null\n\n  const contents = extractTagContents(data, pos + 2 + tagSize.length, tagEnd)\n  return { tagEnd, contents }\n}\n\nconst extractTagContents = (\n  data: Uint8Array,\n  start: number,\n  end: number\n): EbmlTagPosition | null => {\n  const nameInfo = findElementsInTag(data, start, end, EBML_ID.TAG_NAME)\n  const valueInfo = findElementsInTag(data, start, end, EBML_ID.TAG_VALUE)\n\n  if (!nameInfo || !valueInfo) return null\n\n  return {\n    name: nameInfo,\n    value: valueInfo\n  }\n}\n\nconst findElementsInTag = (\n  data: Uint8Array,\n  start: number,\n  end: number,\n  id: Uint8Array\n): EbmlElementRange | null => {\n  for (let pos = start; pos < end - 1;) {\n    if (matchesId(data, pos, id)) {\n      const size = readVint(data, pos + 2)\n      if (size && size.value > 0) {\n        const elementPos = pos + 2 + size.length\n        return { pos: elementPos, len: size.value }\n      }\n    }\n    pos++\n  }\n\n  return null\n}\n\nconst processTagContents = (\n  data: Uint8Array,\n  contents: EbmlTagPosition,\n  meta: ComfyMetadata\n) => {\n  try {\n    const name = extractEbmlTagName(data, contents.name.pos, contents.name.len)\n    if (!name) return\n\n    const value = extractEbmlTagValue(\n      data,\n      name,\n      contents.value.pos,\n      contents.value.len\n    )\n    if (value !== null) {\n      meta[name.toLowerCase()] = value\n    }\n  } catch {\n    // Silently continue on error\n  }\n}\n\nconst extractEbmlTagValue = (\n  data: Uint8Array,\n  name: string,\n  pos: number,\n  len: number\n): string | ComfyWorkflowJSON | ComfyApiWorkflow | null => {\n  if (\n    name === ComfyMetadataTags.PROMPT ||\n    name === ComfyMetadataTags.WORKFLOW\n  ) {\n    return readJson(data, pos, len)\n  }\n\n  return ebmlToString(data, pos, len)\n}\n\nconst extractEbmlTagName = (\n  data: Uint8Array,\n  start: number,\n  length: number\n): string | null => {\n  if (length <= 0) return null\n\n  const textRange = findReadableTextRange(data, start, length)\n  if (!textRange) return null\n\n  return new TextDecoder()\n    .decode(data.subarray(textRange.start, textRange.end))\n    .trim()\n}\n\nconst findReadableTextRange = (\n  data: Uint8Array,\n  start: number,\n  length: number\n): TextRange | null => {\n  const isPrintableAscii = (byte: number) =>\n    byte >= ASCII.PRINTABLE_MIN && byte <= ASCII.PRINTABLE_MAX\n\n  let textStart = start\n  while (textStart < start + length && !isPrintableAscii(data[textStart])) {\n    textStart++\n  }\n\n  if (textStart >= start + length) return null\n\n  let textEnd = textStart\n  while (textEnd < start + length && data[textEnd] !== ASCII.NULL) {\n    textEnd++\n  }\n\n  return { start: textStart, end: textEnd }\n}\n\nconst readJson = (\n  data: Uint8Array,\n  start: number,\n  length: number\n): ComfyWorkflowJSON | ComfyApiWorkflow | null => {\n  if (length <= 0) return null\n\n  const nullTerminatorPos = findNullTerminator(data, start, length)\n  const jsonStartPos = findJsonStart(data, start, nullTerminatorPos - start)\n\n  if (jsonStartPos === null) return null\n\n  const jsonText = decodeJsonText(data, jsonStartPos, nullTerminatorPos)\n  return parseJsonText(jsonText)\n}\n\nconst decodeJsonText = (\n  data: Uint8Array,\n  start: number,\n  end: number\n): string => {\n  return new TextDecoder().decode(data.subarray(start, end))\n}\n\nconst parseJsonText = (\n  jsonText: string\n): ComfyWorkflowJSON | ComfyApiWorkflow | null => {\n  const jsonEndPos = findJsonEnd(jsonText)\n  if (jsonEndPos === null) return null\n\n  try {\n    return parseJsonWithNonFinite<ComfyWorkflowJSON | ComfyApiWorkflow>(\n      jsonText.substring(0, jsonEndPos)\n    )\n  } catch {\n    return null\n  }\n}\n\nconst findNullTerminator = (\n  data: Uint8Array,\n  start: number,\n  maxLength: number\n): number => {\n  const end = Math.min(start + maxLength, data.length)\n\n  for (let pos = start; pos < end; pos++) {\n    if (data[pos] === ASCII.NULL) return pos\n  }\n\n  return end\n}\n\nconst findJsonStart = (\n  data: Uint8Array,\n  start: number,\n  length: number\n): number | null => {\n  for (let pos = start; pos < start + length; pos++) {\n    if (data[pos] === ASCII.OPEN_BRACE) return pos\n  }\n\n  return null\n}\n\nconst findJsonEnd = (text: string): number | null => {\n  let braceCount = 1\n  let pos = 1 // Start after the opening brace\n\n  while (braceCount > 0 && pos < text.length) {\n    if (text[pos] === '{') braceCount++\n    if (text[pos] === '}') braceCount--\n    pos++\n  }\n\n  return braceCount === 0 ? pos : null\n}\n\nconst ebmlToString = (\n  data: Uint8Array,\n  start: number,\n  length: number\n): string => {\n  if (length <= 0) return ''\n\n  const endPos = findNullTerminator(data, start, length)\n  return new TextDecoder().decode(data.subarray(start, endPos)).trim()\n}\n\nconst parseMetadata = (data: Uint8Array): ComfyMetadata => {\n  const meta: ComfyMetadata = {}\n\n  for (let pos = 0; pos < data.length - 2;) {\n    const tagInfo = findNextTag(data, pos)\n    if (!tagInfo) {\n      pos++\n      continue\n    }\n\n    const { tagEnd, contents } = tagInfo\n    if (contents) {\n      processTagContents(data, contents, meta)\n    }\n\n    pos = tagEnd\n  }\n\n  return meta\n}\n\nconst parseWebmBuffer = (buffer: ArrayBuffer): ComfyMetadata => {\n  try {\n    const data = new Uint8Array(buffer)\n    if (data.length < 4 || !hasWebmSignature(data)) return {}\n\n    return parseMetadata(data)\n  } catch {\n    return {}\n  }\n}\n\n/**\n * Extracts ComfyUI Workflow metadata from a WebM file\n * @param file - The WebM file to extract metadata from\n */\nexport async function getFromWebmFile(file: File): Promise<ComfyMetadata> {\n  const buffer = await readFileAsArrayBuffer(file, MAX_READ_BYTES)\n  if (!buffer) return {}\n\n  return parseWebmBuffer(buffer)\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { ASCII, ComfyMetadataTags, GltfSizeBytes } from '@/types/metadataTypes'\nimport type {\n  ComfyMetadata,\n  GltfChunkHeader,\n  GltfHeader\n} from '@/types/metadataTypes'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nconst MAX_READ_BYTES = 1 << 20\n\nconst isJsonChunk = (chunk: GltfChunkHeader | null): boolean =>\n  !!chunk && chunk.chunkTypeIdentifier === ASCII.JSON\n\nconst isValidChunkRange = (\n  start: number,\n  length: number,\n  bufferSize: number\n): boolean => start + length <= bufferSize\n\nconst byteArrayToString = (bytes: Uint8Array): string =>\n  new TextDecoder().decode(bytes)\n\nconst parseGltfBinaryHeader = (dataView: DataView): GltfHeader | null => {\n  if (dataView.byteLength < GltfSizeBytes.HEADER) return null\n\n  const magicNumber = dataView.getUint32(0, true)\n  if (magicNumber !== ASCII.GLTF) return null\n\n  return {\n    magicNumber,\n    gltfFormatVersion: dataView.getUint32(4, true),\n    totalLengthBytes: dataView.getUint32(8, true)\n  }\n}\n\nconst parseChunkHeaderAtOffset = (\n  dataView: DataView,\n  offset: number\n): GltfChunkHeader | null => {\n  if (offset + GltfSizeBytes.CHUNK_HEADER > dataView.byteLength) return null\n\n  return {\n    chunkLengthBytes: dataView.getUint32(offset, true),\n    chunkTypeIdentifier: dataView.getUint32(offset + 4, true)\n  }\n}\n\nconst extractJsonChunk = (\n  buffer: ArrayBuffer\n): { start: number; length: number } | null => {\n  const dataView = new DataView(buffer)\n\n  const header = parseGltfBinaryHeader(dataView)\n  if (!header) return null\n\n  const chunkOffset = GltfSizeBytes.HEADER\n  const firstChunk = parseChunkHeaderAtOffset(dataView, chunkOffset)\n  if (!firstChunk || !isJsonChunk(firstChunk)) return null\n\n  const jsonStart = chunkOffset + GltfSizeBytes.CHUNK_HEADER\n  const isValid = isValidChunkRange(\n    jsonStart,\n    firstChunk.chunkLengthBytes,\n    dataView.byteLength\n  )\n  if (!isValid) return null\n\n  return { start: jsonStart, length: firstChunk.chunkLengthBytes }\n}\n\nconst extractJsonChunkData = (buffer: ArrayBuffer): Uint8Array | null => {\n  const chunkLocation = extractJsonChunk(buffer)\n  if (!chunkLocation) return null\n\n  return new Uint8Array(buffer, chunkLocation.start, chunkLocation.length)\n}\n\nconst parseJson = (text: string): unknown => {\n  try {\n    return parseJsonWithNonFinite(text)\n  } catch {\n    return null\n  }\n}\n\nconst isJsonObject = (value: unknown): value is Record<string, unknown> =>\n  typeof value === 'object' && value !== null\n\nconst parseMetadataValue = (\n  value: unknown\n): ComfyWorkflowJSON | ComfyApiWorkflow | undefined => {\n  const parsed = typeof value === 'string' ? parseJson(value) : value\n  return isJsonObject(parsed)\n    ? (parsed as ComfyWorkflowJSON | ComfyApiWorkflow)\n    : undefined\n}\n\nconst extractComfyMetadata = (\n  jsonData: Record<string, unknown>\n): ComfyMetadata => {\n  const metadata: ComfyMetadata = {}\n\n  const { asset } = jsonData\n  if (!isJsonObject(asset) || !isJsonObject(asset.extras)) return metadata\n\n  const { extras } = asset\n\n  if (extras.workflow) {\n    const parsedValue = parseMetadataValue(extras.workflow)\n    if (parsedValue) {\n      metadata[ComfyMetadataTags.WORKFLOW.toLowerCase()] = parsedValue\n    }\n  }\n\n  if (extras.prompt) {\n    const parsedValue = parseMetadataValue(extras.prompt)\n    if (parsedValue) {\n      metadata[ComfyMetadataTags.PROMPT.toLowerCase()] = parsedValue\n    }\n  }\n\n  return metadata\n}\n\nconst processGltfFileBuffer = (buffer: ArrayBuffer): ComfyMetadata => {\n  const jsonChunk = extractJsonChunkData(buffer)\n  if (!jsonChunk) return {}\n\n  const parsedJson = parseJson(byteArrayToString(jsonChunk))\n  if (!isJsonObject(parsedJson)) return {}\n\n  return extractComfyMetadata(parsedJson)\n}\n\n/**\n * Extract ComfyUI metadata from a GLTF binary file (GLB)\n */\nexport async function getGltfBinaryMetadata(\n  file: File\n): Promise<ComfyMetadata> {\n  const buffer = await readFileAsArrayBuffer(file, MAX_READ_BYTES)\n  if (!buffer) return {}\n\n  try {\n    return processGltfFileBuffer(buffer)\n  } catch {\n    return {}\n  }\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { ASCII, ComfyMetadataTags } from '@/types/metadataTypes'\nimport type {\n  ComfyMetadata,\n  IsobmffBoxContentRange\n} from '@/types/metadataTypes'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\n// Set max read high, as atoms are stored near end of file\n// while search is made to be efficient.\nconst MAX_READ_BYTES = 64 * 1024 * 1024\n\nconst BOX_TYPES = {\n  USER_DATA: [0x75, 0x64, 0x74, 0x61],\n  META_DATA: [0x6d, 0x65, 0x74, 0x61],\n  ITEM_LIST: [0x69, 0x6c, 0x73, 0x74],\n  KEYS: [0x6b, 0x65, 0x79, 0x73],\n  DATA: [0x64, 0x61, 0x74, 0x61],\n  MOVIE: [0x6d, 0x6f, 0x6f, 0x76]\n}\nconst SIZES = {\n  HEADER: 8,\n  VERSION: 4,\n  LOCALE: 4,\n  ITEM_MIN: 8\n}\n\nconst bufferMatchesBoxType = (\n  data: Uint8Array,\n  pos: number,\n  boxType: number[]\n): boolean => {\n  if (pos + 4 > data.length) return false\n\n  for (let i = 0; i < 4; i++) {\n    if (data[pos + i] !== boxType[i]) return false\n  }\n  return true\n}\n\nconst readUint32 = (data: Uint8Array, pos: number): number => {\n  if (pos + 4 > data.length) return 0\n  return (\n    (data[pos] << 24) |\n    (data[pos + 1] << 16) |\n    (data[pos + 2] << 8) |\n    data[pos + 3]\n  )\n}\n\nconst findIsobmffBoxByType = (\n  data: Uint8Array,\n  startPos: number,\n  endPos: number,\n  boxType: number[]\n): IsobmffBoxContentRange => {\n  for (let pos = startPos; pos < endPos - 8; pos++) {\n    const size = readUint32(data, pos)\n    if (size < SIZES.ITEM_MIN) continue // Minimum size is 8 bytes\n\n    if (bufferMatchesBoxType(data, pos + 4, boxType))\n      return { start: pos + SIZES.HEADER, end: pos + size } // Skip header\n\n    // If type doesn't match, ensure size is valid before skipping\n    if (pos + size > endPos) return null\n\n    pos += size - 1 // Skip to the next potential box start\n  }\n  return null\n}\n\nconst extractJson = (\n  data: Uint8Array,\n  start: number,\n  end: number\n): ComfyWorkflowJSON | ComfyApiWorkflow | null => {\n  let jsonStart = start\n  while (jsonStart < end && data[jsonStart] !== ASCII.OPEN_BRACE) {\n    jsonStart++\n  }\n  if (jsonStart >= end) return null\n\n  try {\n    const jsonText = new TextDecoder().decode(data.slice(jsonStart, end))\n    return parseJsonWithNonFinite<ComfyWorkflowJSON | ComfyApiWorkflow>(\n      jsonText\n    )\n  } catch {\n    return null\n  }\n}\n\nconst readUtf8String = (data: Uint8Array, start: number, end: number): string =>\n  new TextDecoder().decode(data.slice(start, end))\n\nconst parseKeysBox = (\n  data: Uint8Array,\n  keysBoxStart: number,\n  keysBoxEnd: number\n): Map<number, string> => {\n  const keysMap = new Map<number, string>()\n  let pos = keysBoxStart + 4 // Skip version/flags\n  if (pos + 4 > keysBoxEnd) return keysMap\n\n  const entryCount = readUint32(data, pos)\n  pos += 4\n\n  for (let i = 1; i <= entryCount; i++) {\n    // Keys are 1-indexed\n    if (pos + SIZES.HEADER > keysBoxEnd) break\n\n    const keySize = readUint32(data, pos)\n    pos += SIZES.HEADER\n\n    const keyNameEnd = pos + keySize - SIZES.HEADER\n    if (keySize < SIZES.ITEM_MIN || keyNameEnd > keysBoxEnd) break\n\n    const keyName = readUtf8String(data, pos, keyNameEnd)\n    keysMap.set(i, keyName)\n    pos = keyNameEnd\n  }\n  return keysMap\n}\n\nconst extractMetadataValueFromDataBox = (\n  data: Uint8Array,\n  dataBoxStart: number,\n  dataBoxEnd: number,\n  keyName: string\n): ComfyWorkflowJSON | ComfyApiWorkflow | null => {\n  const valueStart = dataBoxStart + SIZES.VERSION + SIZES.LOCALE\n  if (valueStart >= dataBoxEnd) return null\n\n  const lowerKeyName = keyName.toLowerCase()\n  if (\n    lowerKeyName === ComfyMetadataTags.PROMPT.toLowerCase() ||\n    lowerKeyName === ComfyMetadataTags.WORKFLOW.toLowerCase()\n  ) {\n    return extractJson(data, valueStart, dataBoxEnd)\n  }\n  return null\n}\n\nconst parseIlstItem = (\n  data: Uint8Array,\n  itemStart: number,\n  itemEnd: number,\n  keysMap: Map<number, string>,\n  metadata: ComfyMetadata\n) => {\n  if (itemStart + SIZES.HEADER > itemEnd) return\n\n  const itemIndex = readUint32(data, itemStart + 4)\n  const keyName = keysMap.get(itemIndex)\n  if (!keyName) return\n\n  const dataBox = findIsobmffBoxByType(\n    data,\n    itemStart + SIZES.HEADER,\n    itemEnd,\n    BOX_TYPES.DATA\n  )\n  if (dataBox) {\n    const value = extractMetadataValueFromDataBox(\n      data,\n      dataBox.start,\n      dataBox.end,\n      keyName\n    )\n    if (value !== null) {\n      metadata[keyName.toLowerCase() as keyof ComfyMetadata] = value\n    }\n  }\n}\n\nconst parseIlstBox = (\n  data: Uint8Array,\n  ilstStart: number,\n  ilstEnd: number,\n  keysMap: Map<number, string>,\n  metadata: ComfyMetadata\n) => {\n  let pos = ilstStart\n  while (pos < ilstEnd - SIZES.HEADER) {\n    const itemSize = readUint32(data, pos)\n    if (itemSize <= SIZES.HEADER || pos + itemSize > ilstEnd) break // Invalid item size\n    parseIlstItem(data, pos, pos + itemSize, keysMap, metadata)\n    pos += itemSize\n  }\n}\n\nconst findUserDataBox = (data: Uint8Array): IsobmffBoxContentRange => {\n  // Metadata can be in 'udta' at top level or inside 'moov'\n  const topLevelBox = findIsobmffBoxByType(\n    data,\n    0,\n    data.length,\n    BOX_TYPES.USER_DATA\n  )\n  if (topLevelBox) return topLevelBox\n\n  const moovBox = findIsobmffBoxByType(data, 0, data.length, BOX_TYPES.MOVIE)\n  if (!moovBox) return null\n  return findIsobmffBoxByType(\n    data,\n    moovBox.start,\n    moovBox.end,\n    BOX_TYPES.USER_DATA\n  )\n}\n\nconst parseIsobmffMetadata = (data: Uint8Array): ComfyMetadata => {\n  const metadata: ComfyMetadata = {}\n  const userDataBox = findUserDataBox(data)\n  if (!userDataBox) return metadata\n\n  const metaBox = findIsobmffBoxByType(\n    data,\n    userDataBox.start,\n    userDataBox.end,\n    BOX_TYPES.META_DATA\n  )\n  if (!metaBox) return metadata\n\n  const metaContentStart = metaBox.start + SIZES.VERSION\n  const keysBox = findIsobmffBoxByType(\n    data,\n    metaContentStart,\n    metaBox.end,\n    BOX_TYPES.KEYS\n  )\n  if (!keysBox) return metadata\n\n  const keysMap = parseKeysBox(data, keysBox.start, keysBox.end)\n  if (keysMap.size === 0) return metadata // keys box is empty or failed to parse\n\n  const ilstBox = findIsobmffBoxByType(\n    data,\n    metaContentStart,\n    metaBox.end,\n    BOX_TYPES.ITEM_LIST\n  )\n  if (!ilstBox) return metadata\n\n  parseIlstBox(data, ilstBox.start, ilstBox.end, keysMap, metadata)\n\n  return metadata\n}\n\n/**\n * Extracts ComfyUI Workflow metadata from an ISO Base Media File Format (ISOBMFF) file\n * (e.g., MP4, MOV) by parsing the `udta.meta.keys` and `udta.meta.ilst` boxes.\n * @param file - The file to extract metadata from.\n */\nexport async function getFromIsobmffFile(file: File): Promise<ComfyMetadata> {\n  const buffer = await readFileAsArrayBuffer(file, MAX_READ_BYTES)\n  if (!buffer) return {}\n\n  try {\n    return parseIsobmffMetadata(new Uint8Array(buffer))\n  } catch (e) {\n    console.error('Parser: Error parsing ISOBMFF metadata:', e)\n    return {}\n  }\n}\n","import { isObject } from 'es-toolkit/compat'\n\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nexport function getDataFromJSON(\n  file: File\n): Promise<Record<string, object> | undefined> {\n  return new Promise<Record<string, object> | undefined>((resolve) => {\n    const reader = new FileReader()\n    reader.onload = async () => {\n      try {\n        if (typeof reader.result !== 'string') {\n          resolve(undefined)\n          return\n        }\n        const jsonContent = parseJsonWithNonFinite<Record<string, unknown>>(\n          reader.result\n        )\n        if (jsonContent.templates) {\n          resolve({ templates: jsonContent.templates })\n          return\n        }\n        if (isApiJson(jsonContent)) {\n          resolve({ prompt: jsonContent })\n          return\n        }\n        resolve({ workflow: jsonContent })\n      } catch {\n        resolve(undefined)\n      }\n    }\n    reader.onerror = () => resolve(undefined)\n    reader.onabort = () => resolve(undefined)\n    reader.readAsText(file)\n  })\n}\n\nfunction isApiJson(data: unknown) {\n  return isObject(data) && Object.values(data).every((v) => v.class_type)\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nconst NULL = '\\0'\n\n/** Extracts the JSON text from an `<key>\\0{...}\\0` ID3 text frame. */\nfunction readNullTerminatedJson(header: string, key: string) {\n  const frameStart = header.indexOf(`${key}${NULL}{`)\n  if (frameStart === -1) return undefined\n  const jsonStart = frameStart + key.length + NULL.length\n  const jsonEnd = header.indexOf(`}${NULL}`, jsonStart)\n  if (jsonEnd === -1) return undefined\n  return header.slice(jsonStart, jsonEnd + 1)\n}\n\nexport async function getMp3Metadata(file: File) {\n  const arrayBuffer = await readFileAsArrayBuffer(file)\n  if (!arrayBuffer) return { prompt: undefined, workflow: undefined }\n  //https://stackoverflow.com/questions/7302439/how-can-i-determine-that-a-particular-file-is-in-fact-an-mp3-file#7302482\n  const sig_bytes = new Uint8Array(arrayBuffer, 0, 3)\n  if (\n    (sig_bytes[0] != 0xff || sig_bytes[1] != 0xfb) &&\n    (sig_bytes[0] != 0x49 || sig_bytes[1] != 0x44 || sig_bytes[2] != 0x33)\n  )\n    console.error('Invalid file signature.')\n  let header = ''\n  while (header.length < arrayBuffer.byteLength) {\n    const page = String.fromCharCode(\n      ...new Uint8Array(\n        arrayBuffer,\n        header.length,\n        Math.min(4096, arrayBuffer.byteLength - header.length)\n      )\n    )\n    header += page\n    if (page.match('\\u00ff\\u00fb')) break\n  }\n  let workflow: ComfyWorkflowJSON | undefined\n  let prompt: ComfyApiWorkflow | undefined\n  const prompt_s = readNullTerminatedJson(header, 'prompt')\n  if (prompt_s) {\n    try {\n      prompt = parseJsonWithNonFinite<ComfyApiWorkflow>(prompt_s)\n    } catch (e) {\n      console.error('Failed to parse MP3 prompt metadata', e)\n    }\n  }\n  const workflow_s = readNullTerminatedJson(header, 'workflow')\n  if (workflow_s) {\n    try {\n      workflow = parseJsonWithNonFinite<ComfyWorkflowJSON>(workflow_s)\n    } catch (e) {\n      console.error('Failed to parse MP3 workflow metadata', e)\n    }\n  }\n  return { prompt, workflow }\n}\n","import type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { readFileAsArrayBuffer } from '@/utils/fileUtil'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nconst NULL = '\\0'\n\n/** Extracts the JSON text from a `<key>={...}` Vorbis comment ending at a null byte. */\nfunction readVorbisCommentJson(header: string, key: string) {\n  const commentStart = header.indexOf(`${key}={`)\n  if (commentStart === -1) return undefined\n  const jsonStart = commentStart + key.length + '='.length\n  const firstClose = header.indexOf('}', jsonStart)\n  if (firstClose === -1) return undefined\n  const commentEnd = header.indexOf(NULL, firstClose)\n  if (commentEnd === -1) return undefined\n  return header.slice(jsonStart, commentEnd).match(/\\{.*\\}/)?.[0]\n}\n\nexport async function getOggMetadata(file: File) {\n  const arrayBuffer = await readFileAsArrayBuffer(file)\n  if (!arrayBuffer) return { prompt: undefined, workflow: undefined }\n  const signature = String.fromCharCode(...new Uint8Array(arrayBuffer, 0, 4))\n  if (signature !== 'OggS') console.error('Invalid file signature.')\n  let oggs = 0\n  let header = ''\n  while (header.length < arrayBuffer.byteLength) {\n    const page = String.fromCharCode(\n      ...new Uint8Array(\n        arrayBuffer,\n        header.length,\n        Math.min(4096, arrayBuffer.byteLength - header.length)\n      )\n    )\n    if (page.match('OggS\\u0000')) oggs++\n    header += page\n    if (oggs > 1) break\n  }\n  let workflow: ComfyWorkflowJSON | undefined\n  let prompt: ComfyApiWorkflow | undefined\n  const prompt_s = readVorbisCommentJson(header, 'prompt')\n  if (prompt_s) {\n    try {\n      prompt = parseJsonWithNonFinite<ComfyApiWorkflow>(prompt_s)\n    } catch (e) {\n      console.error('Failed to parse Ogg prompt metadata', e)\n    }\n  }\n  const workflow_s = readVorbisCommentJson(header, 'workflow')\n  if (workflow_s) {\n    try {\n      workflow = parseJsonWithNonFinite<ComfyWorkflowJSON>(workflow_s)\n    } catch (e) {\n      console.error('Failed to parse Ogg workflow metadata', e)\n    }\n  }\n  return { prompt, workflow }\n}\n","import type { ComfyMetadata } from '@/types/metadataTypes'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\nexport async function getSvgMetadata(file: File): Promise<ComfyMetadata> {\n  const text = await file.text()\n  const metadataMatch =\n    /<metadata>\\s*<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>\\s*<\\/metadata>/i.exec(text)\n\n  if (metadataMatch && metadataMatch[1]) {\n    try {\n      return parseJsonWithNonFinite<ComfyMetadata>(metadataMatch[1].trim())\n    } catch (error) {\n      console.error('Error parsing SVG metadata:', error)\n      return {}\n    }\n  }\n\n  return {}\n}\n","import { getFromWebmFile } from '@/scripts/metadata/ebml'\nimport { getGltfBinaryMetadata } from '@/scripts/metadata/gltf'\nimport { getFromIsobmffFile } from '@/scripts/metadata/isobmff'\nimport { getDataFromJSON } from '@/scripts/metadata/json'\nimport { getMp3Metadata } from '@/scripts/metadata/mp3'\nimport { getOggMetadata } from '@/scripts/metadata/ogg'\nimport { getSvgMetadata } from '@/scripts/metadata/svg'\nimport type { ComfyMetadata } from '@/types/metadataTypes'\nimport {\n  getAvifMetadata,\n  getWebpMetadata,\n  getFlacMetadata,\n  getLatentMetadata,\n  getPngMetadata\n} from '@/scripts/pnginfo'\n\nexport async function getWorkflowDataFromFile(\n  file: File\n): Promise<ComfyMetadata | Record<string, string | object> | undefined> {\n  if (file.type === 'image/png') {\n    return await getPngMetadata(file)\n  }\n  if (file.type === 'image/avif') {\n    return await getAvifMetadata(file)\n  }\n  if (file.type === 'image/webp') {\n    const pngInfo = await getWebpMetadata(file)\n    // Support loading workflows from that webp custom node.\n    const workflow = pngInfo.workflow || pngInfo.Workflow\n    const prompt = pngInfo.prompt || pngInfo.Prompt\n    return { workflow, prompt }\n  }\n  if (file.type === 'audio/mpeg') {\n    return await getMp3Metadata(file)\n  }\n  if (file.type === 'audio/ogg') {\n    return await getOggMetadata(file)\n  }\n  if (file.type === 'audio/flac' || file.type === 'audio/x-flac') {\n    const pngInfo = await getFlacMetadata(file)\n    const workflow = pngInfo.workflow || pngInfo.Workflow\n    const prompt = pngInfo.prompt || pngInfo.Prompt\n\n    return { workflow, prompt }\n  }\n  if (file.type === 'video/webm') {\n    return await getFromWebmFile(file)\n  }\n  if (\n    file.name.endsWith('.mp4') ||\n    file.name.endsWith('.mov') ||\n    file.name.endsWith('.m4v') ||\n    file.type === 'video/mp4' ||\n    file.type === 'video/quicktime' ||\n    file.type === 'video/x-m4v'\n  ) {\n    return await getFromIsobmffFile(file)\n  }\n  if (file.type === 'image/svg+xml' || file.name.endsWith('.svg')) {\n    return await getSvgMetadata(file)\n  }\n  if (file.type === 'model/gltf-binary' || file.name.endsWith('.glb')) {\n    return await getGltfBinaryMetadata(file)\n  }\n  if (file.name.endsWith('.latent') || file.name.endsWith('.safetensors')) {\n    return await getLatentMetadata(file)\n  }\n\n  if (file.type === 'application/json' || file.name.endsWith('.json')) {\n    return getDataFromJSON(file)\n  }\n  return\n}\n","// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n/**\n * Utility functions for handling workbench events\n */\n\nfunction activeTextSelection(): Selection | null {\n  const selection = window.getSelection()\n  return selection !== null && !selection.isCollapsed ? selection : null\n}\n\nexport function hasTextSelection(target: EventTarget | null): boolean {\n  if (\n    target instanceof HTMLInputElement ||\n    target instanceof HTMLTextAreaElement\n  ) {\n    if (\n      target.selectionStart !== null &&\n      target.selectionEnd !== null &&\n      target.selectionStart !== target.selectionEnd\n    )\n      return true\n  }\n\n  return activeTextSelection() !== null\n}\n\nfunction rangesOf(selection: Selection): Range[] {\n  return Array.from({ length: selection.rangeCount }, (_, i) =>\n    selection.getRangeAt(i)\n  )\n}\n\n/**\n * Collapse a text selection unless every range lies wholly inside\n * `container`, the way a plain mousedown would before the canvas called\n * `preventDefault()` on it. A copy or paste that follows a click on the graph\n * then reaches the graph instead of the stale selection.\n */\nexport function collapseTextSelectionOutside(container: Element): void {\n  const selection = activeTextSelection()\n  if (\n    selection &&\n    rangesOf(selection).some(\n      (range) =>\n        !container.contains(range.startContainer) ||\n        !container.contains(range.endContainer)\n    )\n  )\n    selection.removeAllRanges()\n}\n\nexport function collapseOutsideSelectionOnPrimaryPointerDown(\n  event: PointerEvent\n): void {\n  if (event.button === 0 && event.target instanceof Element)\n    collapseTextSelectionOutside(event.target)\n}\n\n/**\n * Used by clipboard handlers to determine if copy/paste events should be\n * intercepted for graph operations vs. allowing default browser behavior\n * for text inputs and other UI elements.\n *\n * @param target - The event target to check\n * @returns true if copy paste events will be handled by target\n */\nexport function shouldIgnoreCopyPaste(target: EventTarget | null): boolean {\n  const isTextInput =\n    target instanceof HTMLTextAreaElement ||\n    (target instanceof HTMLElement && target.isContentEditable) ||\n    (target instanceof HTMLInputElement &&\n      ![\n        'button',\n        'checkbox',\n        'file',\n        'hidden',\n        'image',\n        'radio',\n        'range',\n        'reset',\n        'submit'\n      ].includes(target.type))\n  return (\n    isTextInput || useCanvasStore().linearMode || activeTextSelection() !== null\n  )\n}\n","import { useEventListener } from '@vueuse/core'\n\nimport {\n  CANVAS_CLIPBOARD_ID_KEY,\n  CANVAS_CLIPBOARD_KEY\n} from '@/lib/litegraph/src/canvas/clipboardStorage'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport {\n  hasTextSelection,\n  shouldIgnoreCopyPaste\n} from '@/workbench/eventHelpers'\n\nconst metadataHtmlPrefix =\n  '<meta charset=\"utf-8\"><div><span data-comfy-metadata=\"'\nconst legacyMetadataHtmlPrefix =\n  '<meta charset=\"utf-8\"><div><span data-metadata=\"'\nconst metadataHtmlSuffix =\n  '\"></span></div><span style=\"white-space:pre-wrap;\">Text</span>'\nconst chromiumHtmlWrappers = [\n  { before: '', after: '' },\n  { before: \"<meta charset='utf-8'>\", after: '' },\n  {\n    before: '<html>\\r\\n<body>\\r\\n<!--StartFragment-->',\n    after: '<!--EndFragment-->\\r\\n</body>\\r\\n</html>'\n  }\n]\n\nfunction clipboardHtml(base64Data: string): string {\n  return `${metadataHtmlPrefix}${base64Data}${metadataHtmlSuffix}`\n}\n\nfunction between(text: string, before: string, after: string) {\n  if (!text.startsWith(before) || !text.endsWith(after)) return undefined\n  return text.slice(before.length, text.length - after.length)\n}\n\nfunction readMetadata(html: string): string | undefined {\n  return chromiumHtmlWrappers\n    .flatMap(({ before, after }) =>\n      [metadataHtmlPrefix, legacyMetadataHtmlPrefix].map((prefix) =>\n        between(html, before + prefix, metadataHtmlSuffix + after)\n      )\n    )\n    .find((base64Data) => base64Data !== undefined)\n}\n\nconst clipboardByteChunkSize = 0x8000\n\nfunction bytesToBinaryString(bytes: Uint8Array): string {\n  const chunks: string[] = []\n\n  for (\n    let offset = 0;\n    offset < bytes.length;\n    offset += clipboardByteChunkSize\n  ) {\n    chunks.push(\n      String.fromCharCode(\n        ...bytes.subarray(offset, offset + clipboardByteChunkSize)\n      )\n    )\n  }\n\n  return chunks.join('')\n}\n\nfunction encodeClipboardData(data: string): string {\n  return btoa(bytesToBinaryString(new TextEncoder().encode(data)))\n}\n\ntype ClipboardHtmlParse =\n  | { status: 'absent' }\n  | { status: 'unreadable'; cause: unknown }\n  | { status: 'read'; text: string; payload: unknown }\n\nexport function parseClipboardHtml(html: string): ClipboardHtmlParse {\n  const base64Data = readMetadata(html)\n  if (!base64Data) return { status: 'absent' }\n  try {\n    const bytes = Uint8Array.from(atob(base64Data), (c) => c.charCodeAt(0))\n    const text = new TextDecoder().decode(bytes)\n    return { status: 'read', text, payload: JSON.parse(text) }\n  } catch (cause) {\n    return { status: 'unreadable', cause }\n  }\n}\n\n/**\n * Adds a handler on copy that serializes selected nodes to JSON\n */\nexport const useCopy = () => {\n  const canvasStore = useCanvasStore()\n  let keyboardCopyId: string | null = null\n\n  useEventListener(document, 'copy', (e) => {\n    if (shouldIgnoreCopyPaste(e.target)) {\n      // Default system copy\n      if (\n        keyboardCopyId !== null &&\n        hasTextSelection(e.target) &&\n        localStorage.getItem(CANVAS_CLIPBOARD_ID_KEY) === keyboardCopyId\n      ) {\n        localStorage.removeItem(CANVAS_CLIPBOARD_KEY)\n        localStorage.removeItem(CANVAS_CLIPBOARD_ID_KEY)\n        keyboardCopyId = null\n      }\n      return\n    }\n    // copy nodes and clear clipboard\n    const canvas = canvasStore.canvas\n    if (canvas?.selectedItems) {\n      const serializedData = canvas.copyToClipboard()\n      keyboardCopyId = localStorage.getItem(CANVAS_CLIPBOARD_ID_KEY)\n      try {\n        const base64Data = encodeClipboardData(serializedData)\n        // clearData doesn't remove images from clipboard\n        e.clipboardData?.setData('text/html', clipboardHtml(base64Data))\n      } catch (error) {\n        reportError(error, {\n          errorType: 'error_writing_clipboard_metadata',\n          surface: 'graph'\n        })\n      }\n      e.preventDefault()\n      e.stopImmediatePropagation()\n      return false\n    }\n  })\n}\n","import { useEventListener } from '@vueuse/core'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { parseClipboardHtml } from '@/composables/useCopy'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { t } from '@/i18n'\nimport { CANVAS_CLIPBOARD_KEY } from '@/lib/litegraph/src/canvas/clipboardStorage'\nimport type { LGraphCanvas, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { zClipboardItems } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyApp } from '@/types/comfy'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport {\n  createNode,\n  isAudioNode,\n  isImageNode,\n  isSelectOnly,\n  isVideoNode\n} from '@/utils/litegraphUtil'\nimport { shouldIgnoreCopyPaste } from '@/workbench/eventHelpers'\n\nexport function cloneDataTransfer(original: DataTransfer): DataTransfer {\n  const persistent = new DataTransfer()\n\n  // Copy string data\n  for (const type of original.types) {\n    const data = original.getData(type)\n    if (data) {\n      persistent.setData(type, data)\n    }\n  }\n\n  for (const item of original.items) {\n    if (item.kind === 'file') {\n      const file = item.getAsFile()\n      if (file) {\n        persistent.items.add(file)\n      }\n    }\n  }\n\n  // Preserve dropEffect and effectAllowed\n  persistent.dropEffect = original.dropEffect\n  persistent.effectAllowed = original.effectAllowed\n\n  return persistent\n}\n\nfunction pasteClipboardItems(data: DataTransfer): boolean {\n  const parsed = parseClipboardHtml(data.getData('text/html'))\n  if (parsed.status === 'absent') return false\n  if (parsed.status === 'unreadable') {\n    useErrorHandling().toastErrorHandler(parsed.cause)\n    return true\n  }\n\n  const clipboardItems = zClipboardItems.safeParse(parsed.payload)\n  if (!clipboardItems.success) {\n    useErrorHandling().toastErrorHandler(clipboardItems.error)\n    return true\n  }\n\n  try {\n    useCanvasStore().getCanvas()._deserializeItems(clipboardItems.data, {})\n  } catch (err) {\n    useErrorHandling().toastErrorHandler(err)\n  }\n  return true\n}\n\nfunction holdsLatestCanvasCopy(html: string): boolean {\n  const parsed = parseClipboardHtml(html)\n  if (parsed.status !== 'read') return false\n  try {\n    return parsed.text === localStorage.getItem(CANVAS_CLIPBOARD_KEY)\n  } catch {\n    return false\n  }\n}\n\nfunction isWorkflow(\n  value: unknown\n): value is Parameters<ComfyApp['loadGraphData']>[0] {\n  return (\n    typeof value === 'object' &&\n    value !== null &&\n    'version' in value &&\n    (typeof value.version === 'number' || typeof value.version === 'string') &&\n    'nodes' in value &&\n    Array.isArray(value.nodes) &&\n    'extra' in value &&\n    typeof value.extra === 'object' &&\n    value.extra !== null &&\n    !Array.isArray(value.extra)\n  )\n}\n\nfunction pasteItemsOnNode(\n  items: DataTransferItemList,\n  node: LGraphNode | null,\n  contentType: string\n): void {\n  if (!node) return\n\n  const filteredItems = Array.from(items).filter((item) =>\n    item.type.startsWith(contentType)\n  )\n\n  const blob = filteredItems[0]?.getAsFile()\n  if (!blob) return\n\n  node.pasteFile?.(blob)\n  node.pasteFiles?.(\n    Array.from(filteredItems)\n      .map((i) => i.getAsFile())\n      .filter((f) => f !== null)\n  )\n}\n\nexport async function pasteImageNode(\n  canvas: LGraphCanvas,\n  items: DataTransferItemList,\n  imageNode: LGraphNode | null = null\n): Promise<LGraphNode | null> {\n  // No image node selected: add a new one\n  if (!imageNode) {\n    imageNode = await createNode(canvas, 'LoadImage')\n  }\n\n  pasteItemsOnNode(items, imageNode, 'image')\n  return imageNode\n}\n\nexport async function pasteImageNodes(\n  canvas: LGraphCanvas,\n  fileList: File[]\n): Promise<LGraphNode[]> {\n  const nodes: LGraphNode[] = []\n\n  for (const file of fileList) {\n    const transfer = new DataTransfer()\n    transfer.items.add(file)\n    const imageNode = await pasteImageNode(canvas, transfer.items)\n\n    if (imageNode) {\n      nodes.push(imageNode)\n    }\n  }\n\n  return nodes\n}\n\nexport async function pasteAudioNode(\n  canvas: LGraphCanvas,\n  items: DataTransferItemList,\n  audioNode: LGraphNode | null = null\n): Promise<LGraphNode | null> {\n  if (!audioNode) {\n    audioNode = await createNode(canvas, 'LoadAudio')\n  }\n  pasteItemsOnNode(items, audioNode, 'audio')\n  return audioNode\n}\n\nexport async function pasteAudioNodes(\n  canvas: LGraphCanvas,\n  fileList: File[]\n): Promise<LGraphNode[]> {\n  const nodes: LGraphNode[] = []\n\n  for (const file of fileList) {\n    const transfer = new DataTransfer()\n    transfer.items.add(file)\n    const node = await pasteAudioNode(canvas, transfer.items)\n\n    if (node) {\n      nodes.push(node)\n    }\n  }\n\n  return nodes\n}\n\nexport async function pasteVideoNode(\n  canvas: LGraphCanvas,\n  items: DataTransferItemList,\n  videoNode: LGraphNode | null = null\n): Promise<LGraphNode | null> {\n  if (!videoNode) {\n    videoNode = await createNode(canvas, 'LoadVideo')\n  }\n  pasteItemsOnNode(items, videoNode, 'video')\n  return videoNode\n}\n\nexport async function pasteVideoNodes(\n  canvas: LGraphCanvas,\n  fileList: File[]\n): Promise<LGraphNode[]> {\n  const nodes: LGraphNode[] = []\n\n  for (const file of fileList) {\n    const transfer = new DataTransfer()\n    transfer.items.add(file)\n    const node = await pasteVideoNode(canvas, transfer.items)\n\n    if (node) {\n      nodes.push(node)\n    }\n  }\n\n  return nodes\n}\n\n/**\n * Adds a handler on paste that extracts and loads images or workflows from pasted JSON data\n */\nexport const usePaste = () => {\n  const workspaceStore = useWorkspaceStore()\n  const canvasStore = useCanvasStore()\n\n  useEventListener(document, 'paste', async (e) => {\n    // An editor claims the paste it handles by cancelling it. Its target is not\n    // always editable: a caret inside an uneditable chip makes the chip the\n    // target, which shouldIgnoreCopyPaste would hand to the canvas.\n    if (e.defaultPrevented) return\n    if (shouldIgnoreCopyPaste(e.target)) {\n      // Default system copy\n      return\n    }\n    // ctrl+shift+v is used to paste nodes with connections\n    // this is handled by litegraph\n    if (workspaceStore.shiftDown) return\n\n    const { canvas } = canvasStore\n    if (!canvas || isSelectOnly(canvas)) return\n\n    let data: DataTransfer | string | null = e.clipboardData\n    if (!data) {\n      console.error('No clipboard data on clipboard event')\n      return\n    }\n    data = cloneDataTransfer(data)\n\n    const { items } = data\n\n    const currentNode = canvas.current_node\n    const isNodeSelected = currentNode?.is_selected\n\n    const isImageNodeSelected = isNodeSelected && isImageNode(currentNode)\n    const isVideoNodeSelected = isNodeSelected && isVideoNode(currentNode)\n    const isAudioNodeSelected = isNodeSelected && isAudioNode(currentNode)\n\n    const audioNode: LGraphNode | null = isAudioNodeSelected\n      ? currentNode\n      : null\n    const imageNode: LGraphNode | null = isImageNodeSelected\n      ? currentNode\n      : null\n    const videoNode: LGraphNode | null = isVideoNodeSelected\n      ? currentNode\n      : null\n\n    // Look for image paste data\n    for (const item of items) {\n      if (item.type.startsWith('image/')) {\n        await pasteImageNode(canvas, items, imageNode)\n        return\n      } else if (item.type.startsWith('video/')) {\n        await pasteVideoNode(canvas, items, videoNode)\n        return\n      } else if (item.type.startsWith('audio/')) {\n        await pasteAudioNode(canvas, items, audioNode)\n        return\n      }\n    }\n\n    const isMediaNodeSelected =\n      isImageNodeSelected || isVideoNodeSelected || isAudioNodeSelected\n    if (!isMediaNodeSelected && pasteClipboardItems(data)) return\n    const html = data.getData('text/html')\n\n    // No image found. Look for node data\n    data = data.getData('text/plain')\n    let workflow: unknown\n    try {\n      data = data.slice(data.indexOf('{'))\n      workflow = JSON.parse(data)\n    } catch {\n      try {\n        data = data.slice(data.indexOf('workflow\\n'))\n        data = data.slice(data.indexOf('{'))\n        workflow = JSON.parse(data)\n      } catch {\n        workflow = null\n      }\n    }\n\n    if (isWorkflow(workflow)) {\n      await useApp().loadGraphData(workflow)\n    } else {\n      if (\n        (e.target instanceof HTMLTextAreaElement &&\n          e.target.type === 'textarea') ||\n        (e.target instanceof HTMLInputElement && e.target.type === 'text')\n      ) {\n        return\n      }\n\n      // Litegraph default paste\n      if (!isMediaNodeSelected || holdsLatestCanvasCopy(html)) {\n        canvas.pasteFromClipboard()\n      } else {\n        useToast().info(t('toastMessages.nothingToPasteIntoNode'), {\n          duration: 3000\n        })\n      }\n    }\n  })\n}\n","import { useEventListener, useResizeObserver } from '@vueuse/core'\nimport _ from 'es-toolkit/compat'\nimport { reactive, unref, shallowRef } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { part